window.__D("text/likkutei-sichot/c184",{"p":[[1300291063,"משא\"כ דער שכר מצוה של אור הסובב איז ניט שייך צו זאָגן אויף דעם אַז דאָס איז אַן ענין טבעי אין דער עבודה — ווייל לגבי דעם אור איז די עבודה פון נבראים ניט תופס מקום; נאָר דאָס איז אַן ענין נסי וואָס איז ניט מוכרח, עס איז אַן ענין וואָס קומט בדרך מתנה מצד רצונו יתברך⁴⁴.\nאון דאָס איז דער טעם פאַרוואָס „ולמחר לעולם הבא ליטול שכרם\":\nאין עולם הזה איז מאיר בגלוי ממש נאָר דער שכר המוגבל⁴⁵, מצד אור הממלא, און דעריבער איז דער תשלום השכר אין אַן אופן פון „לקבל שכרם\" — די עבודה פון אידן טוט אויף די נתינת השכר, אַזוי אַז עס קומט אָן צו אים בדרך ממילא און ער דאַרף עס נאָר מקבל זיין;\nמשא\"כ „למחר לעולם הבא\", ווען עס וועט מאיר זיין דער שכר הבלתי גבולי (מצד אור הסובב)⁴⁶ — איז דער תשלום השכר אין אַן אופן פון „ליטול שכרם\"⁴⁷, דער שכר קומט ניט בדרך ממילא, נאָר עס איז אַ באַזונדער פעולה פון נתינת (ונטילת) השכר.\n(משיחת ש\"פ ואתחנן תשכ\"ה)",[["","","בשל\"ה שם, שגם לפי הרמב\"ן שכר מצוה מסובב מן המצוה עצמה אלא שבא בדרך סגולה. עיי\"ש. וראה לעיל הערה 40: הכרח אלקי רצוני)."],["44","44","אף שגם אור הסובב נמשך ע\"י עבודת האדם ובאופן שהעבודה היא היא הממשיכה את האור (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091072\" data-slug=\"likkutei-sichot\" data-id=\"1300091072\">לקו\"ש ח\"ד</a> שם. ח\"ט ע' 72. ועוד) — מ\"מ מובן, שמכיון שהמדובר באור הסובב שלמעלה מנבראים, הרי בערך העבודה (המוגבלת) של נברא, הוא ענין של חסד ומתנה (ראה לקו\"ש ח\"ט שם. ועוד)."],["45","45","ראה אגה\"ק סי' ג."],["46","46","ראה בהנסמן בהערה 41. ושם, שזהו (בעיקר) בעולם התחי'. ולהעיר מהגירסא בפרש\"י לע\"י עירובין שם (ד\"ה ולא למחר) ובענף יוסף שם."],["47","47","ע\"פ המבואר באגרות קודש שם, דדוקא בשכר המוגבל שייך העכבה והפסק ח\"ו ע\"י מדת הדין, אבל מה שנותנים מלמעלה בדרך מתנה חסד בלתי מוגבל, אין שייך בו עכבה והפסק של מדת הדין — מובנת השייכות למשנת\"ל (סעיף ו-ז) בפירוש „ליטול שכרם\", שנוטל מעצמו ואין שייך לעכב השכר."]]],[1300291064,"<h3>עקב</h3>\nא. בפרשתנו¹ וואו משה רבינו דערציילט ווי ער איז אַרויף נעמען די לוחות פון דעם אויבערשטן, שטייט כמה פעמים דער לשון „לוחות האבנים\", „לוחות הברית\", ברענגט רש\"י אַראָפּ דעם וואָרט „לחת\" און איז מפרש: לחת כתיב ששתיהם שוות².\nרש\"י איז ניט מציין פון וועלכן פסוק ער איז מעתיק בפירושו דעם וואָרט לחת, נאָר פון דעם אָרט וואו רש\"י האָט אַריינגעשטעלט דעם פירוש — צווישן פירושו אויף פסוק ט און פסוק יח — איז מובן, אַז פירושו איז אויף דעם וואָרט „לחת\" וואָס שטייט צווישן די צוויי פסוקים\n[און היות אַז אין די צווישנדיקע פסוקים ווערט דער וואָרט דערמאָנט אייניקע מאָל — בפסוק יו\"ד „ויתן ה' אלי את שני לוחת האבנים כתובים גו'\", בפסוק יא „ויהי מקץ ארבעים יום וארבעים לילה נתן ה' אלי את שני לחת האבנים לחות הברית\", בפסוק טו „ואפן וארד מן ההר גו' ושני לוחת הברית על שתי ידי\", בפסוק יז „ואתפש בשני הלחת ואשלכם גו' ואשברם לעיניכם\" — דאַרף מען זאָגן, אַז רש\"י מיינט אָדער איינעם פון די פסוקים, אָדער דעם לשון „לוחת\" וואָס שטייט חסר אין די אַלע פסוקים³]\nאָבער ניט אויף די צוויי מאָל „לוחת\" וועלכע שטייען חסר בתחלת פסוק ט: „בעלתי ההרה לקחת לוחת האבנים לוחת הברית גו'\", וואָרום דעם פירוש אויף „לוחת\" זאָגט רש\"י נאָך דעם פירוש אויף די ווערטער „ואשב בהר\" וועלכע שטייען שפעטער אין פסוק ט.\nדאַרף מען פאַרשטיין: דעם פירוש, אַז פון „לחת\" חסר לערנט מען אָפּ אַז „שתיהן שוות\", האָט שוין רש\"י געזאָגט פריער אין פ' תשא אויפן פסוק⁴ „ויתן אל משה ככלתו לדבר אתו בהר סיני שני לחת העדת לחת אבן\" — „לחת כתיב שהיו שתיהן שוות\"⁵; נאָר היות דער פריערדיקער פירוש שטייט בהפסק ריבוי פרשיות בתורה (מער ווי צוויי חומשים), חזר'ט רש\"י איבער דעם פירוש נאָכאַמאָל בפרשתנו⁶, ווי מען געפינט כמה פעמים כיו\"ב בפירושו.\nס'איז אָבער ניט מובן, פאַרוואָס איז עס רש\"י מפרש אויף איינעם פון די (אָדער אַלע) שפעטערדיקע פסוקים (י, יא, טו, יז) און ניט גלייך וואו „לוחת\" חסר שטייט דאָ צום ערשטן מאָל (אין פסוק ט)?",[["1","1","ט, ט ואילך."],["2","2","בתנחומא פרשתנו יו\"ד „אמר רבי חנינא לחת כתיב שלא היו גדולים זה מזה אלא שניהם שוין והיתה פסולת שניהם כאחד\". אמנם שם הוא בנוגע תיבת לחת הנאמרת להלן בלוחות שניות (י, א). ועד\"ז מ\"ש במדרש לק\"ט שם „לוחות שיהו שניהם שוין\" — קאי בלוחות שניות. וראה להלן סעיף ט' והערה 52; 54."],["3","3","ואפילו תיבה זו שבפסוק יז. ואף ששם כתיב „הלחת\", י\"ל דלא איכפת לי' לרש\"י מכיון שאינה מיסוד התיבה."],["4","4","לא, יח."],["5","5","ובתנחומא תשא טז „א\"ר חנניא לחת כתיב לא זה גדול מזה\". ועד\"ז בשמו\"ר פמ\"א, ו (ר' חנינא — כבתנחומא פרשתנו שם)."],["6","6","משא\"כ בפ' תשא לאח\"ז — לב, טו־יט. ועד\"ז שם לד, א־ד; שם, כח־ט (בנוגע לוחות השניות)."]]],[1300291065,"מ'קען ניט זאָגן אַז רש\"י איז דאָס מפרש דוקא בפסוק יא⁷ (אָדער יז) וואו עס פעלן אין וואָרט „לחת\" ביידע ואוי\"ן⁸, אויך דער וא\"ו נאָכן למ\"ד — און ניט אין פסוק ט (און יו\"ד) וואו עס שטייט „לוחת\", מיט אַ וא\"ו נאָכן למ\"ד — וואָרום צום תוכן הפירוש „לחת כתיב ששתיהם שוות\" איז נוגע נאָר דער וא\"ו וואָס נאָכן חי\"ת, וואָס ווען ער איז חסר ווערט דער וואָרט „לחת\" נשתנה פון ל' רבים אויף ל' יחיד, משא\"כ דער וא\"ו וואָס נאָכן למ\"ד איז אין דעם ענין גאָרניט משנה — אויך ווען לוחת כתיב (חסר וא\"ו נאָר נאָכן חי\"ת) קען מען אַרויסלערנען „ששתיהם שוות\"⁹.\nב. נאָכמער: אויב רש\"י דאַרף איבערחזר'ן דעם פירוש (פון פ' תשא) נאָך אַ לענגערן הפסק (צווישן חומש שמות און דברים) — האָט ער דאָס געדאַרפט מקדים זיין נאָך פריער (ניט בפרשתנו, עקב, נאָר) אין פ' ואתחנן¹⁰, וואָס אויך דאָרט שטייט (נאָך די עשרת הדברות) „לחת\" חסר וא\"ו: „ויכתבם על שני לחת אבנים ויתנם אלי\".\nובאמת שטעלט זיך די זעלבע תמי' אפילו בנוגע פירושו בפעם הא' אין ס' שמות — בפ' תשא: אויך דאָרט איז דאָס ניט דעם ערשטן מאָל וואו עס שטייט „לחת\" חסר, נאָר דאָס שטייט שוין פריער אין פ' משפטים¹¹: „ואתנה לך את לחת האבן גו'\", לחת כתיב חסר (ביידע ווי\"ן), פונקט ווי אין פ' תשא — איז פאַרוואָס איז רש\"י דאָס ניט מפרש אין פרשת משפטים, וואו עס שטייט צום ערשטן מאָל לחת חסר, נאָר ער וואַרט ביז פ' תשא¹²?\nג. בפשטות וואָלט מען געקענט פאַרענטפערן ע\"פ הידוע¹³, אַז דער ענין פון מלא וחסר כשלעצמו איז ניט קיין דבר הקשה אין פשוטו של מקרא, וואָס רש\"י זאָל עס מוזן פאַרענטפערן (וכדמוכח דערפון וואָס ע\"פ רוב שטעלט זיך ניט רש\"י אויף מלא וחסר שבכתובים). און דאָס וואָס רש\"י באַוואָרנט עס יע בפרשתנו, איז ווייל אין דעם זעלבן פסוק (יא) איז די תורה משנה בזה אחר זה: „את שני לחת האבנים לחות הברית\" — פריער חסר (לגמרי) און דערנאָך גלייך מלא (מיטן צווייטן וא\"ו). דעריבער איז רש\"י מפרש אַז דער פסוק",[["7","7","כ\"ה גם במשכיל לדוד לפרש\"י — ראה לקמן הערה 14."],["8","8","בדפוסים וכת\"י דפרש\"י זה (ועד\"ז בפרש\"י תשא) — שינויים בהד\"ה דפרש\"י זה: בדפוס ראשון ושני (ועוד) ובכמה כת\"י (שתח\"י), הד\"ה דפרש\"י הוא „לוחות\" (מלא ב' ווי\"ן), בכמה כת\"י (שתח\"י) ודפוסים הד\"ה הוא „לוחת\", ובדפוסים הנפוצים — „לחת\"; וכן יש שינויים בפנים פירושו: בדפוס א' (ועוד) וכמה כת\"י „לוחת כתיב\", בדפוס שני וכמה כת\"י „לחת כתיב\" (כבדפוסים הנפוצים)."],["9","9","וכמ\"ש בס' זכרון כאן (ובפ' תשא ועוד)."],["10","10","ה, יט."],["11","11","כד, יב."],["12","12","לכאורה יש לומר שהדיוק והקושי בהפסוק (בפ' תשא ובפרשתנו) הוא לא (רק) „לחת\" חסר כשלעצמו כ\"א (גם —) לפי שיש סתירה בהכתוב דנאמר „שני\" ואח\"כ „לחת\" דמשמע אחד (כמ\"ש בדבק טוב (ועוד) בפ' תשא שם), משא\"כ בפ' משפטים שלא נאמר „שני\" כ\"א „ואתנה לך את לחת האבן\" (וגם אין ידוע מפסוקים לפנ\"ז דהוי שני לוחות) לכן לא פרש\"י כלום (ולכן לא פירשו גם כאן בפסוק ט, דלא נאמר שם שני לחת). אבל מזה שרש\"י בתשא וכן בפרשתנו לא העתיק בהד\"ה שני לחת, כ\"א „לחת\" לבד, משמע, שבא לפרש „לחת חסר\" כשלעצמו (ובפרט בפרשתנו דנאמר בפסוק ט „לוחות האבנים\" — לא שייך לתרץ כן)."],["13","13","ראה גו\"א לפרש\"י בראשית א, יד. וראה גם משכיל לדוד כאן (ובכ\"מ). וכ\"ה בכמה מפרשי רש\"י. וראה כללי רש\"י (קה\"ת תש\"מ) פי\"ג (בהוצאת תנש\"א — פי\"ד). וש\"נ."]]],[1300291066,"קומט דערמיט מדגיש זיין דעם חסר: „לחת כתיב ששתיהם שוות\"¹⁴.\nאון דערפאַר איז דאָס רש\"י ניט מפרש בפסוק ט בפרשתנו „בעלותי ההרה לקחת לוחת האבנים לוחת הברית\" ווייל דאָרטן איז ביידע מאָל „לוחת\" חסר כתיב; און אויך ניט פריער בפ' ואתחנן (וואו עס שטייט „ויכתבם על שני לחת אבנים\") און אין פ' משפטים (פאַר פ' תשא) — היות אַז אין די ערטער שטייט דער וואָרט בלויז איין מאָל, ס'איז ניטאָ קיין שינוי אין זעלבן פסוק.\nדאָס איז אָבער ניט קיין ביאור מספיק, וואָרום:\nא) אין פ' תשא, כאָטש דאָרט שטייט אין פסוק צוויי מאָל „לחת העדות לחת אבן\", זיינען אָבער ביידע חסר, ובמילא איז ניטאָ קיין שינוי אין פסוק לשם הדגשה — און פונדעסטוועגן איז עס רש\"י יע מפרש דאָרט.\nב) בכל אופן קען מען די שאלה פרעגן בפרשתנו בנוגע די פסוקים עצמם: פאַרוואָס איז דער פסוק משנה ומרמז דעם ענין פון „שתיהם שוות\" דוקא אין דעם שפעטערדיקן פסוק (יא), און ניט אין דעם פריערדיקן פסוק (ט), וואו עס שטייט צוויי מאָל דער זעלבער וואָרט?\n[ועפ\"ז איז מובן, אַז די שאלות הנ\"ל קען מען ניט פאַרענטפערן דערמיט וואָס עס זיינען דאָ כו\"כ דעות ושיטות שונות אין דער מסורה פון חסרות ויתירות¹⁵, והיינו¹⁶ אַז לויט דעת רש\"י איז די מסורה אין פ' תשא באופן אַז ס'שטייט איין מאָל מלא („לחות\") און איין מאָל חסר („לחת\") (ניט¹⁷ ווי לפנינו¹⁸); און בפרשתנו, ווידער, איז שיטת רש\"י אַז (פאַר די ווערטער „ואשב בהר\") שטייט ביידע מאָל „לחת\" חסר\n— וואָרום¹⁹ סייווי בלייבט די שאלה אינעם פסוק גופא (כנ\"ל) — פאַרוואָס איז די תורה משנה דוקא אין פסוק יא (ועד\"ז בפ' תשא) כדי מדגיש זיין „לחת חסר כתיב ששתיהם שוות\", און ניט אין פריערדיקן פסוק ט, וואו עס שטייט דער זעלבער לשון „לוחת האבנים לוחת הברית\"].\nד. וועט מען דאָס פאַרשטיין בהקדם אַ דיוק אין לשון רש\"י בפירושיו על",[["14","14","גם במשכיל לדוד כתב שכוונת רש\"י ל„לחת\" שבפסוק יא. אבל — מפני דהפסוק מיותר (ועד\"ז פי' בפ' תשא). אבל צע\"ק לומר, דיתור כל הפסוק בא רק לדרשא על תיבת „לחת\". ואכ\"מ."],["15","15","ראה לדוגמא מנחת שי ח\"ש כה, ו (וש\"נ). תרומה כה, כב. בלק כג, ט. ועוד."],["16","16","ובפרט דאנן לא בקיאין בחסרות ויתרות — קדושין ל, סע\"א. וכ\"ה ברמ\"א או\"ח סקמ\"ג ס\"ד. וראה נ\"כ שם."],["17","17","וע\"ד פרש\"י ח\"ש ותרומה שם*; דברים (א, יג) — שהוא לא כבמסורה שלנו (ראה מנחת שי שם)."],["18","18","וכ\"ה (כלפנינו) גם במסורה ובמנחת שי תשא שם."],["19","19","נוסף על העיקר שדוחק גדול לומר כן (מבלי כל מקור), מכיון שברש\"י אין רמז ע\"ז*. ובפרט שבמסורה ומנחת שי שאסף מכו\"כ ספרים ונוסחאות לא הביא שינויים בפ' תשא (וכבהערה הקודמת). *) ועד\"ז בפ' נשא ז, א „כלת כתיב\" לגי' דפוס ראשון, שני וכמה כת\"י רש\"י (שתח\"י), וע\"פ פירוש הריב\"א וצידה לדרך בפרש\"י. וראה מנחת שי שם. *) משא\"כ בפרש\"י ח\"ש, תרומה ודברים שם (ועוד) — הרי מפורש כן בפרש\"י (וראה קושיות המפרשים שם. וי\"ל ע\"פ מנחת שי פ' בלק שם. ואכ\"מ)."]]],[1300291067,"התורה בענין חסר (ויתיר), וואָס מען געפינט אין דעם שינויים:\nאַמאָל זאָגט רש\"י „חסר וי\"ו\"²⁰, „חסר כתיב\"²¹ וכיו\"ב²², און בכמה מקומות ברענגט רש\"י בלויז דעם וואָרט ווי ער שטייט געשריבן אין פסוק און זאָגט ניט „חסר וי\"ו\" אָדער „חסר כתיב\" וכיו\"ב²³, וכבפרשתנו²⁴: „לחת כתיב\".\nאון וויבאַלד אַז לשונו של רש\"י איז דאָך מדויק, איז מובן אַז אויך די שינויים הנ\"ל אין ל' רש\"י זיינען בכוונה ובדיוק; ובפרט אַז דאָס זיינען שינויים וועלכע מען געפינט בכו\"כ מקומות בפירושו על התורה, אַמאָל באופן הא' און אַמאָל באופן הב'.\nה. ויש לומר די הסברה אין דעם — ע\"פ תוספת ביאור אין דעם כלל הנ\"ל (ריש סעיף ג), אַז דער שינוי פון חסירות ויתירות כשלעצמו איז ניט קיין שווערקייט אין פשוטו של מקרא — אַזאַ וועלכע רש\"י מוז באַוואָרענען לבן חמש למקרא²⁵ [נאָר — ווען עס איז פאַראַן אַן אַנדער שווערקייט אין פשוטו של מקרא און עס ווערט פאַרענטפערט לויט דעם ביאור אין דעם חסר ויתיר, דאַמאָלס ברענגט עס רש\"י ומבאר²⁶].\nאָבער דער כלל, איז נאָר אין אַ פאַל ווען עס איז ניטאָ קיין קשיא וסתירה אין דעם חסר או יתיר עצמו (עס איז נאָר אַ שאלה פון „מאי טעמא\" חסר או יתיר); משא\"כ אין פאַל ווען מצד תוכן הכתובים האָט דער וואָרט געדאַרפט שטיין בדוקא מלא און ניט חסר (או להיפך) — דעמאָלט שטעלט זיך רש\"י אויף דעם.\nוהטעם: דער שינוי פון מלא וחסר איז ניט ווי אַ באַזונדער ענין אין תורה, וואָס האָט ניט קיין שייכות צום לערנען „פשוטו של מקרא\" (און בלויז בשעת הצורך באַנוצט זיך רש\"י מיט חסר ויתיר אויף צו פאַרענטפערן אַן ענין אין פשש\"מ, בדוגמא ווי ער באַנוצט זיך מיט אַן „אגדה המיישבת דברי המקרא\"²⁷);\nאויך אין פשוטו של מקרא איז מובן אַז מלא און חסר אין אַ וואָרט פון תורה איז ניט סתם אַן ענין אינעם אופן הכתיבה פון דעם וואָרט בתורה, נאָר דאָס איז נוגע צום תוכן הכתיבה והכתוב²⁸. ד. ה. דער שינוי פון מלא או חסר וכיו\"ב",[["20","20","בראשית א, יד. שם, כח. ח\"ש כג, טז. שמות ג, טו. משפטים כג, ב (חסר י'. וראה שם לפנ\"ז: על ריב על רב). אמור כג, מ. נשא ז, יט (חסר יוד). שלח טו, כד (חסר א'). דברים א, יג."],["21","21","ח\"ש כג, י (כתיב חסר). כה, ו. בלק כב, ה."],["22","22","נח ט, יב: נכתב חסר; תולדות כה, כד (וישב לח, כז): חסר (סתם); ויקהל לה, כז: נחסרה אות כו' (אלא שמסיים ג\"כ „והנשאם כתיב\" — כבמקומות שבהערה הבאה)."],["23","23","בראשית א, כא. ו, ב. נח ח, כא. לך יד, יד. וירא יח, א. יט, א. ח\"ש כד, לט. תשא לא, יח*. (נשא ז, א**). דברים ב, לג. ואתחנן ו, ט."],["24","24","ובפ' תשא (אבל להעיר, שבא' מכת\"י רש\"י (שתח\"י) תשא שם: „חסר כתיב\"). *) כ\"ה בדפוס ראשון (ככלתו כתיב). ועוד. וראה לקמן ע' 59 בהרשימה הערה 3. **) ראה לעיל שוה\"ג להערה 17."],["25","25","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151112\" data-slug=\"likkutei-sichot\" data-id=\"1300151112\">וע\"ד</a> הענין ד„ניקוד\" על תיבות, שאין מוכרח לפרשו בפשש\"מ — ראה לקו\"ש חט\"ו ע' 112 ואילך. ס' כללי רש\"י שם פי\"ג (בסופו) (בהוצאת תנש\"א — פי\"ד אות 11 ואילך)."],["26","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181086\" data-slug=\"likkutei-sichot\" data-id=\"1300181086\">לקו\"ש חי\"ח ע' 77</a>. ובכ\"מ."],["27","27","בל' רש\"י בראשית ג, ח."],["28","28","ובפרט בימיהם ש„לא היו הנקודות . . כתובים\", דה„חומשי' שלהם היו כתיקון ס\"ת ממש בלי נקודות כו'\" (ל' אדה\"ז בהל' ת\"ת שלו פ\"א ס\"א ובקו\"א שם סק\"ב. וראה פרישה יו\"ד סע\"ר סק\"ח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161436\" data-slug=\"likkutei-sichot\" data-id=\"1300161436\">לקו\"ש חט\"ז ע' 423</a> והערה 10), הרי נוגע עוד יותר הענין דחסר ומלא להבנת התיבות."]]],[1300291068,"ווייזט אויף אַ שינוי אין דעם תוכן התיבה אָדער הכתוב.\nס'איז נאָר וואָס דער ביאור וטעם, אין וואָס עס דריקט זיך אויס דער חסר (אָדער מלא), איז ניט אַן ענין וואָס פאָדערט זיך אינעם לימוד פון פשוטו של מקרא, נאָר דאָס געהערט צו די אַנדערע אופני לימוד התורה.\nאון דעריבער, בשעת אַז מצד תוכן הכתוב וואָלט געדאַרפט שטיין בדוקא מלא און עס שטייט חסר — ווייל מצד תוכן הכתוב דאַרף אויסקומען אַז דאָרט איז ניטאָ קיין חסרון — מוז רש\"י פאַרענטפערן די קשיא (פון בן חמש למקרא), הלמאי שטייט עס „חסר\".\nו. מהדוגמאות לזה:\nא) אין ערשטן אָרט וואו רש\"י איז מפרש דעם ענין פון „חסר\"²⁹: „יהי מארת ברקיע השמים גו'\", זאָגט רש\"י „חסר וי\"ו כתיב על שהוא יום מארה כו'\":\nדער תוכן פון די פסוקים (וועלכע רעדן וועגן די זאַכן וואָס דער אויבערשטער האָט באַשאַפן בששת ימי בראשית) באַשטייט, אין אַרויסברענגען די מעלה פון די זאַכן וועלכע דער אויבערשטער האָט באַשאַפן; ובפרט ובמיוחד דער תוכן פון בריאת המאורות, ווי דער פסוק איז מסיים דאָרט³⁰ (ובכל מעשה בראשית³¹) „וירא אלקים כי טוב\"³² — האָט דאָך געדאַרפט שטיין מאורות מלא (מיט איין וא\"ו לכה\"פ, ווי בפסוק שלאח\"ז), אויף מדגיש זיין³³ די שלימות שבזה³⁴.\nב) אין פ' נח³⁵, נאָכן מבול, וואו דער פסוק זאָגט „וירח ה' את ריח הניחוח ויאמר ה' אל לבו לא אסף לקלל עוד את האדמה בעבור האדם כי יצר לב האדם רע מנעריו ולא אסף עוד להכות גו'\", איז רש\"י מפרש: „מנעריו כתיב משננער לצאת ממעי אמו ניתן בו יצר הרע\" —\nוויבאַלד דער פסוק גיט דעם טעם אויף „לא אוסיף לקלל עוד\" — „כי יצר לב האדם רע מנעריו\", פאַרוואָס שטייט עס חסר, אַן ענין של חסרון אין „נעוריו\", כאילו אַז „יצר לב האדם\" איז ניט רע ממש „מנעוריו\", נאָר ערשט שפעטער — היפך תוכן הכתוב³⁶?",[["29","29","בראשית א, יד."],["30","30","א, יח. וראה שם א, ד: וירא אלקים את האור כי טוב."],["31","31","א, י (בשייכות ליום ב'); יב; כא; כה."],["32","32","ועוד יותר — בסיום כל מעשה בראשית, נאמר (שם, לא) „והנה טוב מאד\"."],["33","33","וראה באו\"א — גו\"א ומשכיל לדוד לפרש\"י (א, יד)."],["34","34","ואף שבריבוי פעמים לא פירש רש\"י החסר גם במעשה בראשית, וכמו „בקר\" (א, ה)* דכתיב חסר, הרי מובן דגם כאשר מפרש „חסר\" לפי שסותר לתוכן התיבה או הכתוב וכיו\"ב (כנ\"ל בפנים) — היינו רק באם ע\"פ דקדוק צ\"ל מלא, וכמו „מאורות\" ל' רבים (ראה משכיל לדוד שם עד\"ז), משא\"כ „בקר\" וכיו\"ב שנכתב במקרא תמיד חסר. ועד\"ז יש לפרש בשאר הדוגמאות דלקמן בפנים ובהערות. ולהעיר מרש\"י לך טז, ה „כל בינך שבמקרא חסר וזה מלא\". ומזה מוכח, דכ\"מ שפרש\"י „חסר\", אף שי\"ל שמפרשו גם מחמת השינוי מן הרגיל — אין זה כל הטעם, דאל\"כ — הי' כותב כן מפורש, וכבפ' לך שם."],["35","35","ח, כא."],["36","36","ראה משכיל לדוד שם — באו\"א. *) ועד\"ז „אלקים\" בלא ו' (א, א), שבכ\"מ נכתב כן (וגם מובן הוא כאן, ע\"פ פרש\"י שם „לבראותו במדת הדין\"). וכ\"ה בנוגע ל„תהו ובהו וחשך\" (א, ב), דכן נכתב בכ\"מ (ומתאים גם מצד תוכנו)."]]],[1300291069,"ג) עד\"ז געפינט מען ווייטער אין פ' חיי שרה³⁷ „ועפרון ישב\", זאָגט רש\"י „כתיב חסר אותו היום כו'\" — וואָרום אין המשך הכתובים ווערט אַרויסגעבראַכט די מעלה פון (בני חת ו)עפרון, אַז ער האָט מסכים געווען צו (פאַרקויפן, און נאָכמער צו) אַוועקגעבן, די מערת המכפלה צו אברהם פאַר קבורת שרה — פאַרוואָס³⁸ שטייט אין פסוק בתחילת הדיבור וועגן עפרון „ישב\" חסר — אַן ענין של חסרון ביי אים³⁹?\nז. עפ\"ז וועט מען אויך פאַרשטיין דעם חילוק הלשונות אין פרש\"י וואָס אַמאָל זאָגט ער „חסר וי\"ו\" „חסר כתיב\" וכיו\"ב, און אַמאָל ניט:\nווען דער חסר פון פסוק קומט זאָגן אַן ענין פון חסרון אין תוכן התיבה (אָדער הענין), דעמאָלט זאָגט רש\"י „חסר כתיב\" וכיו\"ב;\nבשעת אָבער דער חסר קומט ניט זאָגן אַ חסרון, נאָר אַרויסברענגען אַן אַנדער זאַך, אָדער אַ תוספת הדגשה אין דעם ענין גופא — זאָגט ניט רש\"י „חסר כתיב\" (ווייל דאָ איז ניטאָ קיין חסרון (בפירוש)), נאָר ער איז בלויז מדגיש דעם שינוי פון וואָרט לרמז אויף זיין תוכן וענין מיוחד.\nובדוגמאות הנ\"ל:\nאין דעם ערשטן פירוש אויף „יהי מארת\" זאָגט רש\"י „חסר וי\"ו כתיב על שהוא יום מארה ליפול כו'\", אַז דאָ איז אַן ענין של חסרון אין תיבת מאורות.\nעד\"ז אין פסוק „ועפרון ישב\" זאָגט רש\"י „כתיב חסר\" — ווייל דאָס איז געווען אַן ענין פון חסרון אין עפרונ'ען, אין זיין „ישב\" — „אותו היום מנוהו שוטר עליהם מפני חשיבותו של אברהם שהי' צריך לו עלה לגדולה\", ד. ה. דער פסוק קומט דערמיט אָנדייטן אַז עפרון מצ\"ע איז געווען „חסר\", ער איז ניט געווען אויסגעטיילט אין גדולה צווישן די בני חת, נאָר „מפני חשיבותו של אברהם שהי' צריך לו עלה לגדולה\" — נאָר דאַן האָט זיך אָנגעהויבן זיין „ישב\"⁴⁰.\nמשא\"כ אין פ' נח באַ דעם וואָרט „מנעריו\" זאָגט ניט רש\"י „חסר כתיב\" „חסר וי\"ו\" וכיו\"ב, נאָר „מנעריו כתיב משננער לצאת כו'\". ווייל דאָ איז ניטאָ קיין חסר וחסרון בנוגע „נעריו\", אדרבה — דאָס איז מוסיף אין דעם תוכן הכתוב והטעם — אין דעם לימוד זכות על האדם, אַז וויבאַלד גלייך „משננער לצאת ממעי אמו ניתן בו יצר הרע\" (ניט נאָר מנעוריו⁴¹), ובמילא איז דאָס נאָכמער מחזק הטעם אויף „לא אסף לקלל עוד את האדמה בעבור האדם כי יצר לב האדם רע מנעריו\".\nועד\"ז בעוד כו\"כ מקומות וואו רש\"י זאָגט ניט „חסר כתיב\" איז דאָס מטעם הנ\"ל. ולדוגמא — דעם ערשטן מאָל אין חומש (און נאָר אַ פּאָר פסוקים נאָך זיין פי' „מארת חסר ו' כתיב\") וואו רש\"י איז",[["37","37","כג, י."],["38","38","וכן י\"ל בעוד מקומות שרש\"י מפרש „חסר\". ואכ\"מ."],["39","39","ואף דלהלן שם (כג, טז) פרש\"י חסרונו של עפרון — ה\"ז חידוש בפ\"ע שלמדין מהכתוב שם, ואין זה נוגע להתחלת הענין בנוגע לעפרון — שם מדובר בפשטות בנוגע למעלתו, כבפנים."],["40","40","ועד\"ז הוא התוכן ד„חסר\" בשאר המקומות שבהערה 20־22 — ראה לקמן ע' 58 ואילך."],["41","41","ראה רא\"ם וגו\"א שם."]]],[1300291070,"מפרש אַן ענין פון „חסר\" ניט נוצנדיק דעם לשון „חסר\"⁴²:\nאויפן וואָרט „התנינם\"⁴³, ברענגט רש\"י פון דברי אגדה: „הוא לויתן ובן זוגו שבראם זכר ונקבה והרג את הנקבה ומלחה לצדיקים לע\"ל שאם יפרו וירבו לא יתקיים העולם בפניהם התנינם כתיב\" — און זאָגט ניט „חסר כתיב\" —\nווייל⁴⁴ דאָס וואָס „התנינם כתיב\" מצד דעם וואָס „הרג את הנקבה\" — איז ניט קיין ענין פון „חסרון\" אין בריאתו של הקב\"ה — אדרבה, דורך דעם איז באַוואָרנט געוואָרן קיום העולם (און אויך בשייכות דער נקבה עצמה, איז דאָך „מלחה לצדיקים לע\"ל\")⁴⁵.\nח. עפכ\"ז איז מובן בנדו\"ד אין דעם וואָרט „לחת\":\nרש\"י קומט ניט סתם מפרש זיין פאַרוואָס עס שטייט דער וואָרט „לחת\" חסר, פונקט ווי ער איז ניט מפרש אַנדערע חסרות ויתירות.\nרש\"י איז מפרש נאָר דאָרטן וואו דער פסוק איז מדגיש דעם עילוי שבדבר — און דאָס איז נאָר בפ' תשא ובפרשתנו.\nמשא\"כ אין די פריערדיקע ערטער אין תורה, הן אין פ' משפטים (פאַר פ' תשא) און הן אין פ' ואתחנן (פאַר פרשתנו, עקב), וואו דער פסוק איז ניט אויסן מדגיש זיין מעלת הלוחות, שטעלט זיך רש\"י ניט אויף דעם וואָס לחת חסר כתיב, כדלקמן.\nט. אין פ' תשא⁴ שטייט „ויתן אל משה ככלתו לדבר אתו גו' שני לחת העדת לחת אבן כתבים באצבע אלקים\" — די מעלה גדולה פון די לוחות;\nועד\"ז און נאָכמער בפרשתנו⁴⁶: „ויתן ה' אלי את שני לוחת האבנים כתבים באצבע אלקים ועליהם ככל הדברים אשר דבר ה' עמכם בהר מתוך האש גו'\", ובהמשך לזה⁴⁷ „ויהי מקץ ארבעים יום וארבעים לילה נתן ה' אלי את שני לחת האבנים לחות הברית\" — וואָס דאָס אַלץ איז בהמשך צו⁴⁸ „ובחרב הקצפתם . . בעלתי גו'\", און אַ הקדמה צו דעם אַז⁴⁹ „ויאמר . . קום רד . . ואפן וארד מן ההר גו' ושני לוחת הברית על שתי ידי וארא והנה חטאתם גו' ואתפש בשני הלחת ואשלכם מעל שתי ידי ואשברם לעיניכם\",\nד. ה. משה איז דאָ אויסן צו מפליא זיין דעם גרויסן עילוי פון די לוחות, און אַז ניט קוקנדיק אויף דעם, האָט דער חטא פון די אידן געבראַכט צו שבירתם — „ואשברם לעיניכם\" — האָט דאָך אין די צוויי פסוקים (עכ\"פ) געדאַרפט שטיין ניט „לוחת\" חסר, וואָס ווייזט אויף אַ חסרון, נאָר לוחות מלא.\nאיז רש\"י מפרש ומבאר „לחת כתיב\" — דאָ איז ניטאָ קיין „חסר\" (חסרון) אין דעם ענין, נאָר פאַרקערט — דאָס גופא קומט אויף צו אַרויסברענגען אַן עילוי",[["42","42","ועד\"ז הוא בשאר המקומות שבהערה 23, כדלקמן ע' 58 ואילך."],["43","43","בראשית א, כא."],["44","44","ועד\"ז בפ' לך יד, יד „חניכו כתיב זה אליעזר שחנכו למצות כו'\", מעדיף רש\"י לפרש שהכתוב בא להדגיש המעלה שבענין (בנוגע לאליעזר), ולא ענין של „חסר\" בהתיבה (ובמספר האנשים שהלכו עם אברהם (שברוב עם הדרת גו') — ראה פרש\"י שלאח\"ז שם)."],["45","45","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051019\" data-slug=\"likkutei-sichot\" data-id=\"1300051019\">לקו\"ש ח\"ה ע' 19</a> ואילך ובהערות שם."],["46","46","ט, י."],["47","47","שם, יא."],["48","48","שם, ח־ט."],["49","49","שם, יג; טו־יז."]]],[1300291071,"וואָס איז געווען אין די לוחות, „ששתיהם שוות\"⁵⁰, וואָס דאָס איז נאָכמער מדגיש ווי ס'איז געווען אַ ג־טלעכע זאַך:\nנוסף אויף דעם וואָס בידי אדם איז זייער שווער (אָדער מן הנמנע) צו מצמצם זיין⁵¹ אַז צוויי זאַכן זאָלן זיין בשווה ממש בדיוק⁵² — איז דאָ אַ חידוש באַ די לוחות: אויף די צוויי לוחות זיינען דאָך געווען געשריבן די עשרת הדברות, „חמש (ה)דברות (ה)כתובין על לוח אחד וחמש (ה)כתובין על השני\"⁵³, וואָס אין די חמש דברות הראשונים זיינען געווען⁵⁴ אַ סך מער תיבות ואותיות ווי אין די חמש דברות האחרונות — און אעפ\"כ „שתיהם שוות\", איינער איז ניט גרעסער פון צווייטן!\n[ובפשוטם של דברים — איז דער כתב שעליהם געווען דער זעלבער (בגודל האותיות) אין ביידע לוחות — ניט אַז אויף דעם לוח הא' זיינען די תיבות פון די דברות געווען געשריבן מיט קלענערע אותיות און די דברות אחרונות אויף לוח הב' — מיט גרעסערע אותיות. ולכאורה⁵⁵ אַזוי אויך זיינען דער ריווח והפסק בין התיבות והאותיות געווען גלייך אין ביידע לוחות⁵⁶].\nולהעיר מהנס אין דעם וואָס „כתובים משני עבריהם\", וואָס רש\"י טייטשט⁵⁷ „משני עבריהם היו האותיות נקראות ומעשה נסים הי'\".\nובמילא איז דאָס מתאים צום המשך תוכן הכתוב וואָס קומט אַרויסברענגען דעם עילוי פון די לוחות וואָס דער אויבערשטער האָט געגעבן צו משה; און דערמיט גופא אַ הוספת חומר והתראה אין די „דברי תוכחות\"⁵⁸ וואָס משה האָט זיי געזאָגט און געוואָרנט „זכור אל תשכח גו' ובחרב הקצפתם גו'\"⁵⁹ — דאָס וואָס זיי האָבן גורם געווען צו שבירת הלוחות.\nמשא\"כ אין פ' ואתחנן לפנ\"ז¹⁰, וואו עס שטייט „לחת\" חסר, איז דאָרט דער תוכן המדובר וועגן דעם ענין פון „את הדברים האלה דבר ה' אל כל קהלכם גו' ויכתבם על שני לחת אבנים ויתנם אלי\", אָבער עס רעדט זיך דאָרט ניט וועגן דער מעלה מיוחדת פון די לוחות. ועד\"ז",[["50","50","ועפ\"ז יש להמתיק החילוק בלשונו של רש\"י בפ' תשא „שהיו שתיהן שוות\" ובפרשתנו „ששתיהם שוות\": בפ' תשא המדובר ע\"ד הלוחות עצמן — ויתן אל משה . . שני לחת . . אבן (ופ' עגל ושבירת הלוחות הבאה עי\"ז — בא אח\"כ בהפ' כענין בפ\"ע), לכן מדגיש „שהיו שתיהן שוות\" בנתינתן; משא\"כ בפרשתנו שכל הענין ע\"ד הלוחות ה\"ז רק כפרט בדברי התוכחה — שחטאם גרם שבירת הלוחות, ואין צורך להדגיש שהיו שוות לפני שבירתן, כותב רק „ששתיהם שוות\". ועוד י\"ל. ואכ\"מ."],["51","51","ראה יפ\"ת לשמו\"ר (ובעץ יוסף לתנחומא) שבהערה 5."],["52","52","ואף שלדעת המדרש, כן הי' גם בלוחות שניות שעשה משה (כנ\"ל הערה 2) — י\"ל שלמדו שהי' כן ממ\"ש בהם (תשא לד, א. פרשתנו י, א) „פסל לך שני לחת אבנים כראשונים\", ואין ה\"נ שגם בזה הי' פלא. ואולי כ\"ה גם לדעת רש\"י (ראה גם פרש\"י תשא שם). וראה סה\"ש תש\"ג ע' 123 ואילך ובהנסמן שם."],["53","53","פרש\"י נשא ז, כג „מיסודו של ר' משה הדרשן\". וראה גם פרש\"י שה\"ש ד, ה."],["54","54","בלוחות הראשונות, שבזה מדובר כאן (ועד\"ז בלוחות האחרונות)."],["55","55","אף שהבן חמש (למקרא) רואה בהספרים שלומד (ובספר תורה) שאין הריוח וכו' שווה בכל השורות."],["56","56","ראה ביאור מהרי\"פ לשמו\"ר שם (נדפס בהוספות לשמו\"ר — ווילנא)."],["57","57","תשא לב, טו."],["58","58","ל' רש\"י ר\"פ דברים."],["59","59","פרשתנו ט, ז־ח."]]],[1300291072,"אין פ' משפטים¹¹ „ויאמר ה' אל משה עלה אלי ההרה והי' שם ואתנה לך את לחת האבן והתורה והמצוה אשר כתבתי להורתם\" — איז ער ניט מדגיש מעלת הלוחות.\nיו\"ד. עפ\"ז איז אויך מובן פאַרוואָס רש\"י איז מדייק צו שטעלן זיך אויפן וואָרט „לחת\" וואָס שטייט נאָך פסוק ט, און ניט אויף די צוויי מאָל „לחת\" וועלכע שטייען אין אָנפאַנג פסוק ט „בעלתי ההרה לקחת לוחת האבנים לוחת הברית\":\nדער תוכן הדברים אין די פסוקים יו\"ד־יא איז וועגן די לוחות ווי זיי זיינען געגעבן געוואָרן צו משה'ן — „ויתן ה' אלי\", „ויהי מקץ ארבעים יום גו' נתן ה' אלי\". משא\"כ אין פסוק ט רעדט זיך וועגן דעם ווי משה איז אַרויף לקבל הלוחות, ד. ה. ווי די לוחות זיינען נאָך געווען ביים אויבערשטן.\nדער דיוק והדגשה בגודל מעלת הלוחות (כדי צוצוגעבן האַרבקייט אין די דברי תוכחה צו די אידן אויף שבירתם), איז (ניט בעת זיי זיינען נאָך געווען ביים אויבערשטן, „בעלתי ההרה לקחת לוחת האבנים לוחת הברית\", נאָר דוקא) ווען זיי זיינען געקומען בידי משה אויף צו געבן די אידן; אַז (אויך) ווי דער אויבערשטער האָט זיי געגעבן משה'ן זיינען זיי געווען אינגאַנצן אַ העכערע זאַך — אַ זאַך פון „אלקים\" („כתובים באצבע אלקים\" וכו') ניט ווי נבראים.\nיא. עפ\"ז יש לבאר (ביינה של תורה עכ\"פ) נאָך אַן ענין: דער וואָרט „לחת\" חסר אין פסוק יא שטייט ביחס די אבנים, „לחת האבנים\", דער וואָרט לוחות שלאח\"ז שטייט מלא ביחס לברית — „לחות הברית\".\nולכאורה, די מעלה אין די לוחות וואָס זיי זיינען געגעבן געוואָרן פון אויבערשטן און „כתובים באצבע אלקים\" איז דאָך בעיקר אין דעם (ומצד דעם) וואָס זיי זיינען „לחות הברית אשר כרת ה' עמכם\"⁶⁰, דער ברית צווישן דעם אויבערשטן מיט אידן, ניט אין דעם וואָס זיי זיינען (גשמיות'דיקע) „אבנים\", האָט לכאו' געדאַרפט שטיין פאַרקערט (בפסוק יא), „לחות האבנים\" מלא און „לחת הברית\" חסר — „לחת כתיב ששתיהם שוות\", בכדי צו מדגיש זיין ביי לוחות הברית די מעלה פון זייער פאַרבונד מיט „אלקים\"?\nוע\"פ הנ\"ל איז דאָס מובן, וואָרום דער עיקר הדגשה דאָ איז ניט אויף דעם תוכן רוחני אַז די לוחות הברית זיינען אַן ענין אלקי, נאָר אַז אויך די גשמיות פון די לוחות, דאָס וואָס זיי זיינען „לחת האבנים\" (וואָס אין דעם איז געווען די שבירה, „ואשברם לעיניכם\") איז אַן ענין אלקי, עד כ\"כ אַז „שתיהם שוות\" —\nביז אַז אין דעם זיינען געווען צוויי הפכים: שתיהם שוות, כאָטש איין לוח האָט געהאַט אַ סך מער אותיות ותיבות פון דעם צווייטן (בגודל אחד) — אעפ\"כ „שתיהם שוות\".\n(משיחות ש\"פ עקב וש\"פ ראה תשמ\"ג)",[["60","60","שם, ט."]]],[1300291073,"<h3>הוספה</h3>\nלשלימות הענין המבואר בהשיחה (ס\"ז) שרק בענין של חסרון כותב רש\"י תיבת „חסר\" — מובאים בזה המקומות שבהם פירש רש\"י את הטעם דחסרות, על סדר הכתובים:\nא) בראשית א, יד: „יהי מארת — חסר וי\"ו כתיב, על שהוא יום מארה כו'\" — ענין של חסרון (כבפנים ס\"ז).\nב) בראשית א, כח: „וכבשה — חסר וי\"ו, ללמדך שהזכר כובש את הנקבה שלא תהא יצאנית כו'\", כי דעתה קלה ותוכל להנזק (משא\"כ הזכר) — ענין של חסרון.\nג) בראשית א, כא: „התנינם — שבראם זכר ונקבה והרג את הנקבה כו' שאם יפרו וירבו לא יתקיים העולם בפניהם, התנינם כתיב\" — ענין של מעלה (כבפנים ס\"ז).\nד) בראשית ו, ב: „כי טבת הנה — א\"ר יודן טבת כתיב, כשהיו מטיבין כו' גדול נכנס כו'\". אף שלכאורה מדובר כאן אודות ענין של חסרון — הרי: (1) זהו לשונו של ר' יודן, ולא לשונו של רש\"י. (2) כאשר „ויראו בני האלקים גו'\" — לא היו בחסרון [וא\"כ, הרי זו מעלה הכי גדולה — שעד שנכנס גדול כו', כי צנועות היו (ראה פרש\"י חיי שרה כד, טז), ולכן מוכרח רש\"י לומר כן ע\"פ פשש\"מ, ולא לכתוב „חסר\" — ושלא היו צנועות], אלא שידעו שסופן לא טוב. (3) גם שמו „יודן\" — חסר ה\"א כתיב, ואם ידגיש חסר כתיב הרי זה היפך הכבוד כו'.\nה) נח ח, כא: „מנעריו — מנעריו כתיב, משננער לצאת ממעי אמו ניתן בו יצה\"ר\". וזהו ענין של מעלה — לימוד זכות על האדם (כבפנים ס\"ז).\nו) נח ט, יב: „לדרת עולם — נכתב חסר, שיש דורות שלא הוצרכו לאות לפי שצדיקים גמורים היו כו'\", חסרון ב„(ל)דרת עולם\", שחסר בהם דורו של חזקי' כו'.\nז) לך לך יד, יד: „חניכו — חניכו כתיב, זה אליעזר שחנכו למצות כו'\" — ענין של מעלה (ראה הערה<sup data-n=\"44\">44</sup>.\nח) וירא יח, א: „והוא ישב פתח האוהל כחום היום — ישב כתיב כו' סימן לבניך שעתיד אני להתייצב בעדת הדיינין והן יושבין כו'\" — ענין של מעלה שמדגיש מעלתו וכבודו של אברהם, וכבודם של בנ\"י.\nט) וירא יט, א: „ולוט ישב — ישב כתיב, אותו היום מינוהו שופט עליהם\" — ענין של מעלה, כי כל הנהגותיהם (של אנשי סדום) עד עתה אינן באשמתו כלל.\nי) חיי שרה כג, י: „ועפרון ישב — כתיב חסר, אותו היום מינוהו שוטר כו'\" — ענין של חסרון, מכיון שלולי שאברהם הי' צריך לו, לא הי' ראוי לזה (כבפנים ס\"ז).\nיא) חיי שרה כג, טז: „וישקול אברהם לעפרן — חסר וי\"ו, לפי שאמר הרבה ואפילו מעט לא עשה כו'\" — ענין של חסרון.\nיב) חיי שרה כד, לט: „אלי לא תלך האשה — אלי כתיב, בת היתה לו לאליעזר, והי' מחזר למצוא עילה שיאמר לו אברהם לפנות אליו להשיאו בתו כו'\" — ענין של\n---"],[1300291074,"מעלה ביחס לאליעזר¹ ובתו, שלולי חטאו של „חם\" [שבזה נעשה עבד — „ארור\", ולכן „אין ארור מדבק בברוך\"] ראויים הם ליצחק.\nיג) חיי שרה כה, ו: „הפילגשם — חסר כתיב², שלא היתה אלא פלגש אחת כו'\" — חסרון הכי בולט, שאין ב„פלגשים\" (לשון רבים) אלא אחת.\nיד) תולדות כה, כד: „והנה תומם³ — חסר כו' אחד צדיק ואחד רשע\" — ענין של חסרון.\nטו) וישב לח, כז: „תאומים — מלא, ולהלן תומים חסר לפי שהאחד רשע כו'\" (כנ\"ל יד).\nטז) שמות ג, טו: „זה שמי לעלם — חסר וי\"ו, לומר העלימהו שלא יקרא ככתבו\" — חסרון הכי בולט.\nיז) משפטים כג, ב: „לא תענה על ריב — על רב, שאין חולקין על מופלא שבב\"ד כו'\" — ענין של מעלה [ורק בסיום פירושו כותב רש\"י מהיכן לומדים זאת: „לפי שהוא חסר יו\"ד דרשו כן\"].\nיח) כי תשא לא, יח: „ככלתו — ככלתו כתיב⁴ . . ככלה לחתן כו'\" — ענין של מעלה ויתרון בנתינת התורה⁵.\nיט) שם: „לחת — לחת כתיב, שהיו שתיהן שוות\" — ענין של מעלה (כבפנים ס\"ח ואילך).\nכ) ויקהל לה, כז: „והנשאם — לפי שנתעצלו ממלאכתם נחסרה אות משמם\" ענין של חסרון.\nכא) אמור כג, מ: „כפת תמרים — חסר וי\"ו, למד שאינה אלא אחת\" — חסרון הכי בולט, שאין ב„כפות\" אלא אחת.\n[כא (ב) נשא ז, א: „כלות משה — כלת כתיב⁶ יום הקמת המשכן היו ישראל ככלה הנכנסת לחופה\" — ענין של מעלה ושלימות בהקמת המשכן עבור ישראל].\nכב) נשא ז, יט: „הקרב את קרבנו — חסר יו\"ד, שהוא משמע הקרב לשון ציווי כו'\" — ענין של חסרון, מכיון שהי' כאן ענין של ערעור, שלכן הוצרך לציווי מיוחד.\nכג) שלח טו, כד: „לחטת — חסר א', שאינו כשאר חטאות, שכל חטאות שבתורה הבאות עם עולה החטאת קודמת כו' וזו עולה קודמת לחטאת\" — חסרון בחטאת זו לגבי שאר חטאות.",[["1","1","ועפ\"ז מובן (בפשטות) למה סיפר זה אליעזר."],["2","2","וראה לעיל הערה 17; 19 — בשוה\"ג."],["3","3","להעיר, ש„תומם\" — חסר א' וגם יו\"ד, שהוא דוקא סימן לרבים. וצ\"ע בפרש\"י."],["4","4","כ\"ה בדפוס ראשון ושני וכמה כת\"י (שתח\"י). ובדפוסים שלפנינו „ככלתו כתיב חסר\"."],["5","5","דהטעם שברש\"י „שלא הי' יכול ללמוד כולה בזמן מועט כזה\" — אינו כלל בהתיבה."],["6","6","לגי' ופי' המפרשים הנ\"ל שוה\"ג להערה 17."]]],[1300291075,"כד) בלק כב, ה: „והוא ישב ממלי — חסר כתיב, קרובים הם להכריתני כו'\", ותחסר כל מציאותו — ענין של חסרון ביחס לבלק.\nכה) דברים א, יג: „ואשמם בראשיכם — חסר יו\"ד², לומר שאשמותיהם של ישראל כו'\" — ענין דגדלות („ואשימם בראשיכם\") והפכו („ואשמם חסר יו\"ד — אשמותיהם כו'\").\nכו) דברים ב, לג: „ואת בנו — בנו כתיב, שהי' לו בן גבור כמותו\" — תוספת הדגשה בדמיון בנו אליו שהי' גבור כמותו (ומעלה בבנ\"י, שמ\"מ „ונך אותו ואת בנו\").\nכז) ואתחנן ו, ט: „מזזות — מזזות כתיב, שאין צריך אלא אחת\" — מעלה במזוזה, שאין צורך במזוזה נוספת על פתח זה (ראה באר מים חיים, משכיל לדוד. ועוד), מכיון שמזוזה אחת על הפתח פועלת פעולתה בשלימות.\nכח) עקב ט, יא: „לחת כתיב ששתיהן שוות\", ענין של מעלה (כבפנים ס\"ח ואילך).\nועוד יש לומר — בכמה מהנ\"ל, ואכ\"מ.\n---"],[1300291076,"<h3>עקב ב</h3>\nא. אין סוף הלכות מזוזה¹ זאגט דער רמב״ם, וז״ל:\nחייב אדם להזהר במזוזה מפני שהיא חובת הכל תמיד. וכל זמן שיכנס ויצא יפגע² ביחוד השם שמו של הקדוש ב״ה ויזכור אהבתו ויעור משנתו ושגיותיו בהבלי הזמן³. וידע שאין דבר העומד לעולם ולעולמי עולמים⁴ אלא ידיעת צור העולם ומיד הוא חוזר לדעתו והולך בדרכי מישרים. אמרו חכמים הראשונים⁵ כל מי שיש לו תפילין בראשו ובזרועו⁶ וציצית בבגדו ומזוזה בפתחו מוחזק הוא⁷ שלא יחטא שהרי יש לו מזכירין רבים והן הם המלאכים שמצילין אותו מלחטוא שנאמר⁸ חונה מלאך ה׳ סביב ליראיו ויחלצם. בריך רחמנא דסייען.\nדארף מען פארשטיין: פארוואס ברענגט דער רמב״ם דעם מאמר „כל מי שיש לו תפילין כו׳ וציצית כו׳ ומזוזה כו׳“ דא אין הלכות מזוזה⁹, און ניט פריער אין הלכות תפילין¹⁰ (די ערשטע מצוה וואס ווערט דערמאנט אין דעם מאמר)? עכ״פ — אויך דארטען?\nאון אויב דער רמב״ם וויל ברענגען דעם מאמר נאכדעם ווי ער זאגט די הלכות פון אלע דריי מצות — האט ער דאס געדארפט ברענגען שפעטער, אין הלכות ציצית (וואס קומט נאך די אנדערע צוויי הלכות)?\nובפרט אז דער ענין הזכירה שטייט מפורש אין תורה¹¹ ביי מצות ציצית, „וראיתם אותו וזכרתם את כל מצות ה׳“¹² (ניט בנוגע צו (תפילין ו)מזוזה) — און ווי דער רמב״ם עצמו ברענגט דאס אראפ בסוף הל׳ ציצית — האט ער דארט (בסוף הל׳ ציצית) געדארפט ברענגען (אויך) דעם מאמר וועגן די „מזכירין רבים“?\nנאכמער: דער מקור פון דעם מאמר „כל מי שיש לו תפילין בראשו כו׳“ איז",[["1","1","פ״ו הי״ג."],["2","2","ראה מנחות לג, ריש ע״ב „כדי שיפגע במזוזה מיד“. וי״ל שלכן הקדים הרמב״ם „כל זמן שיכנס (לפני) ויצא“ — דלא כבכתוב (תהלים קכא, ח) „ה׳ ישמור צאתך ובואך“ (וכהובא בגמ׳ ע״ז יא, א. זח״ג רסג, ב. וכן סדרם בשו״ע בהלכה — ראה רמ״א יו״ד סרפ״ה ס״ב. ועוד). ולהעיר מתוד״ה יכנס פסחים ב, א."],["3","3","להעיר מרמב״ם הל׳ תשובה פ״ג ה״ד."],["4","4","להעיר מרמב״ם סוף הל׳ שמיטה ויובל (פי״ג הי״ג בסופה)."],["5","5","מנחות מג, ב (כדלקמן בפנים)."],["6","6","לפנינו במנחות „תפילין בראשו ותפילין בזרועו“. וכ״ה בע״י ודק״ס שם (וכ״ה בע״ז ג, ב). ובכ״מ בילקוט ליתא תיבת „תפילין“ עוה״פ — ראה דק״ס שם. וכן ליתא בהל׳ ציצית להרי״ף בסופן ובהלכות קטנות להרא״ש קרוב לסופן. סמ״ג מ״ע ג (בסופה). כג (בסופה). ובטור או״ח סו״ס כד; יו״ד סרפ״ה. ועוד. וראה לקמן הערה 25."],["7","7","בגמ׳ „הכל בחיזוק שלא יחטא“ (וראה שינויי הלשונות בסמ״ג שבהערה הקודמת). ברי״ף ורא״ש שם: מוחזק אני בו שלא יחטא. בטור יו״ד שם הוא כברמב״ם, ובטור או״ח שם (וכ״ה בדק״ס שם מילקוט כ״י) „מובטח לו שלא יחטא“."],["8","8","תהלים לד, ח."],["9","9","ולהעיר שגם בסמ״ג הובא במצות מזוזה ולא בציצית, וגם לא בתפילין (אלא שבמצות „ואהבת“ הביאו בקשר למצות תפילין)."],["10","10","ראה שם פ״ד הכ״ה."],["11","11","ס״פ שלח."],["12","12","ולהעיר מזח״ג שם (בנוגע למזוזה) „דלא ינשי ב״נ . . כגוונא דציצית . . וראיתם כו׳“."]]],[1300291077,"טאקע אין (מס׳ מנחות¹³ — אין) דער סוגיא וועגן מצות ציצית, און אזוי אויך אין רי״ף (און רא״ש¹⁴) ווערט דער מאמר געבראכט ב(סוף) הל׳ ציצית¹⁵ — פארוואס ברענגט עס דער רמב״ם (ניט אין הלכות ציצית, נאר) אין הל׳ מזוזה¹⁶?\nב. אויך דארף מען פארשטיין דעם שינוי אין לשון הרמב״ם לגבי לשון הגמרא — וז״ל הגמרא:\nכל שיש לו תפילין בראשו ותפילין בזרועו וציצית בבגדו ומזוזה בפתחו הכל בחיזוק שלא יחטא שנאמר¹⁷ והחוט המשולש לא במהרה ינתק. ואומר⁸ חונה מלאך ה׳ סביב ליראיו ויחלצם.\nהיינו: דער רמב״ם איז (א) משמיט (די ראי׳ פון) דעם ערשטן פסוק וואס די גמרא ברענגט „שנאמר והחוט המשולש לא במהרה ינתק“, און איז (ב) מוסיף „שהרי יש לו מזכירין רבים והן הם המלאכים שמצילין אותו מלחטוא“.\nדי הוספה פון רמב״ם יש לבאר בפשטות, אז דער רמב״ם וויל מוסיף זיין ביאור¹⁸ אין דברי הש״ס (כדרך הרמב״ם, ובכלל — כדרכן של בתראי לגבי קדמאי¹⁹); עס איז אבער ניט מובן פארוואס איז דער רמב״ם משמיט אן ענין וואס ווערט געבראכט אין ש״ס, ובפרט אז דאס שטייט בש״ס אלס דער ערשטער ענין?\nלכאורה וואלט מען אויף דעם געקענט ענטפערן: לויט שיטת הרמב״ם זיינען תפילין של יד ותפילין של ראש צוויי באזונדערע מצות²⁰, ביז אז דער רמב״ם רעכנט זיי אלס צוויי מצות אין מנין תרי״ג מצות²¹ — און דעריבער איז ניט מתאים צו ברענגען דעם פסוק „והחוט המשולש²² לא במהרה ינתק“²³, וויבאלד אז לדעת הרמב״ם זיינען עס (ניט דריי מצות, נאר) פיר מצות.\nס׳איז אבער ניט מסתבר אז מטעם זה איז עס דער רמב״ם משמיט: א) אפילו מצד דעם וואס דאס זיינען פיר מצות, איז די הוספה פון דער פערטער מצוה ניט גורע פון דער מעלה פון „והחוט המשולש לא במהרה ינתק“²⁴ (יש בכלל",[["13","13","כנ״ל הערה 5."],["14","14","ג׳ עמודי ההוראה בשו״ע — הרמב״ם רי״ף ורא״ש (הב״י בהקדמתו להב״י)."],["15","15","וכן הובא בטור או״ח סוף הל׳ ציצית סכ״ד. וביו״ד הל׳ מזוזה (סרפ״ה) הביא הענין (ולא הפסוקים). וראה לקמן הערה 46."],["16","16","ודוחק גדול לומר שהרמב״ם לא כתבו בהל׳ ציצית כי אז הוי אמינא דעיקר מה שמצילו היא מצות ציצית „שהרי היא לבדה מסבבת את האדם מד׳ פינותיו“ (ל׳ הלבוש או״ח סו״ס כד (הובא בפרישה שם) — בהטעם שבגמ׳ הוצרך להביא גם הפסוק „והחוט המשולש גו׳“)."],["17","17","קהלת ד, יב."],["18","18","ועד״ז יש לומר בשאר השינויים (קלים) הנ״ל הערה 7, ואולי י״ל שכן היתה גירסתו בגמ׳."],["19","19","ראה יד מלאכי כללי הרמב״ם אות כד ועוד (ע״פ ב״י לטיו״ד סר״א ד״ה ומ״ש ואף אם תטבול)."],["20","20","הל׳ תפילין פ״ד ה״ד."],["21","21","מ״ע יב־יג. וכ״ה גם בהכותרת להל׳ תפילין."],["22","22","ראה ב״י לטור או״ח סו״ס כד „ופי׳ רש״י והחוט המשולש תפלין ציצית ומזוזה כלומר דתפילין דראש ודזרוע לא חשיבי אלא כחד“."],["23","23","להעיר שבמנחות שם בא בהמשך להמאמר לפנ״ז „חביבין ישראל שסיבבן הקב״ה במצות תפילין בראשיהן ותפילין בזרועותיהן כו׳“, שמונה (ראה רגמ״ה ופרש״י שם) תפילין של יד ושל ראש לשתי מצות (ומונה ד׳ ציציות לד׳ מצות), ומסיים „ועליהן אמר דוד שבע כו׳“ — וכ״ה בתוספתא סוף ברכות. ספרי ס״פ ואתחנן — ומשמע לכאורה דלר״א בן יעקב שמביא הכתוב „והחוט המשולש גו׳“ הוא דלא כהברייתא לפנ״ז כ״א חושב תפילין של ראש ושל יד למצוה אחת (כמו שחושב ד׳ ציצית למצוה אחת). וראה לקמן הערה 25."],["24","24","אבל י״ל שאז הי׳ מקום לומר, שאינו מוכרח גם מזוזה לענין זה, כיון שגם בלאה״כ הוי ג׳. ולהעיר שבכד הקמח (לרבינו בחיי) בסופו (בהוצאת שעוועל"]]],[1300291078,"מאתיים מנה). ב) סו״ס אויך לדעת הרמב״ם זיינען דא פאראן דריי סוגי מצות — תפילין (של ראש ושל יד)²⁵, ציצית און מזוזה²⁶.\nג. וי״ל אז מען קען דאס פארשטיין בהקדים לבאר וואס ביי מזוזה איז דער רמב״ם מדייק צו זאגן „חייב אדם להזהר במזוזה“ — אנדערש ווי ביי ציצית²⁷, וואו ער זאגט²⁸ „(לעולם יהא אדם) זהיר במצות ציצית שהרי הכתוב שקלה ותלה²⁹ בה כל המצות כולן שנאמר¹¹ וראיתם אותו וזכרתם את כל מצות ה׳“.\nלכאורה יש לומר: דאס וואס דער רמב״ם זאגט „חייב אדם להזהר במזוזה מפני שהיא חובת הכל תמיד“, איז כוונתו, אז כאטש מזוזה איז א „מצוה שאינה חובה על האדם אלא דומין לרשות . . שאין אדם חייב לשכון בבית החייב במזוזה כדי שיעשה מזוזה אלא אם רצה לשכון כל ימיו באהל או בספינה ישב“³⁰ — פונדעסטוועגן דארף א איד זיך משתדל זיין אוועקצושטעלן זיך אין א מצב אז ער זאל יע זיין מחוייב אין דער מצוה³¹ — ער זאל האבן א בית, א חדר צו קענען מקיים זיין מצות מזוזה³²; און וויבאלד אז די כוונה אין רמב״ם איז די השתדלות ער זאל זיך צוברענגען לידי חיוב מזוזה (וואס די השתדלות איז א פעולה אין אן ענין של רשות), זאגט דער רמב״ם דעם לשון „חייב אדם להזהר במזוזה“, ניט „מצות מזוזה“.\n[ועפ״ז יומתק³³ וואס ביי ציצית זאגט דער רמב״ם „לעולם יהא אדם זהיר במצות ציצית“: ביי ציצית קומט דאך די הלכה „לעולם יהא אדם זהיר במצות ציצית“ נאכדעם ווי דער רמב״ם האט געזאגט אין דער פריערדיקער הלכה",[["","","— ע׳ תנ) העתיק מאמר ר״א בן יעקב ומשמיט „מזוזה“. אבל דוחק גדול לומר שכן היתה גירסתו בגמ׳, מאחר שבכל מקומות הנ״ל הערה 6 (ועוד) איתא „מזוזה“. ונראה לומר שט״ס שם."],["25","25","ובפרט שבגמ׳ איתא „תפילין בראשו ותפילין בזרועו“ והרמב״ם משמיט תיבת „תפילין“ השני׳. וגם בגמ׳ אינו מוכרח שס״ל דהוי מצוה אחת (במנין המצות), אלא שחשבינן להו כחד. וראה לשון הב״י הנ״ל. ולהעיר מצפע״נ הל׳ תפילין פ״ד ה״ד (ושם בסופו מיישב „מה שכתב התוס׳ מנחות . . דהם מצוה אחת“)."],["26","26","ואולי י״ל דלהרמב״ם מכיון שצריך לפרש מרז״ל הנ״ל „כל מי שיש לו תפילין כו׳“ דאין הכוונה שיש לו כל הג׳ בכל עת, דהרי לילה לאו זמן תפילין (רמב״ם הל׳ תפילין פ״ד ה״י־יא), ועד״ז בציצית (רמב״ם הל׳ ציצית פ״ג ה״ז־ח), כ״א שבכללות במשך כל המעל״ע יש לו כל הג׳ מצות, לכן השמיט הכתוב „והחוט המשולש לא במהרה ינתק“. ולהעיר משאילתות שאילתא כו „מזוזה בימין ונ״ח משמאל ובעל הבית בטלית מצויצת ביניהון“. ובגליוני הש״ס (להר״י ענגל) לשבת (כב, א) דבשו״ת מהרי״ל מסיים (כשמביא מהשאלתות) לקיים החוט המשולש לא במהרה ינתק, ע״ש. וראה גם העמק שאלה שם סקכ״ב."],["27","27","להעיר משבת כג, ב: הזהיר במזוזה כו׳ הזהיר בציצית כו׳."],["28","28","בסוף הל׳ ציצית."],["29","29","והוא כהב׳ מימרות במנחות מג, ב. וכ״ה בסמ״ג מ״ע כו בסופה."],["30","30","רמב״ם הל׳ ברכות פי״א ה״ב."],["31","31","כמ״ש בתוד״ה ואין פסחים קיג, ב [אלא שהתוס׳ לא הביאו שם מפורש מזוזה (אף שמובן הוא). וראה גליוני הש״ס לתוס׳ שם]. ס׳ חרדים בהקדמה למצוות ס״ב."],["32","32","ולהעיר שהרמב״ם בסהמ״צ סוף מנין מ״ע חשב מצות מזוזה מ„המצות ההכרחיות“ — „מצות מתחייבות בהכרח בכל זמן בכל מקום ובאיזה ענין שיהי׳“ (וע״ש שכתב „כגון ציצית (ותפילין ושמירת שבת)“. וראה ההמשך שם „בתנאי שיהי׳ . . כענין שרוב בנ״א בו“. וראה הל׳ ציצית פ״ג הי״א — הובא לקמן בפנים). ואכ״מ."],["33","33","אף שבלאה״כ מובן הוא שם — ראה המשך לשונו שם „שהרי הכתוב שקלה ותלה בה כל המצות כולן“."]]],[1300291079,"„אע״פ שאין אדם מחוייב לקנות לו טלית ולהתעטף בה כדי שיעשה בה ציצית, אין ראוי לאדם חסיד שיפטר עצמו ממצוה זו אלא לעולם ישתדל להיות עטוף בכסות המחוייבת בציצית כדי שיקיים מצוה זו. ובשעת התפלה צריך להזהר ביותר גנאי גדול הוא לתלמידי חכמים שיתפללו והם אינם עטופים“;\nאיז מובן, אז דער המשך (אין דער לעצטער הלכה) „לעולם יהא אדם זהיר במצות ציצית“ איז די כוונה [ניט די השתדלות צו האבן א בגד אויף קענען מקיים זיין מצות ציצית — ווארום דעם ענין האט שוין דער רמב״ם געזאגט (ובאריכות) אין דער פריערדיקער הלכה — נאר די כוונה דערביי איז] אז ער זאל שטענדיק מקיים זיין די מצוה, זיין עטוף בציצית.\nדעריבער זאגט דער רמב״ם דעם לשון „לעולם יהא אדם זהיר במצות ציצית“, ווייל ער רעדט וועגן דער זהירות אין קיום המצוה, אין דעם בגד מצוייץ וואס ער האט שוין].\nס׳איז אבער א דוחק לפרש כן, ווארום וויבאלד דא (ביי מזוזה) רעדט זיך פארט וועגן א זהירות והשתדלות אין אן ענין של רשות (ניט קיין „חובה על האדם“), איז ניט מתאים כ״כ דער לשון „חייב אדם להזהר“, וואס משמעו איז חובה (של מצוה)³⁴, און דער רמב״ם האט לכאורה געדארפט³⁵ נוצן דעם לשון השתדלות וכיו״ב — ווי מיר געפינען טאקע בכגון דא בלשונו ביי מצות ציצית (כנ״ל) „אע״פ כו׳ אלא לעולם ישתדל להיות עטוף כו׳“.\nלכן משמע סו״ס, אז „חייב אדם להזהר במזוזה“ מיינט דעם חיוב במצות מזוזה — והדרא קושיא: פארוואס שרייבט דער רמב״ם דא ניט מפורש „להזהר במצות מזוזה“?\nד. ויש לומר הביאור בזה:\nדאס וואס דער רמב״ם זאגט „חייב אדם להזהר“ מיינט ער ניט דעם חיוב הזהירות אין זיין מקיים זיין מצות מזוזה, נאר די זהירות אין דער פעולה אויף עם³⁶ פון דעם חפצא פון מזוזה ותוכנה, און ווי ער איז דאס מפרט אינעם המשך דבריו „וכל זמן שיכנס ויצא יפגע ביחוד השם שמו של הקב״ה ויזכור אהבתו ויעור משנתו ושגיותיו בהבלי הזמן וידע שאין דבר העומד לעולם ולעולמי עולמים אלא ידיעת צור העולם ומיד הוא חוזר לדעתו והולך בדרכי מישרים“.\nדער ענין אין מזוזה („וכל זמן שיכנס כו׳“) איז ניט דער קיום מצות מזוזה³⁷ — די מעשה המצוה איז „קביעתה (בפתח הבית) זו היא המצוה“³⁸, און דער המשך קיומה³⁹ פון דער מצוה, באשטייט אין",[["34","34","כהמשך לשונו „מפני שהיא חובת הכל תמיד“."],["35","35","אבל אינו מוכרח, כי מצינו בכ״מ הלשון „חייב אדם“ והמדובר לא בחיוב, ולפעמים לא במצוה דאורייתא בכלל — ראה אנציקלופדי׳ תלמודית ערך חובה מצוה ורשות (ע׳ תרנב. ע׳ תרסד ואילך)."],["36","36","לכאורה ע״ד מש״נ בציצית וראיתם אותו וזכרתם גו׳ (וראה זהר שבהערה 12), אבל ראה לקמן בפנים."],["37","37","ולפ״ז המשך דברי הרמב״ם „מפני שהיא חובת הכל תמיד“ הוא כעין מאמר המוסגר ע״ד גודל ענין המזוזה, שלכן „חייב אדם להזהר במזוזה כו׳ וכל זמן שיכנס כו׳“. ועצ״ע."],["38","38","רמב״ם הל׳ מזוזה פ״ה ה״ז. ועד״ז הוא לשון הרמב״ם בהכותרת להל׳ תפילין ומזוזה מצוה ג ובמנין המצות בריש ספר היד מ״ע טו (וראה לשונו בסהמ״צ מ״ע טו)."],["39","39","ראה תוד״ה בההיא הנאה ב״ק נו, ב. נמוק״י שם. וכן מוכח ממרז״ל הנ״ל במנחות „חביבין ישראל שסיבבן כו׳“. ראה מג״א או״ח סכ״א סק״ב. ועוד. וראה חדא״ג מהרש״א מנחות שם."]]],[1300291080,"דעם וואס ער האט א מזוזה אויפן פתח הבית אין וועלכן ער איז דר (קיום מצות מזוזה איז ניט בלויז אין די זמנים „שיכנס ויצא“); ד.ה. ס׳איז ניט וואס דער אדם דארף טאן אין קיום המצוה, נאר (אדרבה), וואס די חפצא פון דער מצוה דארף פועל זיין אויפן אדם: וויבאלד אז די מזוזה אנטהאלט אין זיך „יחוד השם, שמו של הקב״ה“, דארף עס ביים אידן ארויסרופן דעם „יזכור⁴⁰ אהבתו ויעור משנתו כו׳ וידע כו׳“.\nולפ״ז קומט אויס, אז דער ענין פון „חייב להזהר במזוזה“ איז א דבר נוסף אויפן קיום המצוה: האבנדיק א מזוזה על פתח ביתו, דארף די זהירות⁴¹ אין מזוזה זיין באופן אז „כל זמן שיכנס ויצא יפגע ביחוד השם כו׳ ויזכור אהבתו כו׳“ ביז עס ברענגט אים אז „והולך בדרכי מישרים“.\nה. עפ״ז וועט מען פארשטיין פארוואס דער רמב״ם ברענגט דעם מאמר „כל מי שיש לו כו׳“ דוקא אין הל׳ מזוזה — ווייל דוקא מזוזה איז א „מזכיר“ מצד דעם חפצא שלו.\nביי תפילין זאגט דער רמב״ם⁴²: קדושת תפילין קדושתן גדולה היא שכל זמן שהתפילין בראשו של אדם ועל זרועו הוא עניו וירא שמים ואינו נמשך בשחוק ובשיחה בטילה ואינו מהרהר מחשבות רעות אלא מפנה לבו בדברי האמת והצדק לפיכך צריך אדם להשתדל להיותן עליו כל היום שמצותן כך היא.\nביי מצות ציצית איז לשון הרמב״ם (כנ״ל) „מצות ציצית . . הכתוב שקלה ותלה בה כל המצות כולן“.\nקומט אויס, אז לויטן רמב״ם איז דא א חילוק עיקרי צווישן די דריי מצות באופן פעולתן על האדם המקיימן:\nביי תפילין איז די פעולה על האדם מצד „קדושת תפילין“, וואס דאס איז ניט דער עצם חפצא דתפילין⁴³ אדער פון דער מהות המצוה⁴⁴;\nאויך ביי ציצית — דאס וואס זי רופט ארויס ביים אדם די זכירת כל המצות,",[["40","40","להעיר מזח״ג רסג, ב בנוגע למצות מזוזה „ותו דלא ינשי ב״נ דוכרנא דקב״ה לעלמין כו׳ כיון דחמי בר נש להאי דוכרנא אדכר בגרמי׳ למעבד פקודא דמארי׳ כו׳“. ולכאורה זהו מקורו דהרמב״ם. [אלא שבזהר הוא ענין שני („ותו“), ובתחילה כתב „פקודא למקבע ב״נ מזוזה לתרעי׳ למהוי כל ב״נ נטיר מעם קב״ה כו׳“. וראה גם לעיל הערה 12. ואכ״מ]."],["41","41","עד״ז פי׳ בט״ז יו״ד ר״ס רפה — דברי הטור יו״ד שם."],["42","42","הל׳ תפילין פ״ד הכ״ה."],["43","43","ד„קדושת תפילין“ (הפועלת על הגברא) כוללת לא רק הפרשיות עם הבתים כו׳, כ״א גם הרצועות (והקשרים), שכולם ביחד מהוים קדושת תפילין (דעיקרה וסיבתה — כשהם קשורים ומונחים על האדם). משא״כ החפצא דתפילין י״ל דהוי (רק) הד׳ פרשיות עם הבתים* וכשמונחים בהבתים — (ראה לשון הרמב״ם ריש הלכות תפילין) — ואולי י״ל דהללמ״מ מכריחה שצ״ל גם רצועות וכו׳. ונפק״מ לשבועה בתפלין בלא רצועותיהן (ושחורות דוקא וכו׳?). ולאידך, בקדושת תפילין בפ״ע (לא כמו שהתפילין קשורים ופועלים על הגברא), ישנם כמה חילוקים ודרגות בהקדושה: תפילה של ראש (דגדולה מ)תפילה של יד (רמב״ם הל׳ תפילין פ״ג הי״ז. שו״ע אדה״ז או״ח סמ״ב ס״א. וראה שם סכ״ה סי״ד); החילוקים דעור הבתים וקלף הפרשיות (שו״ע אדה״ז שם סל״ב סנ״ז); רצועות והקלף (ראה שו״ע אדה״ז שם סמ״ב ס״ז. וש״נ). ועוד. אמנם החפצא דתפילין אחת היא — הפרשיות והבתים. ועצ״ע ואכ״מ."],["44","44","ומה שהרמב״ם מסיים „שמצותן כך היא“ ה״ז לכל היותר בגדר מצוה מן המובחר (כמ״ש בפמ״ג (א״א) או״ח סי׳ לז סק״ב), וכדמוכח גם בלשונו „לפיכך צריך אדם להשתדל כו׳“. וראה תו״ש מילואים לכרך יב סל״ט ובהנסמן שם. ואכ״מ. *) וי״ל יתירה מזו — גם בלא הבתים, כפשט הכתוב בהפרשיות (שלא נזכר שם ע״ד הבתים ורצועות)."]]],[1300291081,"איז עס ניט פארבונדן מיט דער חפצא פון ציצית מצד עצמה, נאר דערפאר וואס „הכתוב שקלה ותלה בה כל המצות כולן“ — ע״פ הציווי בתורה איז דער קיום המצוה אויסגעשטעלט אין אזא מנין החוטין כו׳ וצבע תכלת וכו׳ וואס זיינען מרמז ומזכיר אלע מצות⁴⁵ — אבער ניט אז די חפצא פון ציצית איז פועל די זכירה [ומהאי טעמא איז דער מזכיר פארבונדן מיט מצות ציצית — ד.ה. דערמיט וואס דער אדם איז מקיים מצות ציצית דערמאנט אים די מצוה (ע״י הנ״ל) אויף אלע תרי״ג מצות].\nמשא״כ ביי מזוזה⁴⁶, וואס אנטהאלט „יחוד השם שמו של הקב״ה“⁴⁶*, איז די עצם⁴⁷ מזוזה⁴⁸ א „מזכיר“⁴⁹.\nועפ״ז יש לבאר ג״כ פארוואס דער רמב״ם ברענגט ניט דעם פסוק „והחוט המשולש לא במהרה ינתק“ (משא״כ אין גמרא):\nפון לשון הפסוק „והחוט המשולש לא במהרה ינתק“ איז מוכח, אז די מצות עצמן, זייענדיק דריי צוזאמען, פארהיטן זיי אים „שלא יחטא“⁵⁰, ד.ה. דער זכות פון מקיים זיין (זיין מסובב פון) די דריי מצות, איז שטארק צו זיין א הגנה פון חטא, און דערפאר „הכל בחיזוק שלא יחטא“.\nדער רמב״ם רעדט אבער וועגן פארשידענע פעולות ע״י די מצות⁵¹, ניט מצד זכות קיומן אלס „חוט המשולש“ — וכנ״ל — דעריבער⁵² פאסט ניט צו",[["45","45","ראה טור או״ח שם סכ״ד: דוגמא לדבר כאדם המזהיר לחבירו על ענין אחד שקושר קשר באזורו כדי שיזכרנו וע״כ יש בה ה׳ קשרים כו׳. וגם להטעמים דציצית בגמ׳ ת״ר כו׳ (רש״י מנחות מג, ב ד״ה שקולה) או דתכלת דומה לים כו׳ לכסא הכבוד (מנחות שם (ובפרש״י). וש״נ) — ה״ז בסוג הנ״ל."],["46","46","להעיר שבטור יו״ד שם כתב מרז״ל זה כטעם ע״ז שצריך ליזהר מאוד במזוזה „וצריך ליזהר מאוד בה כמו שאחז״ל כל מי שיש לו תפילין בראשו ובזרועו וציצית בבגדו ומזוזה בפתחו מוחזק הוא שלא יחטא מפני שיש במזוזה יחודו של הקב״ה ותמיד בבואו ובצאתו יזכור יחודו של הקב״ה כו׳“. ומשמע שהעיקר בג׳ אלו הוא מזוזה שהוא הוא הגורם כו׳. 46*) באופן גלוי — משא״כ תפלין, שהפרשיות מכוסות בבתים, אא״פ לומר שעצם חפצא דתפלין הוי „מזכיר“ (מצד „יחוד השם“ שבו)."],["47","47","וי״ל דכמו בפעולת השמירה שע״י המזוזה אשר [היא שייכת לגוף המזוזה, ולכן] היא לא רק בעת קיום מצות מזוזה כ״א גם מצד החפצא דמזוזה, כדמוכח בירושלמי (פאה פ״א ה״א. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191125\" data-slug=\"likkutei-sichot\" data-id=\"1300191125\">לקו״ש חי״ט ע׳ 125</a> ואילך) — כמו״כ הוא בפעולת „יחוד השם שמו של הקב״ה“ שבמזוזה, שהיא לא רק במזוזה הקבועה על פתח הבית (שבזה מקיים מצות מזוזה), כ״א יש מעין זה גם בגוף חפצא דהמזוזה, גם כשהיא מונחת על השולחן. וראה לקו״ש שם. וש״נ."],["48","48","אף שכל המצות שבספר אהבה ברמב״ם „הם תדירות, שנצטוינו בהם כדי לאהוב המקום ולזכרו תמיד כגון קריאת שמע* כו׳“ (ל׳ הרמב״ם בהקדמתו לספר היד). ולהעיר שהרמב״ם לא הזכיר שם מזוזה**. ואכ״מ."],["49","49","אלא שמעין זה הוא גם בתפלין וציצית, וכמ״ש הרמב״ם כאן „מזכירין רבים“ [שלכאורה אין כוונתו מצד ענין קדושת התפילין שכתב לפנ״ז (פ״ד הכ״ה) בנוגע פעולתן, או ענין הציצית שכתב בסוף הל׳ ציצית (ש„הכתוב שקלה ותלה בה כל המצות כולן“) — שאין זה בגדר „מזכירין“]. וי״ל שכוונתו שתוכן המצוה מזכיר אותו, וזה מביאו שלא יחטא."],["50","50","ראה פרישה לטור או״ח שם סק״י: המצות נקראים ג״כ מלאכים שהם שלוחי המקום אל ישראל. וראה סמ״ג שנסמן שם. מעדני יו״ט על הל׳ קטנות להרא״ש שם אות ש. וראה חדא״ג מהרש״א מנחות שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380082\" data-slug=\"likkutei-torah\" data-id=\"4001380082\">לקו״ת ויקרא ב, א</a>."],["51","51","וכדיוק לשון הרמב״ם „שהרי יש לו (א) מזכירין (ב) רבים“, ולא הזכיר לשון מצוה ומספרם — ג׳ („שהרי יש לו ג׳ מצות“ וכיו״ב), כי להרמב״ם הוא לא מצד (א) זכות קיום המצוה (ראה הערה הקודמת), (ב) ג׳ המצות ביחד — כ״א „מזכירין רבים“. וראה הערה 53."],["52","52","גם י״ל דמשמיט „חוט המשולש“ כי לפי *) ראה לשון הרמב״ם הל׳ ק״ש פ״א ה״ב. **) להעיר: גם בש״נ ס׳ המדע (ירושלים, תשכ״ד) ורמב״ם הוצאת קאפח לא הובאה מצות מזוזה."]]],[1300291082,"ברענגען דעם ענין פון „והחוט המשולש גו׳“⁵³.\nו. ע״פ כל הנ״ל קען מען פארענטפערן אן ענין תמוה דא אין רמב״ם:\nבדפוסים שלפנינו⁵⁴ שטייט בסיום הלכות מזוזה „בריך רחמנא דסייען“. ולכאורה, דרכו של הרמב״ם בכ״מ צו שרייבן דעם לשון בסיום פון א ספר⁵⁵ (אדער לכמה גירסות⁵⁶ אויך בסיום פון א „הלכה“ — כללית⁵⁶*), אבער ניט אינמיטן המשך ההלכות — פארוואס איז דא דער רמב״ם מוסיף דעם סיום־שבח „בריך רחמנא דסייען“ באמצע ההמשך — הלכות תפילין מזוזה וס״ת זיינען איין המשך פון הלכות?\nע״פ הנ״ל יש לומר, אז דער לשון האט א שייכות מיוחדת צו הלכות מזוזה:\nאין דעם וואס די דריי מצות — תפילין מזוזה און ציצית — זיינען פועל און העלפן א אידן בעבודתו, איז דער ענין פון „מסייע“ צוגעפאסט בעיקר ביי מזוזה, זייענדיק א מצוה וואס איר חפצא, דער „יחוד השם שמו של הקב״ה“ [און ווי דער רמב״ם זאגט פריער אין הל׳ מזוזה⁵⁷, אז זי איז א „מצוה גדולה שהיא יחוד השם של הקב״ה ואהבתו ועבודתו“] — איז מסייע דעם אידן.\nמשא״כ ביי די אנדערע צוויי מצות — ביי תפילין איז אופן פעולתן, ניט מצד החפצא פון תפילין נאר מצד קדושתן (כנ״ל), פאסט ניט זאגן אז דער אויבערשטער האט געגעבן תפילין אלס א מזכיר, א מסייע;\nועד״ז במצות ציצית וואס „הכתוב שקלה ותלה בה כל המצות כולן“ — ניט אז די עצם מציאות פון ציצית איז מזכיר ומסייע דעם אידן (וכנ״ל).\nאון דעריבער פירט אויס דער רמב״ם במצות מזוזה דוקא — א ברכה ושבח",[["","","הנ״ל אין כל הג׳ (ד׳) שוות בהצלה מן החטא, כי עיקרה הוא בהמזוזה. וראה לבוש שהובא לעיל הערה 16."],["53","53","ואולי י״ל שתלוי בחילוק הנ״ל ס״א: בגמ׳ הובא זה בהסוגיא דמצות ציצית, ובציצית עיקר המכוון הוא גודל קיום המצות, וכמודגש בציצית ש„הכתוב שקלה ותלה בה כל המצות כולן“ (והוא מצד מצות ציצית), וכנ״ל, ולכן הובא בגמ׳ „והחוט המשולש גו׳“, שמבטא מעלת קיום ג׳ המצות שמציל מן החטא. משא״כ ברמב״ם שהביא זה בהל׳ מזוזה בהמשך למעלת פעולת המזוזה (שעי״ז יעורר אותו „משנתו ושגיותיו בהבלי הזמן כו׳“), מדגיש הרמב״ם במצות אלו לא קיום המצות שלהם, אלא פעולתן בהאדם „שהרי יש לו מזכירין רבים כו׳“, כנ״ל בפנים. וראה לקמן סעיף ז."],["54","54","וכ״ה בדפוס רומי ר״מ."],["55","55","לפנינו נמצא „בריך רחמנא דסייען“ רק בסוף ב׳ (או ג׳) ספרי הרמב״ם*. אבל בכת״י תימן (ועוד כת״י) וכן בדפוסים הראשונים דהרמב״ם, כתוב כן בסוף כל א׳ מספריו — ראה ספר המדע (ירושלים, תשכ״ד). רמב״ם הוצאת קאפח. רמב״ם הוצאת פרענקל. ובדפוס רומי הנ״ל — ליתא בסוף ספר זמנים, עבודה, טהרה וקנין."],["56","56","כ״ה בכת״י תימן הנ״ל [וכ״ה בכת״י של ספר הרמב״ם ספר אהבה שעליו חתם הרמב״ם בכי״ק „הוגה מספרי אני משה ברבי מימון ז״ל“], ש„בריך רחמנא דסייען“ הוא בסוף כל הלכה — ראה הנסמן בהערה הקודמת (אבל לא נמצא שם בסוף הל׳ מזוזה*). וכן הוא בכו״כ הלכות בדפוס רומי הנ״ל. ובדפוסים לפנינו נמצא בסוף חמש הלכות דספר טהרה. ובסיום כו״כ הלכות שבספר היד לפנינו נמצא „סליקו . . בס״ד“. ויל״ע בכל הנ״ל אם כ״ז הוא מהרמב״ם או מהמעתיקים או מהמדפיסים. 56*) כהשם בספרו (לא „הלכות קטנות“ רבות שבכל פרק)."],["57","57","פ״ה ה״ד. *) ס׳ אהבה. זרעים. ובסוף ספר נשים „סליקו . . בסייעתא דשמיא“. וראה בסוף הערה הבאה. *) ובהוצאת קאפח חסר גם בסוף הל׳ ע״ז."]]],[1300291083,"אויף דעם וואס דער אויבערשטער האט געגעבן א מזכיר, א מסייע.\nז. בעומק יותר: מיט דער הוספה „בריך רחמנא דסייען“ קומט צו א תוספת הסברה אין דער פעולה מיוחדת פון מזוזה און איר אנדערשקייט פון מצות תפילין וציצית:\nדער ענין פון „מסייע“ אין א זאך, פאסט צו זאגן ווען איינער העלפט־צו דעם צווייטן צו טאן די זאך, אבער ניט ווען דער העלפער אליין טוט די גאנצע זאך — דעמאלט איז ער ניט קיין מסייע, נאר דער (גאנצער) עושה; ולאידך, ווען יענעמס הילף איז אזא וואס פארזיכערט ניט אז דער מסתייע זאל קענען אפטאן די זאך, איז דאס אויך ניט דער אמת׳ער סיוע.\nאון אין דעם איז (אויך) דער אויפטו פון מזוזה לגבי תפילין וציצית:\nבנוגע צו תפילין זאגט דער רמב״ם כנ״ל, אז דורך דעם וואס „קדושתן גדולה“ איז „כל זמן שהתפילין בראשו של אדם ועל זרועו הוא עניו וירא שמים ואינו נמשך בשחוק ובשיחה בטילה ואינה מהרהר מחשבות רעות אלא מפנה לבו בדברי האמת והצדק“. ד.ה. אז די תפילין זיינען ניט (בלויז) מסייע דעם אדם בעבודתו⁵⁸, נאר קדושתן של התפילין עצמה ווירקט און טוט אויף אין דעם אדם, ער זאל בשעת מעשה זיין אן „עניו וירא שמים כו׳“.\nביי מצות ציצית, וואס „הכתוב שקלה ותלה בה כל המצות כולן שנאמר וראיתם אותו וזכרתם את כל מצות ה׳“, איז עס לאידך גיסא — די מצוה דערמאנט דעם אידן אלע מצות, דערביי ווערט אבער ניט געזאגט, אז די זכירה איז א סיוע און הילף⁵⁹ אין מקיים זיין די מצות בפועל; עס דערמאנט אלע מצות, אבער לאו דוקא עד כדי כך, אז זייענדיק פארטאן אין הבלי הזמן וכיו״ב זאל די זכירה אים העלפן צו ברענגען אים צום קיום פון אלע מצות בפועל⁶⁰.\nמשא״כ במזוזה (זאגט דער רמב״ם) „כל זמן שיכנס ויצא יפגע ביחוד השם שמו של הקב״ה ויזכור אהבתו ויעור משנתו ושגיותיו בהבלי הזמן וידע שאין דבר העומד כו׳ ומיד הוא חוזר לדעתו והולך בדרכי מישרים“. ד.ה. פון איין זייט איז עס ניט ווי ביי (קדושת) תפילין, וואס אלץ וואס דער אדם קומט צו ע״י מצוה זו, איז די פעולה פון די תפילין, ניט דורך עבודתו הוא — משא״כ ביי מזוזה איז דער יחוד השם פון מזוזה מזכיר ומעורר דער אדם אז ער זאל (דורך דער מזוזה) געדענקען „אהבתו“ און „יעור משנתו“ א.א.וו.\nומצד השני, איז עס ניט ווי ביי מצות ציצית, וואס „הכתוב שקלה ותלה בה כל המצות . . וזכרתם את כל מצות ה׳“, אבער זי ווירקט ניט אויף דעם אדם צו שטעלן זיך אינעם מצב פון שינוי גברא; דאקעגן ביי מזוזה איז דאס באופן, אז דאס פועלט אז דער גברא זאל נשתנה",[["58","58","ולהעיר שהרמב״ם לא הביא (שם) הפעולה דתפילין בהזמן שלאח״ז, אף שבתר״י לברכות (יד, סע״ב ואילך), טושו״ע (ודאדה״ז) או״ח סכ״ה ס״ה (סי״א) „וע״י הנחת תפילין יזכור את הבורא יתברך וימעיט הנאותיו“ — ואולי י״ל שמובן הוא, מאחר שהן פועלות עליו בזמן היותן עליו, וסתם פעולה רישומה עכ״פ ניכר."],["59","59","יותר מגוף קיום המצוה (כבכל המצות) ש„מצוה גוררת מצוה“ (אבות פ״ד מ״ב)."],["60","60","ולהעיר שהרמב״ם לא הביא בסוף הל׳ ציצית המשך הכתוב „ועשיתם אותם“. וראה מנחות שם מג, ב „ראי׳ מביאה לידי זכירה וזכירה מביאה לידי עשי׳“."]]],[1300291084,"ווערן דורך דעם וואס „יזכור אהבתו ויעור משנתו ושגיותיו בהבלי הזמן“, ביז אז ער איז „חוזר לדעתו“ און ער איז „הולך בדרכי מישרים“.\nאון דערמיט איז מובן, אז דער אמת׳ער ענין פון „מסייע“, ביז אז דאס רופט ארויס ביים מסתייע צו בענטשן דערפאר דעם אויבערשטן, איז דוקא ביי מזוזה, וואס איז מסייע דעם אידן אז ער זאל גיין בדרך הישר.\nח. ע״פ הנ״ל איז אויך מובן, וואס דעם ענין פון „מזכירין רבים כו׳ שמצילין אותו מלחטוא“, ברענגט דער רמב״ם דוקא ביי מזוזה — ווייל בעצם איז דאס דער אמת׳ער גדר פון „מזכיר“:\nדי אמת׳ע און שלימות׳דיקע פעולה פון מזכיר זיין איז (ניט בלויז א דערמאנונג פון א זאך, וועלכע איז ניט פארבונדן מיט א ווירקונג במעשה (אדער עכ״פ „כאילו עשה“), נאר בלשון ופירוש הידוע) — „נזכרים ונעשים“⁶¹, אז די זכירה איז באופן כזה אז עס פועלט און מאכט אן עשי׳⁶².\n[וע״ד זכירת יצי״מ⁶³, וואס די זכירה בשלימות איז — בשעת ס׳איז באופן אז ער איז דאס רואה (מרגיש) — „חייב⁶⁴ . . לראות את עצמו כאילו הוא יצא היום⁶⁵ ממצרים“].\nאון אזא „מזכיר“ איז דוקא במזוזה, וכנ״ל אז מזוזה (איז מסייע און) פועלט אז ער זאל זיך איבערשטעלן אין א מצב הראוי און גיין „בדרכי מישרים“.\nט. אט דער „סיוע“ פון מזוזה איז ניט נאר אין דער איכות פון סיוע כנ״ל, נאר אויך אין דער כמות שבזה:\nאין סדר החיים פון (רוב) אידן זיינען פאראן בכללות צוויי מצבים — ווי דער איד געפינט זיך „בפנים“, בד׳ אמות של תורה ותפלה ומצות, אין א מצב פון קדושה און עבודת ה׳, און — ווי ער גייט ארויס אינעם „חוץ“ פון וועלט, אין „הנהג⁶⁶ בהן מנהג דרך ארץ“.\nאון דאס איז בכללות דער חילוק צווישן די מצות — תפילין וציצית אדער מזוזה⁶⁷:\nדורך די מצות פון תפילין וציצית, וואס דער איד לייגט על ראשו וזרועו און טראגט על גופו, איז ער מסובב במצות, ער איז „בפנים“; דער איד איז אפגעטיילט פון עניני עולם, ער איז פארבונדן מיט דעם אויבערשטן ומצותיו.\nמזוזה וואס געפינט זיך על פתח ביתו „בטפח הסמוך לחוץ“⁶⁸, איז מדגיש דעם אידן׳ס פארבונדנקייט מיטן אויבערשטן (אויך) ווען ער גייט ארויס בעולם שמחוץ. און דאס איז דער תוכן הענין וואס דער רמב״ם איז מסביר ומדגיש בהל׳ מזוזה: מזוזה קומט דערמאנען דעם אידן, אז ניט נאר זייענדיק בתוך ביתו, בפנים, דארף דער איד וכל עניניו זיין",[["61","61","אסתר ט, כח. וראה רמ״ז בספר תיקון שובבים. הובא ונתבאר בספר לב דוד (להחיד״א) פכ״ט."],["62","62","וכאותו שנתעלף בפועל בציירו לעצמו שהולך להמלך — ראה בארוכה לקו״ד ח״א קסד, א ואילך."],["63","63","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071273\" data-slug=\"likkutei-sichot\" data-id=\"1300071273\">לקו״ש ח״ז ע׳ 261</a> ואילך. ע׳ 270. ועוד."],["64","64","משנה — פסחים קטז, ב (הובא ברמב״ם בסדר ההגדה שלו)."],["65","65","הוספת אדה״ז ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא רפמ״ז</a>. ועד״ז ברמב״ם הל׳ חמץ ומצה פ״ז ה״ו. ועוד."],["66","66","ברכות לה, ב."],["67","67","להעיר מתר״י ברכות שם. סמ״ג בחלק המ״ע מ״ע ג. של״ה שנז, א. ועוד."],["68","68","רמב״ם הל׳ מזוזה פ״ו הי״ב — ממנחות לג, ריש ע״ב. וראה לעיל הערה 2."]]],[1300291085,"בהתאם מיט יחוד השם, שמו של הקב״ה שבמזוזה — נאר אויך ווען ער גייט ארויס בעולם שחוץ הימנו דארף ער אויך דארטן זיין דורכגענומען מיט יחוד השם שבמזוזה;\nאון דער „יפגע ביחוד השם שמו של הקב״ה“ שבמזוזה דארף פועל זיין אז אפילו ווען ער איז אריינגעפאלן אין הבלי הזמן, איז „יזכור אהבתו ויעור משנתו ושגיותיו בהבלי הזמן“. אבער אויך דאס איז נאך ניט מספיק — די זכירה דארף ווירקן א פעולה פנימית „וידע שאין דבר העומד לעולם ולעולמי עולמים אלא ידיעת צור העולם, ומיד הוא חוזר לדעתו (ביז — במעשה בפועל) והולך בדרכי מישרים“.\nאון דוקא דאן, ווען אויך זייענדיק אין דרויסן פון א אידישער שטוב — איז זיין עבודת השם כדבעי, איז דא, און ער פילט בשלימות דעם סיוע פון דעם אויבערשטן, און דאס ברענגט אים לברך את השם — „בריך רחמנא דסייען“.\n(משיחת ש״פ במדבר תשד״מ)"],[1300291086,"<h3>ראה</h3>\nא. אין הלכות בית הבחירה1 זאָגט דער רמב\"ם „המקדש כולו לא הי' במישור אלא במעלה ההר (און ווייטער איז ער ממשיך ומבאר די פרטי החילוקים והעליות כו' — ) כשאדם נכנס משער מזרחי של הר הבית מהלך עד סוף החיל בשוה. ועולה מן החיל לעזרת הנשים בשתים עשרה מעלות כו' ומהלך כל עזרת הנשים בשוה ועולה ממנה לעזרת ישראל שהוא תחלת העזרה בחמש עשרה מעלות כו' ומהלך כל עזרת ישראל בשוה ועולה ממנו לעזרת הכהנים במעלה גבוהה אמה כו' ומהלך כל עזרת הכהנים והמזבח כו' ועולה משם לאולם בשתים עשרה מעלות כו' והאולם וההיכל כולו בשוה\".\nדאָס וואָס דער רמב\"ם פאַנגט אָן (ומוסיף) די שלילה — „המקדש כולו לא הי' במישור (אלא במעלה ההר)\", און זאָגט ניט נאָר דעם חיוב „המקדש כולו הי' במעלה ההר\" — יש לומר:\nוויבאַלד אַז לדעת הרמב\"ם, איז דער קיום מצות עשה „ועשו לי מקדש\"2 ביים בויען דעם בית המקדש — בהמשך צום „משכן שעשה משה רבינו (במדבר)\", ווי ער זאָגט אין אַנפאַנג הל' בית הבחירה3; און ווי ער טייטשט אויך אָפּ דאָרט ביי די „דברים\" שבבנין הבית4:\n„ואלו הן הדברים שהן עיקר בבנין הבית, עושין בו קדש וקדש הקדשים ויהי' לפני הקדש מקום אחד והוא הנקרא אולם, ושלשתן נקראין היכל ועושין מחיצה אחרת סביב להיכל רחוקה ממנה כעין קלעי החצר שהיו במדבר וכל המוקף במחיצה זו שהוא כעין חצר אהל מועד הוא הנקרא עזרה והכל נקרא מקדש\". וואָס פון פשטות לשונו איז מובן, אַז די „דברים\" וואָס זיינען „עיקר בבנין הבית\" זיינען כעין ובדומה צו דעם וואָס עס איז געווען אין משכן5.\n[ועד\"ז זאָגט ער ווייטער אין הל' בית הבחירה6 לגבי די „שלש מחנות\" וואָס זיינען געווען במדבר, אַז אַזוי איז אויך „כנגדן לדורות\"].\nדעריבער וואָלט מען געקענט מיינען, אַז כשם ווי דער גאַנצער משכן איז (בפשטות) געווען אויף איין גלייכן שטח, ניט איין טייל העכער פאַר דעם צווייטן, איז באופן כזה אויך געווען דער מקדש,\nדעריבער פאַנגט אָן דער רמב\"ם מיט: „המקדש כולו7 לא הי' במישור (ווי דער משכן), אלא במעלה ההר\".",[["1","1","פ\"ו ה\"א-ד."],["2","2","תרומה כה, ח."],["3","3","רפ\"א. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161302\" data-slug=\"likkutei-sichot\" data-id=\"1300161302\">לקו\"ש חט\"ז ע' 302</a> ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211149\" data-slug=\"likkutei-sichot\" data-id=\"1300211149\">חכ\"א ע' 149</a>. ובהנסמן בהערות שם."],["4","4","הל' בית הבחירה פ\"א ה\"ה."],["5","5","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161306\" data-slug=\"likkutei-sichot\" data-id=\"1300161306\">לקו\"ש חט\"ז ע' 306</a>. וש\"נ. וראה גם קרית ספר להמבי\"ט על הרמב\"ם שם פ\"ד."],["6","6","פ\"ז הי\"א."],["7","7","לכאורה י\"ל שזהו דיוק לשון הרמב\"ם כאן „המקדש כולו\", כי מאחר שכבר כתב (פ\"א ה\"ה) שרק ההיכל (קדש קה\"ק ואולם) והעזרה (היינו עזרת ישראל, וכלשונו כאן ה\"ב: עזרת ישראל שהוא תחלת העזרה) נקרא מקדש (שהם בדוגמת המשכן), וכאן הרי מפרש „ועולה מן החיל לעזרת הנשים כו'\" (ש„החיל ועזרת נשים מעלה יתירה בבית עולמים\" — רמב\"ם שם פ\"ז הי\"א) — לכן הוצרך להקדים „המקדש כולו\", היינו „מקדש\" במובנו הכללי*. אבל יש לדחוק שגם ב„מקדש כולו\" כוונתו לחלקי *) ראה יבמות ו, ב (הובא ברמב\"ם כאן פ\"ז ה\"א. ע\"ש): איזו היא מורא מקדש לא יכנס אדם בהר"]]],[1300291087,"ב. דער רמב\"ם איז דאָך אַ ספר פון „הלכות הלכות\". איז מובן, אַז דאָס וואָס דער רמב\"ם איז מתאר אַז דער „מקדש כולו לא הי' במישור אלא במעלה ההר\" איז ניט בלויז דערפאַר ווייל אַזוי איז געווען די צורת הבית בפועל — וויבאַלד דער מקדש איז געווען געבויט אויף אַ הר, וואָס איז נאָכאַנאַנד עולה בשיפוע, האָט מען דערפאַר געמוזט8 בויען די חלקי הבית אַלץ העכער און העכער — נאָר9 דאָס איז אַן ענין של הלכה10 אין „מקדש כולו\"11 — און אין ביידע פרטים פון שלילה און חיוב: דער „מקדש כולו\" (א) דאַרף זיין ניט במישור — „לא הי' במישור\", און „אלא\" (ב) ער דאַרף זיין „במעלה ההר\".\nויתירה מזו יש לומר: פון דעם וואָס דער רמב\"ם איז מדייק צו זאָגן בלשון „לא . . אלא\" — און ניט „המקדש כולו הי' במעלה ההר ולא במישור\" — איז משמע12 אַז דאָס איז ניט אַן ענין נאָר לכתחילה, נאָר אַ תנאי לעיכובא13.\nמען דאַרף אָבער פאַרשטיין: וויבאַלד אַז דער בנין המקדש איז אַ המשך פון מצות „ועשו לי מקדש\", וואָס קיומה האָט זיך אָנגעפאַנגען מיטן משכן; און די דברים שהן עיקר בבנין הבית זיינען בדוגמא צו די דברים שבמשכן כנ\"ל — וואָס איז די הסברה וואָס אין דעם ענין דאַרף דער מקדש זיין אַנדערש פון דעם משכן14?\nאון אע\"פ אַז דער ביהמ\"ק איז געווען אין אַ סך פרטים אַנדערש פון דעם משכן, אָנהויבנדיק פון מדת המקדש וכו\"כ פרטים בגוף הבנין — איז: א) אויך בהם דאַרפן האָבן אַ טעם, ב) בכמה מהם — איז דער טעם פשוט, כמו — דער מקדש איז געווען (אויך) מאבנים וכיו\"ב,",[["","","המקדש שנקראים מקדש (שם פ\"א ה\"ה) היינו מעזרת ישראל ולפנים (הנמנה כאן ה\"ג ואילך). ואכ\"מ. וראה אנציקלופדיא תלמודית ערך ביהמ\"ק. וראה לקמן הערה 14."],["8","8","נוסף על העיקר שאין זה הכרח גמור, שהרי כמו שמהלך עד סוף החיל בשוה וכל עזרת הנשים וכו' בשוה (ולא בשיפוע), כך יכול להיות משך כל המקדש כולו."],["9","9","ראה קרית ספר כאן רפ\"ו. וראה שם גם בפ\"ה."],["10","10","דאם נאמר שכוונת הרמב\"ם בד' הלכות הראשונות בפ\"ו היא — רק הקדמה לזה שמסיים בהלכה ה „נמצא גובה קרקע ההיכל על קרקע כו' ומפני זה עשו כותל שעל גבי שער זה נמוך כדי שיהא כהן כו'\" (וכ\"מ מפיה\"מ להרמב\"ם מדות פ\"ב מ\"ד וה') — לא הוצרך הרמב\"ם להאריך כ\"כ בד' הלכות הראשונות, כ\"א לומר כמה גבוה עזרת נשים מן החיל; עזרת ישראל מעזרת נשים, וכו'. או שהי' מספיק רק מ\"ש בה\"ה."],["11","11","וראה לעיל הערה 7. הבית כו'. וראה בכורים פ\"א מ\"ט דנק' בית ה\"א. וברד\"ק יחזקאל (מ, ה) שההר בכללו נקרא בית המקדש. וראה מאירי יבמות ז, ב דביאר המחלוקת דת\"ק ור\"י אם עזרת נשים בכלל מקדש (וטמא הנכנס חייב כרת) או לא הוי בכלל מקדש. וראה שם דיש פוסקים שאף עזרת נשים בכלל כרת כו'. ושם (בחלק הפסקים ו, א) דמצות מורא מקדש אינה אלא מפתח העזרה ולפנים כו' ומד\"ס אף בהר הבית כן הא מן התורה . . ואין קרוי מקדש. וראה שו\"ת אבני נזר יו\"ד ח\"ב סתנ\"א אות כ ואילך ואכ\"מ."],["12","12","להעיר מתוד\"ה מתני דלא (מנחות פג, ב)."],["13","13","וי\"ל שתלוי בהנ\"ל (הערה 7) בפי' „המקדש כולו\", ואם „הכל בכתב גו'\" קאי (גם) על כל (הפרטים) הר הבית (ראה הערה הבאה), ואם כל הפרטים שב„הכל בכתב גו'\" הן למצוה או גם לעיכובא. ואכ\"מ. וראה סה\"ש תשמ\"ט ח\"ב ע' 453."],["14","14","כי אף ש„הכל בכתב מיד ה' עלי השכיל\" (דה\"א כח, יט), ד„כל מלאכת התבנית (ש)הודיעו הקב\"ה כו'\" (פרש\"י סוכה נא, סע\"ב. וראה גם ירושלמי מגילה פ\"א ה\"א); ויתירה מזו: בסוכה שם מוכח, דנאמר זה לא רק על העזרה ומבפנים (וראה פרש\"י שם. וראה פרש\"י דה\"א שם) — מ\"מ אין לומר בסתם ענין שהוא גזיה\"כ ואין ע\"ז שום הסברה. וראה קרית ספר שם ספ\"ד."]]],[1300291088,"אַסך גרעסער און העכער מהמשכן וכו' וויבאַלד ער איז געווען לדורות אין זעלבן אָרט וכיו\"ב, ג) דאָ דוקא איז מען מדגיש ובפרטיות גדולה אַז „המקדש כולו לא הי' במישור (ווי דער משכן) אלא במעלה ההר וכו'\".\nג. ויש לומר הביאור בזה:\nדי חילוקי מקומות וואָס זיינען געווען במקדש „במעלה ההר\" — וואָס דער הילוך פון איין חלק צום צווייטן איז געווען באופן של עלי' במעלות — זיינען בהתאם דערמיט וואָס יעדערער פון זיי האָט אין זיך אַ תוספת, אַן עלי' בקדושה לגבי דעם מקום פאַר עם (ווי דער רמב\"ם זאָגט אין פרק שלאח\"ז<sup data-n=\"15\">15</sup>. ועפ\"ז יש לומר, אַז דער דין פון „המקדש כולו לא הי' במישור אלא במעלה ההר\" איז פאַרבונדן מיט די עליות הדרגות שבקדושת המקדש — יעדער חלק המקדש וועלכער איז העכער אין שטח מקומו האָט אַ העכערע קדושה16.\nאון דערפאַר איז עס אַ דין נאָר אין מקדש און ניט אין משכן — ווייל דאָס וואָס די חילוקי דרגות בקדושה שאַפן אַ דין אין זייער שטח המקום, איז פאַרבונדן מיטן גדר הקדושה וואָס איז נתחדש געוואָרן אין מקדש (לגבי קדושת המשכן).\nדי הסברה אין דעם:\nעס איז דאָ אַ חילוק עיקרי צווישן דעם משכן און דעם בית המקדש: דער משכן איז געווען אַ בנין ארעי, כמ\"ש17 „ואהי' מתהלך באהל ובמשכן\", ובלשון הרמב\"ם הנ\"ל אַז דער „משכן שעשה משה . . הי' לפי שעה\"; משא\"כ דער בית המקדש איז געווען אַ „דירת קבע\"18, ובלשון הרמב\"ם19 „כיון שנבנה המקדש בירושלים נאסרו כל המקומות כולן לבנות בהן בית לה' ולהקריב בהן קרבן ואין שם בית לדורי הדורות אלא בירושלים בלבד ובהר המורי'\"20.\nאון דער אונטערשייד צווישן זיי אין גדר הקדושה איז: אין משכן איז די חלות הקדושה געווען (בעיקר) אין דעם בנין וחלקיו — די קרשים ויריעות כו' (וואָס זיינען נמשח געוואָרן בשמן המשחה21 און וועלכע זיינען געווען קבוע), אין זיי איז ניט געווען קיין שינוי; אין ביהמ\"ק אָבער איז אויך22 געווען „קדושת מקום\"23 — דער עצם מקום המקדש איז נתקדש געוואָרן: און אין צוויי זאַכן: א) דוקא בנוגע לבית המקדש זאָגט מען בפרשתנו24 „המקום",[["15","15","פ\"ז הט\"ז ואילך."],["16","16","אבל לא כל מקום המקודש יותר גבוה יותר בשטח. — ראה לקמן בפנים (ס\"ה ואילך) בנוגע לקה\"ק. ויל\"ע בנוגע להחיל שלדעת הרמב\"ם „מהלך עד סוף החיל בשוה\"*. וכן צ\"ע בנוגע לבין האולם ולמזבח, שאין שם מעלות, אף ש„בין האולם ולמזבח מקודש ממנה (מעזרת כהנים)\" (שם פ\"ז ה\"כ). וראה לקמן הערה 47. *) וראה לעיל בשוה\"ג להערה 7."],["17","17","ש\"ב ז, ו. ראה שהש\"ר פ\"א, טז (ג). תו\"א ר\"פ ויגש."],["18","18","ראה שהש\"ר שם. תו\"א שם."],["19","19","שם פ\"א ה\"ג."],["20","20","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161479\" data-slug=\"likkutei-sichot\" data-id=\"1300161479\">לקו\"ש חט\"ז ע' 466</a> ואילך."],["21","21","תשא ל, כו. פקודי מ, ט. וראה שבועות טז, ב."],["22","22","ראה מהרש\"א שם טו, א: לא הי' למשכן שום קביעות מקום ולא הוה צריך לקדש המקום בהיקף ב' תודות ובשירי מנחה אלא שהמשכן נתקדש במשיחה אבל . . בבנין בהמ\"ק שנקרא נחלה בעי לקדושי המקום (עיי\"ש, ועד\"ז כתב בנוגע לשילה: שהוא מקרי מנוחה בקביעות מקום כו' ע\"כ הוה צריך לקדש המקום. וראה בהנסמן לקמן הערה 24). וראה תוס' שבהערה הבאה, לקמן הערה 27."],["23","23","ראה תוד\"ה או אידי שבועות טז, ב — בפי' רבינו חיים כהן."],["24","24","פרשתנו יב, יא. ספרי ופרש\"י שם. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241079\" data-slug=\"likkutei-sichot\" data-id=\"1300241079\">לקו\"ש חכ\"ד ס\"ע 79</a> ואילך. וש\"נ."]]],[1300291089,"אשר יבחר ה' אלקיכם בו\", ב) ס'איז געווען די מעשה הקידוש פון קרקע (רצפה) המקדש כו'25.\nאון אע\"פ אַז אויך בנוגע דעם משכן שטייט אין פסוק26 (ביי אַ סוטה) „ומן העפר אשר יהי' בקרקע המשכן יקח הכהן\" — איז עס א) געווען נאָר ארעי — „לפי שעה\", ב) אפילו אויך באותה שעה — איז עס געווען ניט צוליב דער קדושה פון דעם מקום27 וקרקע מצד עצמו, נאָר מצד דעם אהל מועד (יריעות וקרשים) — המשכן וועלכער איז געשטאַנען אויף דעם קרקע.\nומהאי טעמא איז דאָ אַ חילוק צווישן מקום המשכן און מקום המקדש, אַז ביים משכן, נאָך דעם ווי מ'האָט אים פורק געווען און נסעו משם28, איז ניט געבליבן קיין שום קדושה במקום הראשון29 (ובדוגמא ווי דאָס איז געווען ביים הר סיני נאָך מ\"ת30, „במשוך היובל המה יעלו בהר\"<sup data-n=\"31\">31</sup>;\nמשא\"כ ביים בית המקדש32, איז דער דין, ווי דער רמב\"ם פסק'נט33, אַז „מקריבין הקרבנות כולן אע\"פ שאין שם בית בנוי ואוכלין קדשי קדשים בכל העזרה אע\"פ שהיא חריבה ואינה מוקפת במחיצה\". וויבאַלד דער מקום עצמו איז נתקדש געוואָרן („מפני השכינה\"<sup data-n=\"34\">34</sup> — „המקום אשר יבחר גו'\" — די בחירה איז אין דעם מקום, דעריבער בלייבט דאָרט קדושה (לעולם ועד)35.\nד. עפ\"ז איז מובן וואָס דוקא אין מקדש איז געווען דער חידוש, אַז „המקדש כולו לא הי' במישור אלא במעלה ההר\" און די פרטי החילוקים אין די עליות ממקום למקום אין בית המקדש:\nדוקא אין מקדש וואָס איז דאָ אַ קדושה בשייכות צום „מקום\" גופא — דער מקום איז אַ „מקום אשר יבחר ה'",[["25","25","ראה זבחים כד, א בפרש\"י ותוס' שם. רמב\"ם הל' בית הבחירה פ\"א הלכה יו\"ד ובמפרשי הרמב\"ם שם."],["26","26","נשא ה, יז."],["27","27","ראה ספרי נשא שם „מגיד הכתוב כו' מפני שהמקום מקדשו\". אבל ראה אמבוהא דספרי לספרי זוטא שם, דהכוונה בזה רק שמזמינו שיהי' ראוי למי סוטה. עיי\"ש. ולהעיר מהדיעה בסוטה טו, סע\"ב (וראה פרש\"י שם) דא\"צ להניחו בקרקע ההיכל."],["28","28","ראה מנחות צה, סע\"א (וש\"נ). ובכ\"מ. וראה הערה הבאה."],["29","29","ראה תוד\"ה בשילה (יומא מד, א) דמפרש עפ\"ז השקו\"ט בשבועות שם. עיי\"ש. ולהעיר שבתוס' שם „אבל במשכן לאחר שנסעו משם ופירקוהו והעמידוהו במקום אחר אין חייבין על מקומו הראשון\" (וראה פי' רגמ\"ה מנחות שם „שאין ראויים להכנס לאותו מקום שהי' בי' אה\"מ מפני שהי' קדוש\"). וראה אמבוהא דספרי נשא שם. ואכ\"מ. וראה הערה הבאה."],["30","30","ראה תענית כא, ב: שכן מצינו בה\"ס שכל זמן כו' וכן מצינו באהל מועד כו'."],["31","31","יתרו יט, יג ובפרש\"י שם."],["32","32","ראה מו\"ק ט, א (ועד\"ז שבועות טז, ב): משכן שאין קדושתו קדושת עולם . . מקדש שקדושתו קדושת עולם*. וראה ר\"ח שם. תוס' יומא שם. ובחי' הרמב\"ן שבועות שם: ואפשר דמאי דקדושתו קדושת עולם שמאחר שנבחר הבית שוב לא השרה הקב\"ה שכינתו במקום אחר אע\"פ שחרב, משא\"כ במשכן שנבחר אח\"כ מקדש. וראה חידושי הרשב\"א והריטב\"א שם."],["33","33","הל' בית הבחירה פ\"ו הט\"ו."],["34","34","שם הט\"ז. — ולהעיר שנקראת כך „על שם ששוכנת ומתלבשת תוך כו'\" (<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א — נז, ב</a>). וכבר נת' כמ\"פ שקביעות קדושת שכינה בהמקום באה מצד מעשה הקידוש שקדשה שלמה (שם הי\"ד). ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161206\" data-slug=\"likkutei-sichot\" data-id=\"1300161206\">לקו\"ש חט\"ז ע' 206</a> (ובהערה 49 שם). ועוד."],["35","35","ואין בכל הנ\"ל סתירה להמבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211151\" data-slug=\"likkutei-sichot\" data-id=\"1300211151\">לקו\"ש חכ\"א ע' 151</a> עד\"ז לגבי המשכן — כי שם המדובר לא במקום המשכן, כ\"א בחלקי המשכן. *) להעיר עד\"ז משיעור הרמב\"ם דיום ג' דשבוע זה (תשד\"מ) — הל' נזירות (פ\"ז הי\"ג) — החילוק דנזיר וכהן, „שזה (נזיר) קדושתו קדושת שעה (ואפילו הי' נזיר עולם), והכהן קדושתו קדושת עולם\". וראה רדב\"ז ולח\"מ שם."]]],[1300291090,"גו'\" — דאָרט איז שייך זאָגן אַז די חילוקי הקדושה אין מקדש שאַפן חלוקים אין מקום המקדש, אין גובה השטח פון די מקומות, מיט וואָס איין מקום איז אויסגעטיילט פון צווייטן מקום. וואָרום די קדושת מקום פון ביהמ\"ק איז ניט (נאָר) אַ קדושה כללית, גלייך אין דעם גאַנצן ביהמ\"ק, נאָר עס זיינען דאָ חילוקי דרגות אין קדושת המקום בהתאם צו דרגות הקדושה פון די חלקי הבית — היכל, עזרה.\n[און אויך די קדושה מיוחדת פון דעם מקום פרטי איז געבליבן אויף שטענדיק — „אע\"פ שאין שם בית בנוי\", ווי פאַרשטאַנדיק (אויך) פון דעם רמב\"ם הנ\"ל אַז „אוכלין ק\"ק בכל העזרה אע\"פ שהיא חריבה כו'\", וואָס אכילת ק\"ק איז מקומה בעזרה36].\nמשא\"כ דער משכן וואָס איז ניט געווען אינעם אופן פון קביעות במקום — ס'איז ניט געווען אַ „מקום אשר יבחר ה'\", נאָר קדושת המשכן איז געווען אין די (חלקי) אהל מועד, קרשים ויריעות וכו' — דעריבער איז ביים משכן ניט געווען, ניט נמשך און נקבע געוואָרן דער אונטערשייד פון קדושת חלקי המשכן אין דעם מקום במדבר — וואו ס'איז געווען (ארעית) חניית המשכן.\nאון דערפאַר איז דער מקום המשכן געווען „במישור\" — אין שטח המשכן גופא איז איין מקום (פון חלק) המשכן ניט געווען אויסגעטיילט פון אַ צווייטן מקום.\nאון דערפאַר איז דער רמב\"ם מדגיש דעם חילוק צווישן משכן און מקדש — כאָטש עס זיינען פאַראַן (כנ\"ל) כו\"כ חילוקים ביניהם — ווייל דוקא אין דעם וואָס „המקדש כולו לא הי' במישור אלא במעלה ההר\" (די חילוקי עליות פון די חלקי המקדש) דריקט זיך אויס אַ חידוש עיקרי פון דעם מקדש לגבי דעם משכן — זייענדיק דער „מקום אשר יבחר ה'\" האָט דער מקדש וחלקיו אויפגעטאָן אין מקומו — אין קדושת המקום.\nה. לפ\"ז דאַרף מען אָבער פאַרשטיין:\nלפי הנ\"ל, אַז די עליות אין שטח המקום זיינען פאַרבונדן מיט די דרגות שונות ועליות אין קדושת המקום, וואָס העכער ס'איז געווען די קדושה פונעם חלק המקדש אַלץ העכער איז געווען זיין (שטח) מקום — פאַרוואָס זיינען ניט געווען קיין מעלות (וריבוי מעלות) אַרויפצוגיין צום קדש הקדשים?\nדער קה\"ק איז דאָך געווען (כשמו קודש לגבי הקדשים) אויסגעטיילט בקדושתו פון אַלע חלקי הבית, און ווי דער רמב\"ם פירט אויס אין ווייטערדיקן פרק37 אַז די העכסטע קדושה38 איז אינעם בית קדש הקדשים „שאין נכנס לשם אלא כה\"ג ביוהכ\"פ בשעת העבודה\". האָט ער דאָך געדאַרפט זיין העכער (אַ סך העכער) בשטח מקומו?!\nוועט מען דאָס פאַרשטיין בהקדם הביאור בהנ\"ל, אינעם הפרש צווישן",[["36","36","ראה זבחים סג, א. וש\"נ. ספרי קרח יח, יו\"ד. וראה לשון הרמב\"ם הל' מעשה הקרבנות פ\"י ה\"ג."],["37","37","פ\"ז הכ\"ב."],["38","38","כי חלק העלי' שהי' מכוון על קדש הקדשים ש„אין נכנסין לו אלא פעם אחת בשבוע לידע כו'\" (שם הכ\"ג) אינה עלי' בקדושה לגבי קה\"ק — עי' לשון הרמב\"ם שם (שלא כתב כמו בהשאר שלפנ\"ז „מקודש ממנו\"). והרי מפורש ברמב\"ם (לעיל הי\"ג) דרק „עשר קדושות הן בא\"י וזו למעלה מזו\". ובקרית ספר שם „דאע\"ג דעליות לא נתקדשו כו' עליות היכל נתקדשו . . וקדושתה שלא יכנסו שם ללא לצורך דהא קדושת היכל נמי היא כו'\". וראה תוי\"ט — מדות פ\"ד מ\"ה; כלים ספ\"א ד\"ה קדש הקדשים."]]],[1300291091,"משכן און מקדש, לויטן סגנון פון תורת החסידות39:\nדער משכן, וואָס איז געווען אַ דירת ארעי (כביכול) צום אויבערשטן, איז געווען געבויט פון עצים (קרשים) — צומח און יריעות — (טיילווייז געמאַכט פון) חי (בלויז דער קרקע, אויף וועלכן מ'האָט עס לפי שעה מקים געווען איז געווען דומם, עפר<sup data-n=\"40\">40</sup>: משא\"כ דער ביהמ\"ק, וואָס איז געווען אַ „דירת קבע\" של הקב\"ה, איז געווען געבויט בעיקר פון אבנים („ואין בונים בו עץ בולט כלל אלא או באבנים או בלבנים\"<sup data-n=\"41\">41</sup> — דומם, וואָס איז נידעריקער פון סוג הצומח וחי.\nאון ס'איז מבואר דער טעם בזה: ענינו של משכן איז געווען (ניט אַזויפיל אויף צו פועל זיין אַ שינוי קבוע אין גשמיות העולם, נאָר) (בעיקר) צו „אָפּשפּיגלען\" דעם סדר ההשתלשלות דהעולמות42. און דעריבער איז דער בנין המשכן געווען בהתאם ווי די ענינים ווערן נמשך אין סדר ההשתלשלות, דער מכסה המשכן למעלה איז געווען פון „חי\" אַזוי אויך די יריעות עזים שלמטה ממנו, און (ברובן) די יריעות שלמטה מהן. למטה מזה מיעוטא דיריעות המשכן און די נידעריקע חלקי המשכן, קרשי המשכן, איז געווען פון צומח, און נאָך נידעריקער די אדנים און דער קרקע המשכן, איז געווען כסף ועפר, דומם.\nדער יתרון און אויפטו פון בית המקדש (לגבי דעם משכן) איז אין דעם וואָס דורך אים פירט זיך אויס די כוונה פון נתאוה הקב\"ה להיות לו דירה בתחתונים43 דוקא, אַז די קדושה, די השראת השכינה, זאָל נמשך ווערן און דורכנעמען די וועלט, ביז צו דער נידעריקסטע דרגא פון גשמיות העולם — אויך דעם סוג פון דומם, אין וועלכן עס זעט זיך ניט בגלוי זיין חיות און זיין רוחניות.\nאון וויבאַלד אַז דער בית המקדש איז ענינו צו ממשיך זיין השראת השכינה אין וועלט באופן אַז די קדושה זאָל דורכנעמען און מעלה זיין די גשמיות, דערפאַר האָט זיך דאָס אויסגעדריקט אויך אין דער גשמיות'דיקער מציאות פון וועלט גופא — אַז דער אָרט וואו דער בית המקדש איז געשטאַנען איז געווען בהר, העכער פון די מקומות סביבו44; און וואָס העכער די עלי' און מדריגת הקדושה במקדש, אַלץ העכער בגשמיות איז אויך געווען דער מקום גשמי.\nמשא\"כ דער משכן, וואָס (עיקר) ענינו איז ניט געווען אַז די השראת השכינה שבו זאָל דורכנעמען גשמיות העולם ביז דעם דומם, דעם ארץ, שאין למטה ממנו — דעריבער איז די השראת השכינה און די קדושה שבו כאילו פאַרבליבן ווי אַ באַזונדער מציאות, דאָס האָט זיך ניט אָפּגעשפּיגלט אין דעם מקום גשמי. און דעריבער, כאָטש אין משכן זיינען",[["39","39","תו\"א ר\"פ ויגש. תו\"ח ויגש שם פ\"ח. סדור כא, ב. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071017\" data-slug=\"likkutei-sichot\" data-id=\"1300071017\">לקו\"ש ח\"ז ע' 17</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091062\" data-slug=\"likkutei-sichot\" data-id=\"1300091062\">ח\"ט ע' 62</a> ואילך. ובכ\"מ."],["40","40","כ\"ה בתו\"א. וצ\"ע שלא נזכרו שם האדנים שהיו דומם. ובתו\"ח שם צב, ג: ושם צג, ב: ובחי' אדני הקרשים דמשכן מדומם דכסף."],["41","41","רמב\"ם הל' ביהב\"ח פ\"א ה\"ט."],["42","42","ראה בחיי תרומה כה, ט. ועוד. תורת העולה להרמ\"א ח\"א באריכות. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא פל\"ד</a>."],["43","43","תנחומא נשא טז. וראה גם במדב\"ר פי\"ג, ו."],["44","44","ראה זבחים נד, ב (וש\"נ): מלמד שביהמ\"ק גבוה מכל א\"י וא\"י גבוהה מכל ארצות. וראה להלן זבחים שם — הובא בפרש\"י ברכה לג, יב."]]],[1300291092,"געווען חילוקים אין דרגות הקדושה, איז ער אָבער געווען — בהמקום בעולם הזה — כולו במישור, ניט אויפגעהויבן בהתאם למדריגת הקדושה, במישור אפילו מיט'ן מקום המדבר.\nו. עפ\"ז איז אויך מובן דער טעם פאַרוואָס דער קדש הקדשים במקדש, דער מקום המקודש ביותר, איז ניט געווען אויסגעטיילט בגובהו פון דעם היכל המקדש:\nדער ענין אַז די קדושה רוחניות פון מקדש פועלט אין דער עלי' פונעם גשמיות'דיקן מקום — און וואָס דערפאַר איז איין מקום העכער פאַר דעם צווייטן, לויט די חילוקים אין דער קדושה — איז שייך בנוגע אַזעלכע מדריגות אין קדושה וואָס די נידעריקערע דרגא איז בערך דער העכערער, העכער (נאָר) „בשתים עשרה מעלות\" וכיו\"ב; ווען עס רעדט זיך אָבער וועגן אַזאַ מדריגה אין קדושה וואָס איז העכער באין ערוך (ביז צו זיין העכער פון דעם גדר פון מעלה ומטה) — ביי אַ דרגא נעלית באין ערוך — איז ניט שייך אַז דאָס זאָל זיך אויסדריקן אין אַ צאָל טרעפּ, מעלות — אין גובה מדוד ומוגבל, ובמילא — ניט אין גובה מקום גשמי.\nאון דאָס איז דער חילוק צווישן שאר חלקי המקדש און — קדש הקדשים: חלקי המקדש, איז די קדושה פון איינעם העכער, אָבער בערך, האָט אַן ערך צו דעם חלק ומדריגת הקדושה הסמוכה — און מתאים לחילוק הערך איז דער חילוק ביניהם אין דעם מספר און גובה המעלות בין מקום למקום, איינער איז העכער פון צווייטן אויך בגשמיות.\nאָבער ביי (דער קדושה פון) קדש הקדשים, וואָס דאָרטן איז געווען גילוי בהמקום פון (עצמות, פון) נמנע הנמנעות45, אין דעם מקום הארון (שאינו מן המדה<sup data-n=\"46\">46</sup>, וואָס איז שלא בערך כלל צו שאר חלקי המקדש, העכער בכלל פון דעם גדר פון מעלה ומטה — אַזאַ העכערקייט קען ניט אויסגעדריקט ווערן (אפילו בכעין רמז ודוגמא) אין אַ גובה פון אַ מקום גשמי, וואָס איז מדוד ומוגבל.\nז. נאָך אַן ענין אין דעם — ובהקדים הדיוק אין לשון הרמב\"ם „כשאדם נכנס משער מזרחי של הר הבית מהלך עד סוף החיל בשוה ועולה מן החיל לעזרת הנשים בשתים עשרה מעלות כו' ומהלך כל עזרת הנשים בשוה ועולה כו'\", אַז ביי די מעלות ועליות רעדט ער (ניט אַזוי וועגן גובה המקום מצ\"ע, נאָר) ווי דער אדם איז מהלך ועולה.\nויש לומר אַז דער רמב\"ם איז דערמיט מרמז אַז די אַלע מדריגות אין קדושה וואָס דער מענטש איז „הולך\" מדרגא לדרגא, איז דאָס באופן של „עולה\", עס מוז פועל זיין עלי' בהאדם, ער דאַרף זיך אויפהויבן און עולה זיין מדרגא לדרגא47.\nבשעת עס קומט אָבער צו מדריגות קודש הקדשים, איז ניט דער אופן אַז דער אדם איז „הולך . . ועולה\", ער שטייגט העכער אין זיינע עליות בקודש, נאָר ער איז כולו בביטול במציאות לגמרי, „כולו בשוה\"48.",[["45","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111326\" data-slug=\"likkutei-sichot\" data-id=\"1300111326\">לקו\"ש חי\"א ע' 319</a> ואילך. וש\"נ."],["46","46","יומא כא, סע\"א. וש\"נ."],["47","47","להעיר מתורת העולה שם פ\"ד, רפ\"ז. ופ\"י. ושם מבאר ג\"כ הטעם שאין מעלות לעלות להחיל, וכן בין האולם ולמזבח, ומן ההיכל לקה\"ק."],["48","48","מעין דוגמא לזה — ר\"ז צם מאה (מ') תעניתא דלשתכח תלמוד בבלי (ב\"מ פה, א), שיוכל ללמוד תלמוד ירושלמי. כי בשכלים שבערך העלי' מדרגא לדרגא היא ע\"י לימוד ועלי' נעלית יותר"]]],[1300291093,"און דאָס איז פאַרבונדן מיט דעם ביהמ\"ק וועלכער איז „(ושכנתי) בתוכם\"49, מיט דער בחינה פון „קודש הקדשים\" וואָס איז אין דעם מקדש הפרטי פון יעדן אידן, פנימיות דפנימיות הלב, בחי' יחידה שבנפש50, וואָס אין אים איז ניטאָ קיין ציור והגבלה, ועל אחת כמה וכמה ניטאָ קיין התפשטות (וואָס איז נרמז51 אין דעם קוץ שעל היו\"ד<sup data-n=\"52\">52</sup>, וואָס מצד איר איז אַ איד „מבטל ומסלק את עצמו ורצונו ליבטל אליו ית'\"53, און אין דעם איז די עצם ההתקשרות פון אַן אידן — וואָס איז העכער פון גדר וציור, יחידה לייחדך, בדוגמת כניסת כהן גדול (אַלס אַ שליח פון „כל עמך בית ישראל בכל מקום שהם\") אחת בשנה לקדש הקדשים.\n(משיחת ש\"פ מסעי תשד\"מ)",[["","","בשכל; משא\"כ שכל שבאין ערוך, כמו החילוק דבמחשכים הושיבני זה תלמוד בבלי (סנהדרין כד, א) לדרך הלימוד דירושלמי דאין תורה כתורת א\"י (ראה ספרי ר\"פ עקב. ב\"ר פט\"ז, ד), צ\"ל ביטול השגה הקודמת לגמרי. כמבואר בארוכה בסה\"מ תש\"ח ע' 121 ואילך. וש\"נ."],["49","49","תרומה כה, ח. „וארז\"ל* בתוכו לא נאמר אלא בתוכם\" (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380389\" data-slug=\"likkutei-torah\" data-id=\"4001380389\">לקו\"ת נשא כ, ב</a>)."],["50","50","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161485\" data-slug=\"likkutei-sichot\" data-id=\"1300161485\">לקו\"ש חט\"ז ע' 472</a>. וש\"נ. *) כ\"ה בכ\"מ בדא\"ח. ולע\"ע לא מצאתיו אלא בר\"ח (ש' האהבה פ\"ו קרוב לתחלתו). של\"ה ש' האותיות אות ל'. מס' תענית רד\"ה מענין העבודה. פ' תרומה — שכה, ב. שכו, ב. — ועוד."],["51","51","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת ראה כז, א</a>."],["52","52","כי גם היו\"ד עצמה אינה בבחי' התפשטות — ראה לקו\"ת שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191433\" data-slug=\"likkutei-sichot\" data-id=\"1300191433\">לקו\"ש חי\"ט ע' 419</a> ואילך. וש\"נ."],["53","53","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380872\" data-slug=\"likkutei-torah\" data-id=\"4001380872\">לקו\"ת תצא לח, סע\"ד</a>. ושם הוא (גם) לגבי בחי' חי'."]]],[1300291094,"<h3>ראה ב</h3>\nא. „לא תוכל לאכול בשעריך מעשר דגנך ותירושך ויצהרך ובכורות בקרך וצאנך וכל נדריך וגו' ותרומת ידך\"1.\nשטעלט זיך רש\"י אויף די ווערטער „לא תוכל\" און (נאכן מפרש זיין „בא הכתוב ליתן לא תעשה על הדבר\", כדלקמן סעיף ה — איז ער נאך אמאל מעתיק די ווערטער „לא תוכל\" און) איז מפרש „רבי יהושע בן קרחה אומר2 יכול אתה אבל אינך רשאי\" [און דערנאך ברענגט ער א דוגמא דערצו — „כיוצא בו ואת3 היבוסי . . לא יכלו . . להורישם יכולים היו אלא שאינן רשאין כו'\", כדלקמן סעיף ב].\nדארף מען פארשטיין:\nדעם ענין — אז „לא תוכל\" קען מיינען „אינך רשאי\" — געפינט מען שוין פריער אין חומש: אין ספר שמות4 שטייט „לא יוכל העם לעלות גו' (אויף הר סיני) כי אתה העדתה בנו לאמר הגבל את ההר גו'\", און ווי רש\"י איז אויף דעם מפרש „איני צריך להעיד בהם שהרי מותרין ועומדין . . ולא יוכלו לעלות שאין להם רשות\"; עד\"ז איז רש\"י מפרש דעם פסוק5 „לא תוכל לראות את פני\" — „איני נותן לך רשות\"6.\n[נוסף לזה וואס מ'געפינט עס אויך כמה פעמים אין ווייטערדיקע פסוקים, וביניהם אויך כו\"כ לא תעשה'ת וועלכע ווערן געזאגט אין דעם לשון — ווייטער אין אונזער סדרה7: לא תוכל לזבוח את הפסח גו'; אין פ' שופטים8 — „לא תוכל לתת עליך איש נכרי גו'\"; אין פ' תצא9: לא יוכל לבכר גו', לא תוכל להתעלם גו', לא יוכל לשלחה גו', לא יוכל בעלה הראשון גו']\n— איז תמוה בנדו\"ד10: מיט וואס איז אונזער פסוק אנדערש פון די אלע ערטער, וואס דוקא דא דארף רש\"י ברענגען דעם מאמר פון ר' יהושע בן קרחה „יכול אתה אבל אינך רשאי\" (כאילו אז דער פירוש („אינך רשאי\") איז א חידוש)11?\nאון נאך מער10: די ראי' אז דער לשון „לא תוכל\" קען געטייטשט ווערן „אינך רשאי\", ברענגט רש\"י ניט פון די אלע ערטער אין חומש12 נאר מוז אנקומען צו א פסוק פון נביא13!",[["1","1","פרשתנו יב, יז."],["2","2","ספרי כאן עה\"פ."],["3","3","יהושע טו, סג."],["4","4","יתרו יט, כג."],["5","5","תשא לג, כ."],["6","6","וראה גם מקץ מג, לב: לא יוכלון המצרים לאכול גו' כי תועבה היא גו'."],["7","7","טז, ה."],["8","8","יז, טו."],["9","9","כא, טז. כב, ג. שם, יט (ושם, כט). כד, ד."],["10","10","כן הקשה (על הספרי) גם בתו\"ת כאן, ונשאר בצ\"ע."],["11","11","ודוחק גדול לתרץ, דמאחר שזהו הלאו הראשון בלשון „לא תוכל\" הוצרך רש\"י לפרש שזהו לשון של אזהרה — כי בדברי ריב\"ק לא נאמר שזהו לאו, כ\"א רק שהתיבות „לא תוכל\" פירושן „אינך רשאי\" — ובשביל זה, אין צריכים למאמרו של ריב\"ק, מאחר שמצינו כ\"פ (וגם לפני פרשתנו) ד„לא תוכל\" פירושו „אינך רשאי\"."],["12","12","בשני כת\"י רש\"י שתח\"י מובא בפרש\"י (לפני הדוגמא ד„ואת היבוסי גו'\") „כיוצא בו לא תוכל לזבוח את הפסח יכול אתה ואינך רשאי\" — אבל בדפוס א' וב', רוב כת\"י רש\"י (שתח\"י) ודפוסים הנפוצים — לא הובאה דוגמא זו. וראה לקמן הערה 55."],["13","13","נוסף ע\"ז שכן הוא גם בת\"א כאן „לית לך"]]],[1300291095,"די תמי' איז נאך גרעסער: כמעט דעם זעלבן ענין ווי אין אונזער פרש\"י, איז רש\"י מפרש אויף די ווערטער „לא אוכל עוד לצאת ולבוא\" — אין פ' וילך14: יכול שחשש כחו כו' מהו לא אוכל איני רשאי שנטלה ממני הרשות וניתנה ליהושע — האט רש\"י דא געקענט ברענגען א דוגמא פון דעם פסוק אין חומש (וואו רש\"י אליין איז מדייק ומוכיח דעם תוכן אז „יכול אתה אבל אינך רשאי\") — און ניט א דוגמא דוקא פון נביא!\nאויך דארף מען פארשטיין:\nא) דרכו של רש\"י איז צו זאגן גלייך דעם פירוש פון ווארט (אדער פסוק) בלי צו זאגן די שאלה (או קושיא) שבתיבה — האט ער אויך בנדו\"ד געדארפט זאגן (בקיצור) „לא תוכל, אינך רשאי\".\nאע\"פ אז דאס איז דער לשון פון ריב\"ק — איז אבער ניט ענינו פון פרש\"י על התורה צו מעתיק זיין מאמרי חז\"ל בדיוק לשונם, כמדובר כמה פעמים15.\nב) דעם דיוק הידוע — פארוואס ברענגט רש\"י דעם מאמר בשם אומרו (רבי יהושע בן קרחה<sup data-n=\"16\">16</sup>, ניט ווי ברובא דרובא פון פירושי רש\"י, וואו ער דערמאנט ניט דעם שם בעל המאמר?\nוכמדובר כמה פעמים17, אז רש\"י טוט דאס נאר אין א פאל ווען דער שם בעל המאמר גיט צו א תוספת הבנה אין זיין פירוש.\nב. ווייטער אין דער דוגמא, איז רש\"י מאריך לבאר: כיוצא בו ואת3 היבוסי יושבי ירושלים לא יכלו בני יהודה להורישם יכולים היו אלא שאינן רשאין לפי שכרת להם אברהם ברית כשלקח מהם מערת המכפלה ולא יבוסים היו אלא חתיים היו אלא על שם העיר ששמה יבוס כך מפורש בפרקי דר\"א18 והוא שנאמר19 כי אם הסירך העורים והפסחים צלמים שכתבו עליהם את השבועה.\nדער מקור פון דער דוגמא איז מאמרו של ריב\"ק (אין ספרי<sup data-n=\"20\">20</sup>, אבער דארט שטייט בקיצור21 „כיוצא בו אתה אומר ואת היבוסי יושבי ירושלים לא יכלו להורישם יכולים היו אבל אינם רשאים\".\nעס איז מובן דער טעם פארוואס רש\"י באגנוגנט זיך ניט מיט דעם קיצור — ווייל רש\"י מוז דאך מבאר זיין דעם בן חמש למקרא פארוואס „אינם רשאים\" צו אייננעמען ירושלים, און דערפאר איז ער מוסיף לבאר אז אברהם האט כורת ברית געווען אז מ'וועט ניט אייננעמען עיר היבוסי22.",[["","","רשו\" (וראה „מצות . . כפי דעת הרמב\"ן\" (בהשגותיו בסוף סהמ\"צ להרמב\"ם) ל\"ת יב: ואונקלוס תרגם בכולם לית לך רשו)."],["14","14","לא, ב."],["15","15","ראה ס' כללי רש\"י (כפר חב\"ד תש\"מ) פ\"ח ס\"ב (בהוצאת תנש\"א פ\"ט ס\"ה). וש\"נ."],["16","16","ולהעיר שבפרש\"י ש\"ב (ה, ו) לפנינו: ר' יהושע בן לוי."],["17","17","ראה ס' כללי רש\"י שם ס\"ו ואילך (בהוצאת תנש\"א — פ\"ח סט\"ו ואילך). וש\"נ."],["18","18","פרק ל\"ו. — גם סיום פרש\"י (והוא שנאמר כו') מקורו בפדר\"א שם, אלא שבדפוס עם פי' הרד\"ל נשמט הפסוק „כי אם הסירך גו'\"!"],["19","19","ש\"ב ה, ו."],["20","20","פרשתנו עה\"פ (ובפרש\"י יהושע שם: שנינו בספרי ריב\"ק כו')."],["21","21","בחזקוני כאן ד„מה שפרש\"י בספר שמואל (שם) ואת היבוסי מזרעו של אבימלך היו היינו דלא כרבי יהושע\". ומשמע שמפרש שלשונו של רש\"י „לפי שכרת . . המכפלה\" הוא מדברי ר' יהושע. אבל נוסף שצ\"ע מנ\"ל הא — הרי מפורש בפרש\"י יהושע שם: ריב\"ק אומר כו' שלא היו רשאין מחמת השבועה . . לאבימלך."],["22","22","וכן הוזקק להוסיף „ולא יבוסים היו כו'\", שהרי אברהם לקח מערת המכפלה מעפרון החתי (ח\"ש כג, ח ואילך)."]]],[1300291096,"מען דארף אבער פארשטיין:\nג) פארוואס לערנט רש\"י אז די שבועה איז געווען „כשלקח (אברהם) מהם מערת המכפלה\" — וואס דאס ווערט כלל ניט דערמאנט אין חומש (נאר בלויז אין תורה שבע\"פ — אין פרקי דר\"א) — בשעת מען געפינט בפירוש אין חומש23 א כריתת ברית צווישן אברהם'ען מיט אבימלך; האט רש\"י (דוקא מצד פשוטו של מקרא) געדארפט לערנען אז דאס איז געווען די שבועה אויף ניט אייננעמען עיר היבוסי (ווייל די יבוסים האבן געשטאמט פון אבימלך<sup data-n=\"24\">24</sup>?\nדי תמי' איז נאך גרעסער: רש\"י אין נביאים25 זאגט טאקע אז „לא היו רשאין מחמת השבועה שנשבע אברהם לאבימלך\"26!\nד) למאי נפק\"מ בפשוטו של מקרא די הוספה פון רש\"י (אויפן לשון הספרי) בסיום פירושו „והוא שנאמר כי אם הסירך . . צלמים שכתבו עליהם את השבועה\"? ס'איז דאך ניט ענינו של רש\"י צו מפרש זיין בפירושו אויף חומש, פסוקים אין נביא.\nה) „כך מפורש בפרקי דר\"א\" — למאי נפק\"מ (ע\"ד הנ\"ל שאלה ב) דער מראה־מקום וואו דער ענין שטייט אין חז\"ל? אפילו אויב רש\"י מוז מדגיש זיין אז דער ענין איז גענומען געווארן פון חז\"ל (ווארום אין מקרא גופא ווערט ניט דערמאנט אזא שבועה) — האט רש\"י געקענט זאגן (כדרכו בכמה מקומות) „ורבותינו אמרו\" (וכיו\"ב). רש\"י איז ניט רגיל צו אנגעבן דעם מקור פון זיין פירוש בדיוק (ווי מען זעט אין דעם פרש\"י עצמו: רש\"י זאגט ניט אז מאמרו של ריב\"ק איז גענומען געווארן פון ספרי<sup data-n=\"27\">27</sup>.\nג. ויש לומר הביאור בכל זה:\nע\"ד הפשט איז מסתבר צו זאגן, אז דארט וואו די תורה זאגט אן אויף אן איסור בלשון „לא תוכל\" — אע\"פ אז דעמאלט איז דער טייטש פון „לא תוכל\" — „אינך רשאי\", איז דאס אבער נאר דאן ווען מען איז ניט שולל דעם פירוש הפשוט פון „לא תוכל\", אז מ'האט ניט די יכולת דאס צו טאן.\nדאס הייסט: ס'איז ניט דער פשט אז דורך דעם וואס די תורה אסר'ט אים צו טאן די זאך, ווערט ביי אים אוועקגענומען די מעגלעכקייט דאס צו טאן28 — ווייל אי משום הא, איז עס ניט אנדערש פון אלע איסורי התורה; און דערפון וואס נאר אין געציילטע ערטער אסר'ט תורה מיטן לשון „לא תוכל\" (וכיו\"ב) איז מובן, אז די אי־אפשריות צו טאן דעם איסור איז (ניט מצד דעם ציווי, נאר) מצד אן אנדער סיבה.",[["23","23","וירא כא, כג ואילך. וראה רש\"י דברים ב, כג."],["24","24","פרש\"י ש\"ב שם. שופטים א, כא. ובפרש\"י יהושע שם „ובני אותו מחוז מפלשתים היו\"."],["25","25","ביהושע שם. ועד\"ז בשופטים וש\"ב שם."],["26","26","אלא שי\"ל כי השבועה לאבימלך היתה רק „לניני ולנכדי\" (וכפרש\"י וירא שם „ע\"כ רחמי האב כו'\") — ומוכרחים לומר שבימי יהושע „עדיין הי' נכדו קיים\" (כפרש\"י שופטים שם. וראה מכילתא ר\"פ בשלח. ב\"ר פנ\"ד, ב. חולין ס, ב ובפרש\"י שם) — ולכאורה קשה לומר (בפשש\"מ*) שקרה נס כזה שהאריך ימים כ\"כ (וראה רש\"י לך טו, טז). *) ומ\"מ הביאו רש\"י בפירושו לנ\"ך — שאינו ע\"ד הפשט כ\"כ כמו פירושו עה\"ת (ראה ס' כללי רש\"י הנ\"ל פ\"ב סי\"ג (בהוצאת תנש\"א — פ\"ג ס\"ט). וש\"נ)."],["27","27","אף שכתבו בפירושו ליהושע (ראה שוה\"ג להערה הקודמת)."],["28","28","ראה באר יצחק על פרש\"י כאן."]]],[1300291097,"און דאס קען זיין אויף כמה אופנים, ולדוגמא29:\nא) עס איז אזא ענין וואס נאך דעם ווי תורה אסר'ט די זאך — קען ער די זאך ניט אויפטאן. וכמו: „לא יוכל לבכר את בן האהובה גו'\"30 — אפילו ווען דער אב וויל מבכר זיין דער „בן האהובה\", ווערט ער ניט קיין בכור31; „לא יוכל לשלחה גו'\"32 — אפילו אויב ער שיקט איר אוועק דארף ער איר צוריקנעמען33.\nב) א זאך וואס איז ניט תלוי ברצונו — וכמו: „לא תוכל לראות את פני כי לא יראני האדם וחי\"5; „לא תוכל לתת עליך איש נכרי גו'\"34 — ווייל, ווי די תורה איז דערנאך ממשיך35, „והי' כשבתו על כסא ממלכתו וכתב לו את משנה התורה גו' והיתה עמו וקרא בו כל ימי חייו גו' לשמור את כל דברי התורה הזאת גו'\" — וואס דאס אלץ איז אוממעגלעך ביי אן „איש נכרי אשר לא אחיך הוא\"; ועד\"ז דאס וואס שטייט ביי משה36 „לא אוכל עוד לצאת ולבא\" — וויבאלד אז „ניטלה ממני הרשות וניתנה ליהושע\"37, איז דאך ניט בידיו של משה „לצאת ולבא\", מ'האט שוין איבערגעגעבן די „רשות\" צו יהושע'ן, איז דאך צוגענומען פון משה'ן די אפשריות אויף „לצאת ולבא\".\nג) בשעת מ'איז שוין פריער אנגעזאגט געווארן ניט צו טאן א זאך — פאסט דערנאך דער לשון „לא תוכל\", אז מ'קען די זאך ניט טאן. וכמו: „לא יוכל העם לעלות אל הר סיני כי אתה העדותה בנו לאמר הגבל גו'\"38 (כלשון רש\"י, אז אידן זיינען שוין אויף דעם „מותרין ועומדין\"); „לא תוכל לזבוח את הפסח באחד שעריך גו'\"39 — וואס (נוסף לזה, אז הקרבת הפסח איז ניט תלוי נאר ברצונו, נאר אויך אין דעם כהן המקריב (כסוג השני הנ\"ל), איז) דער איסור צו מקריב זיין א קרבן בחוץ איז שוין געשטאנען פריער40 — „שמה תביאו גו' עולותיכם וזבחיכם גו' השמר לך פן תעלה עולותיך בכל מקום גו'\"; „לא תוכל להתעלם\"41 — וואס עס שטייט שוין בתחלת הענין42 „לא תראה גו' והתעלמת גו'\", און נאך דעם איז די תורה מסיים „לא תוכל להתעלם\".\nד. עפ\"ז וועט מען פארשטיין דעם חידוש פון אונזער פסוק — „לא תוכל לאכול בשעריך גו'\":\nבנדו\"ד איז נאך ניט געשטאנען אז „בשעריך\" טאר מען ניט עסן „מעשר גו' ובכורות בקרך גו' וכל נדריך גו' ותרומת ידך\" (עס איז נאר געשטאנען דער לאו „פן תעלה עולותיך בכל מקום גו'\"). קומט אויס, אז דער איסור אכילה ווערט מלכתחילה אנגעזאגט מיטן לשון „לא תוכל\" — און דערפאר שטעלט זיך רש\"י דא אפ און איז מחדש „יכול אתה",[["29","29","בהבא לקמן ראה גם הכתב והקבלה פרשתנו עה\"פ. — וראה לקמן הערה 52 עוד אופן שנאמר „לא תוכל\"."],["30","30","תצא כא, טז."],["31","31","ראה ספרי תצא שם „אינו מבוכר\". וראה השגות הרמב\"ן שבהערה 13 (ושם, ד„כן כל המקומות שבא בהן בתורה לא יוכל לעשות\")."],["32","32","שם כב, יט (ועד\"ז שם, כט)."],["33","33","ראה גיטין צ, א (וש\"נ) „עמוד והחזיר\"."],["34","34","שופטים יז, טו."],["35","35","שם, יח-יט."],["36","36","וילך לא, ב."],["37","37","פרש\"י שם."],["38","38","יתרו יט, כג."],["39","39","פרשתנו טז, ה."],["40","40","פרשתנו יב, יא. שם, יג."],["41","41","תצא כב, ג."],["42","42","תצא שם, א."]]],[1300291098,"אבל אינך רשאי\" — אז אויך אין אזא פאל פאסט דער לשון „לא תוכל\" (וויבאלד אז דער איסור התורה גופא איז שולל די מעגלעכקייט צו טאן די זאך).\nדאס איז אבער ניט א ביאור מספיק — ווייל:\nא) לפ\"ז, איז דאך אין הראי' דומה לנידון — אין דער דוגמא פון „ואת היבוסי . . לא יכלו גו' להורישם, יכולים היו אלא שאינן רשאין\", איז דער איסור ניט אנגעזאגט געווארן מיטן לשון „לא יכלו\" פון דעם פסוק, נאר ער קומט מצד דער פריערדיקער שבועה!\nב) אע\"פ אז א לאו מפורש אויף עסן מעשר וכו' בחוץ געפינט מען ניט פריער אין דער תורה, ווייס מען שוין אבער דעם איסור פון א פריערדיקן ציווי בלשון עשה43, „והבאתם שמה . . ואכלתם שם גו'\" — אזוי אז דער „לא תוכל\" דא איז ניט אנדערש לכאורה פון די אנדערע ערטער אין תורה וואו דער „לא תוכל\" שטייט בשייכות צו אן איסור וואס איז שוין אנגעזאגט געווארן פריער.\nג) וויבאלד „לא תוכל\" איז סו\"ס מתאים בא יעדן לאו — איז פארוואס נוצט תורה דעם לשון „לא תוכל\" דוקא ביי דעם לאו44?\nה. וועט מען דאס פארשטיין בהקדים הביאור אין דעם ערשטן דיבור פון רש\"י בפסוק זה: לא תוכל, בא הכתוב ליתן לא תעשה על הדבר.\nדעם לשון „ליתן ל\"ת כו'\", זאגט רש\"י אין נאך דריי ערטער בפרשתנו בסמיכות צו אונזער פסוק: א) השמר לך פן תעלה עולותיך בכל מקום אשר תראה — ליתן לא תעשה על הדבר45. ב) השמר לך פן תעזוב את הלוי גו' — ליתן לא תעשה על הדבר46. ג) את כל הדבר אשר אנכי מצוה גו' תשמרו לעשות — ליתן לא תעשה על עשה האמורים בפרשה47.\nאבער דוקא אין אונזער פסוק איז רש\"י מאריך בלשונו — „בא הכתוב ליתן לא תעשה על הדבר\"48.\nויש לומר הביאור בזה — בפשטות: אין די אנדערע דריי ערטער, איז דער פסוק ניט אויסן בלויז צו מוסיף זיין א לא תעשה — עס זיינען פאראן נאך חידושים אין די פסוקים: א) השמר גו' פן תעלה עולותיך בכל מקום אשר תראה — אשר יעלה בלבך, אבל אתה מקריב ע\"פ נביא כו' (פרש\"י). ב) השמר",[["43","43","פרשתנו יב, ו-ז. ואף שפסוק זה מדבר בשילה (רש\"י שם, יא. וראה רש\"י שם, ה), והעשה בנוגע לירושלים נאמר רק לקמן (פסוק יח) „כ\"א לפני ה\"א תאכלנו גו'\"* — הרי: א) בפרש\"י (שם, ו) דמש\"נ שם „מעשרותיכם\" כולל „לאכול לפנים מן החומה\"** (שבפשטות קאי על ירושלים). ב) ועוד ועיקר: מפשטות לשון רש\"י כאן „ליתן ל\"ת על הדבר\" מוכח, ש„הדבר\" כבר נאסר לפני\"ז (וכמ\"ש ברא\"ם וגו\"א כאן). ובפשטות י\"ל שמובן הוא במכש\"כ מהציווי „ואכלתם שם\" בנוגע לשילה. *) ולהעיר שע\"ד ההלכה לא נמנה כלל מ\"ע לאכול מעשר שני בירושלים (רק לאו שלא לאכלו חוץ מן החומה), ובמנ\"ח (מצוה תמב) „שיהי' מ\"ע מוטל שיאכל בירושלים . . לא שמענו מכל הראשונים\" (אבל ראה ריטב\"א מכות יט, ב). ואכ\"מ. **) ולהעיר, שלשון רש\"י ברמב\"ן שם „לפנים מן המחיצה\"."],["44","44","ראה ע\"ד ההלכה ספרי דבי רב לספרי פרשתנו כאן."],["45","45","יב, יג."],["46","46","שם, יט."],["47","47","יג, א."],["48","48","ראה גם רא\"ם ומשכיל לדוד כאן."]]],[1300291099,"לך פן תעזוב את הלוי כל ימיך על אדמתך — אבל בגולה אינך מוזהר עליו יותר מעניי ישראל (פרש\"י). ג) את כל הדבר גו' תשמרו לעשות לא תוסף עליו ולא תגרע ממנו.\nמשא\"כ אין אונזער פסוק „לא תוכל לאכול בשעריך גו'\" איז „בא הכתוב ליתן לא תעשה על הדבר\" — דער פסוק קומט מער ניט ווי צו מוסיף זיין א לא תעשה49.\nאבער הא גופא דארף האבן א ביאור: למאי נפק\"מ די הדגשה, אז די גאנצע כוונה פון פסוק איז „ליתן לא תעשה\"?\nאיז דעריבער מסתבר לומר, אז דא מוז מען האבן דעם לא תעשה: (ניט ווי אין אנדערע ערטער, נאר אויף צו מוסיף זיין אין חומר הדבר, אין עונש וכו' —) בנדו\"ד איז דא א ספעציעלע הדגשה אין דעם בפירוש'ן לאו, און דערפאר איז דא אויף דעם א כתוב מיוחד.\nו. ויש לומר דעם ביאור אין דעם:\nדא רעדט זיך וועגן מעשר וקדשים כו' וואס אכילתם איז א מצוה. דעריבער וואלט מען געקענט מיינען (אין לימוד ע\"ד הפשט), אז דאס וואס עס איז דא א ציווי זיי צו (ברענגען און) עסן אין ירושלים, איז דאס א מצוה נוספת אויף מצות אכילת מעשר וקדשים כו' בכלל. דאס הייסט, מ'וואלט געזאגט אז דאס זיינען צוויי מצות, וועלכע זיינען ניט תלוי איינע אין דער צווייטער: (א) אכילת מעשר וקדשים כו'. (ב) אכילתם בירושלים, „במקום אשר יבחר ה'\"50:\nולכן, ווען איינער איז אן אנוס און קען ניט עסן זיין מעשר אדער קדשים כו' אין ירושלים, וואלט געווען א קס\"ד לומר51, אז ער (קען, ואדרבה —) מוז עסן זיי במקומו „בשעריך\", צו מקיים זיין עכ\"פ די מצוה פון אכילת מעשר וקדשים כו'\n— אויף דעם „בא הכתוב ליתן לא תעשה על הדבר\" — אז אכילה בירושלים איז ניט א מצוה נוספת, נאר ס'איז א תנאי לעכובא, מען טאר זיי ניט עסן במקום אחר.\nאון דאס איז דער המשך אין פרש\"י: נאך דעם ווי ער איז מפרש אז די כוונה (כללית) פון דעם פסוק איז „(בא הכתוב) ליתן לא תעשה על הדבר\", איז ער מפרש די ווערטער „לא תוכל\" — „יכול אתה אבל אינך רשאי\", ווייל לאחרי ווי מען ווייס אז „בא הכתוב ליתן לא תעשה על הדבר\", ווערט שוין פארשטאנדיק פארוואס די תורה זאגט אן דעם איסור בלשון „לא תוכל\".\nוהביאור בזה:\nמיט „יכול אתה\" מיינט רש\"י (ניט נאר די גשמית'דיקע יכולת צו עסן חוץ לירושלים — דמאי קמ\"ל?! — נאר) די מצוה־יכולת52 צו עסן „בשעריך\" מצד",[["49","49","בפרש\"י תבא (כו, יד) שמהכתוב „לא תוכל לאכול בשעריך\" למדין אזהרה ל„אכילת טומאה\". אבל נוסף על מ\"ש הרא\"ם כאן ד„עיקר הלאו הזה ופירושו אינו אלא אזהרה לאכלו חוץ מן החומה\" — הרי מזה שרש\"י מביאו רק לקמן בפ' תבא ולא בפרשתנו על אתר, מוכח, שפשש\"מ דהכתובים דפרשתנו מכריח רק ד„בא הכתוב ליתן ל\"ת כו'\", ולא שיש כאן דין חדש (וראה ס' כללי רש\"י פ\"ד סי\"ב-י\"ג (בהוצאת תנש\"א — סי\"ט-כ). וש\"נ). ועוד."],["50","50","כבכתוב שלאח\"ז כאן — יב, יח (וראה גם שם, יא)."],["51","51","ראה גם גו\"א כאן."],["52","52","ראה צפע\"נ עה\"ת כאן (ועוד), ד„כ\"מ דנאמר לא תוכל ר\"ל דאף גרם לזה אסור . . עדיין ליכא לאו\" (וראה שם האופנים שאינו חייב גבי מעשר). ולהעיר ממלבי\"ם כאן שהלשון „לא תוכל\" בא „לרוב במקום שבענין אחר יכול לעשות כן . . נגד מ\"ש שבעת היתר הבמות יוכלו לאכול שלמים בכ\"מ עתה"]]],[1300291100,"(סברא הנ\"ל פון דער) מצוה פון אכילת מעשר וקדשים כו' (כנ\"ל): און אין דעם איז דער פסוק מחדש — „לא תוכל . . אינך רשאי\", די אזהרה איז שולל די מצוה־יכולת. ד.ה. מיט דעם לאו איז דער פסוק מחדש, אז חוץ לירושלים איז ניטא די מצוה פון אכילת מעשר וקדשים כו'.\nועפ\"ז וועט מען אויך פארשטיין פארוואס רש\"י ברענגט די דוגמא דוקא פון נביאים („ואת היבוסי גו'\") — ווייל דוקא דארטן איז עס בהתאם צום חידוש אין אונזער פסוק:\nצו כובש זיין „יבוסי יושבי ירושלים\" איז לכאורה דא א ציווי53 — „והורשתם את כל יושבי הארץ גו' וישבתם בה גו' והתנחלתם את הארץ גו'\" — ובמילא איז דער „יכולים היו\" ניט נאר מצד דער גשמיות'דיקער גבורה פון אידן54, נאר מצד ציווי השם — און דאס באווארנט די תורה, אז מצד דער שבועה איז „לא יכלו להורישם\", „שאינן רשאין\". ד.ה. אז דער „לא יכלו — אינן רשאין\", איז מצד דער שבועה, דער ציווי פון כיבוש הארץ איז מלכתחילה ניט חל בנוגע צו יבוסי [ע\"ד נדו\"ד, וואס „לא תוכל לאכול בשעריך\" איז מגלה אז „בשעריך\" איז ניטא די מצוה55 פון אכילת מעשר וכו'].\nז. לכאורה איז אבער אינגאנצן ניט פארשטאנדיק — ווי קען מען זאגן, אז מצד דער שבועה צו די בני חת זאל ניט חל זיין ציווי השם צו אייננעמען גאנץ ארץ ישראל — אדרבה, דער ציווי השם (לאחרי מ\"ת) דארף דאך מבטל זיין56 די התחייבות שמצד השבועה לפני זה!\nאיז דער ביאור אין דעם:\nאע\"פ אז מצד הדין האט די שבועה ניט געהאט קיין תוקף (מצד דעם ציווי השם צו כובש זיין א\"י)57 — פונדעסטוועגן, וויבאלד אז לפי דעת היבוסיים האט די שבועה יע געהאט א תוקף, איז אויב אידן וואלטן זיך ניט גערעכנט מיט דער שבועה, וואלט ארויסגעקומען א חילול השם. און דעריבער „לא יכלו . . להורישם . . שאינן רשאין\" — ווייל מצד דעם ענין פון חילול השם האבן זיך",[["","",". . לא תוכל כו'\"* — וראה פרש\"י תבא (שם) „לא תוכל . . בפסולי המוקדשים בשעריך תאכלנו . . אבל זה לא תוכל לאכול דרך אכילת שעריך האמור במקום אחר\". *) ומה שלא פירש רש\"י כן — י\"ל, משום שהיתר הבמות שייך (בעיקר) להקרבת השלמים ולא לאכילתם, וא\"כ הול\"ל „לא תוכל\" גבי איסור ההעלאה „בכל מקום\" (לעיל פסוק יג). ועוד י\"ל. ואכ\"מ."],["53","53","מסעי לג, נב ואילך (ועוד)."],["54","54","ראה פדר\"א שם: והלא היו ישראל כחול הים."],["55","55","ואולי יש לבאר הגירסא בפרש\"י (ראה לעיל הערה 12) שהובאה דוגמא מ„לא תוכל לזבוח את הפסח\" — ע\"פ משנ\"ת במק\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300281072\" data-slug=\"likkutei-sichot\" data-id=\"1300281072\">לקו\"ש חכ\"ח ע' 72</a> ואילך) שפסח מצרים לא הי' לו דין קרבן, כ\"א רק „זבח\" שכאו\"א שחט בביתו דוקא כו'; ולכן היתה קס\"ד שיכולים להביא פסח בטומאה (בהעלותך ט, ו ואילך) — כי חשבו דזה שפסח דורות מקריבים ע\"ג המזבח הוא רק ענין נוסף בהפסח (ע\"ש באורך ובהערה 46 שם), ועד\"ז בנדו\"ד, שהוצרך הכתוב להזהיר „לא תוכל לזבוח את הפסח באחד שעריך גו'\" — לשלול ה„מצוה־יכולת\" לזבוח את הפסח באחד שעריך (כמו פסח מצרים)*, ומשמיענו בזה, ש„באחד שעריך\" מלכתחילה אין מצוה לזבוח הפסח. *) להעיר גם מחזקוני עה\"פ (טז, ה) „לא תוכל לזבוח את הפסח\"."],["56","56","וראה רד\"ל לפדר\"א שם אות צו."],["57","57","והלאו דלא תחי' ביטל השבועה תיכף בכניסתם עוד קודם שבע שכבשו."]]],[1300291101,"אידן געפירט כאילו ווי די שבועה האט א תוקף.\n[ע\"ד ווי מען געפינט ביי די גבעונים, וואס „ויכרות להם ברית לחיותם וישבעו גו'\"58, און דערפאר „לא נוכל לנגוע בהם\"59 — אז אע\"פ אז „לא חיילה שבועה עילוייהו כלל\"60 (ווייל די גבעונים האבן אויסגענארט אידן), פונדעסטוועגן „לא קטלינהו משום קדושת השם\"60].\nועפ\"ז יש לבאר פארוואס רש\"י איז מפרש אז די שבועה איז (ניט די שבועת אברהם לאבימלך, נאר) די כריתת ברית „כשלקח מהם מערת המכפלה\" — ווייל דאס איז נאכמער מגדיל דעם חילול השם שבדבר (ווען אידן וואלטן זיך ניט געפירט ע\"פ די שבועה):\nלויט דער כריתת ברית מיט די בני חת, איז דער העדר הכיבוש פון ירושלים ווי א תנאי אין קנין פון מערת המכפלה. קומט אויס, אז ווען עס וואלט ניט אפגעהיט געווארן די שבועה, וואלט (לדעת היבוסים) בטל געווארן למפרע קנינו של אברהם במערת המכפלה61, ובמילא, אז די אבות ואמהות זיינען געווען קבורים בקבר לא להם62!\nאון צו פארשפארן דעם חילול השם (אז די יבוסיים וועלן זאגן אז אידן ארט ניט אז די אבות ואמהות זיינען קבורים בקבר לא להם) איז „לא יכלו . . להורישם\".\nח. רש\"י קען זיך אבער ניט מסתפק זיין מיט דעם אליין — ווייל דער „בן חמש למקרא\" וועט דאך פרעגן: וויבאלד אז מצד חילול השם האבן אידן ניט געטארט אייננעמען עיר היבוסי — איז ווי האט מען דאס סוף־סוף פון זיי צוגענומען63?\nדערפאר מוז רש\"י מסיים זיין „והוא שנאמר כי אם הסירך העורים והפסחים צלמים שכתבו עליהם את השבועה\": דוד המלך האט צוגענומען די צלמים אויף וועלכע עס איז געשריבן געווארן די שבועה, אזוי ארום איז בטל געווארן דער זכרון פון דער שבועה (וכמובן בפשטות, אז נאך דעם ווי ס'איז שוין אדורך בערך 800 יאר פון דער כריתת ברית מיט די בני חת, האט מען גרינג געקענט בטל מאכן דעם זכרון פון דער",[["58","58","יהושע ט, טו."],["59","59","שם, יט."],["60","60","גיטין מו, א. רמב\"ם הל' מלכים פ\"ו ה\"ה."],["61","61","ראה גם פי' תולדות אדם לספרי כאן. ואף שאמר אברהם „אטלנה מן הדין\" (רש\"י ח\"ש כג, ד), וכמו שהקשה בתולדות אדם שם (ושם, שהקני' היתה רק „לרווחא דמילתא\". וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101062\" data-slug=\"likkutei-sichot\" data-id=\"1300101062\">לקו\"ש ח\"י ע' 62</a> ואילך) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151146\" data-slug=\"likkutei-sichot\" data-id=\"1300151146\">— הרי ע\"ד</a> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151204\" data-slug=\"likkutei-sichot\" data-id=\"1300151204\">הפשט, ע\"י</a> הבטחת הקב\"ה לאברהם עדיין לא נקנית לו הארץ בפועל (כמשנ\"ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151150\" data-slug=\"likkutei-sichot\" data-id=\"1300151150\">לקו\"ש חט\"ו ע' 146-7</a> (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410147\" data-slug=\"likkutei-sichot\" data-id=\"1301410147\">וראה שם ע' 204</a> ובהערות שם). וראה שם ע' 150 ואילך ביאור בלשון רש\"י „אטלנה מן הדין\"*). *) ע\"פ המבואר לקמן הערה 66 שקנין מערת המכפלה הי' רק על הבעלות הפרטית (ולא הבעלות הכללית, דמלכות בני חת) — יש לומר, שכוונת אברהם היתה: באם ימכרו לו הבעלות הפרטית דמערת המכפלה הרי טוב; ובאם לאו, הרי בזה איגלאי מילתא שעתה כבר בא הזמן לקיום ההבטחה „לזרעך אתן את הארץ הזאת\", ויקח ממנו גם הבעלות הכללית. ואכ\"מ. וראה לקו\"ש ח\"ל ס\"ע 83 ואילך."],["62","62","ואולי י\"ל דשייך גם לבעלות בנ\"י על א\"י — כי הנחלה הראשונה של עם ישראל בא\"י היתה צ\"ל באופן „שאין אוה\"ע יכולין . . לומר גזולים הן בידם\", שזה נעשה ע\"י קניית אברהם דוקא (ב\"ר פע\"ט, ז). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251091\" data-slug=\"likkutei-sichot\" data-id=\"1300251091\">לקו\"ש חכ\"ה ע' 91</a>."],["63","63","משא\"כ להפירוש שנאסר מצד השבועה לאבימלך — הרי „בימי דוד כבר עברו הדורות שהוזכרו בהשבועה\" (רש\"י ש\"ב ה, ח. וראה רד\"ק שם, ו (וכן ביהושע טו, סג). חזקוני פרשתנו כאן. ועוד. — וברש\"י סוטה י, רע\"א: לפי שהם עברו על השבועה תחלה). — וראה לעיל הערה 26."]]],[1300291102,"שבועה דורך מסיר זיין די „צלמים שכתבו עליהם את השבועה\").\n[און דאס איז דער דיוק „כי אם הסירך העורים והפסחים צלמים שכתבו עליהם את השבועה\": דא האט זיך ניט געפאדערט צו מסיר זיין די שבועה עצמה — די שבועה איז בלאה\"כ בטל, תקפה איז הוסר; מען דארף נאר מסיר זיין די צלמים64 אויף וועלכע ס'איז פארשריבן געווארן די שבועה, צו מבטל זיין דעם חילול השם שבדבר65].\nסוף־סוף איז אבער פארט ניט גלאטיק: וויבאלד אז עס זיינען געווען לעבעדיקע יבוסיים וועלכע האבן יע געוואוסט פון דער שבועה (און האבן געזאגט דוד'ן „לא תבא הנה כי אם הסירך גו'\") — איז כלפי זיי, וואס האט אויפגעטאן די הסרת העורים והפסחים?\nדערפאר איז רש\"י מציין צו פרקי דר\"א — „כך מפורש בפרקי דר\"א\": אין פרקי דר\"א, נאך דעם ווי עס ווערט דערציילט וועגן שבועת אברהם וכו', שטייט דארט „ואח\"כ קנה (דוד) את עיר היבוסי לישראל66 בכתב עולם לאחוזות עולם . . שש מאות שקלים כו'\"; און וויבאלד דוד האט קונה געווען עיר היבוסי בכסף מלא67, האט דאס אינגאנצן מבטל געווען וועלכע־עס־איז טענה פון דעם יבוסי אויף עיר ירושלים68.\nט. ע\"פ כל הנ\"ל יש לבאר פארוואס רש\"י ברענגט דעם מאמר בשם אומרו — ר' יהושע בן קרחה:\nא תלמיד „ממולח\" קען דאך פרעגן: וויבאלד א איד האט די מצוה פון אכילת מעשר וקדשים כו' — ווי וועט ער מסביר זיין זיך וואס ער איז אן אנוס און קען ניט גיין קיין ירושלים און דערפאר לא תוכל לאכול אפילו בשעריך?\nזאגט רש\"י אז דעם מאמר האט געזאגט ר' יהושע בן קרחה: פון די באוואוסטע מאמרים פון ר' יהושע בן קרחה איז דער מאמר69 — „למה קדמה פרשת שמע לוהי' אם שמוע כדי שיקבל עליו עול מלכות שמים תחלה ואחר כך מקבל עליו עול מצות\".\nאון דאס איז די הסברה בעניננו: איידער א איד האט קבלת עול מצות, דארף ביי אים פריער זיין קבלת „עול מלכות שמים\", דעם עול פון מלך מה\"מ הקב\"ה, וואס ער האט אנגעזאגט „לא תוכל לאכול בשעריך גו' כי אם לפני ה' אלקיך תאכלנו במקום אשר יבחר ה' אלקיך בו\".\n(משיחת ש\"פ ראה תשכ\"ז)",[["64","64","ואולי מרמז רש\"י בתיבה זו, שהי' בזה גם ענין של ביטול ע\"ז (כהציווי בפרשתנו (יב, ג) ועוד „ופסילי אלקיהם תגדעון\") — ראה גם רד\"ל לפדר\"א שם (ולגירסת הערוך (ערך עור) והרד\"ק (ש\"ב שם) — כן מפורש בפדר\"א שם: שנואי נפש דוד שונא מלשמוע ומלעבוד עבודת אלילים). ועפ\"ז יומתק זה שלא הביא רש\"י כאן מה שכתב בפירושו לש\"ב שם ד„העורים והפסחים\" היו „על שם יצחק ויעקב כו'\" — כי כאן ההדגשה שהיו פסילים של ע\"ז."],["65","65","ראה גם חי' ופי' מהרי\"ק על פרש\"י כאן. רד\"ל שם. ועוד."],["66","66","תיבה זו, לכאורה י\"ל שהיא מדגישה עוד ענין — מלכות ישראל, לא אחוזת אישי מבנ\"י (דוד) שנמצאת במלכות היבוסי — משא\"כ בקנין מערת המכפלה שלא מצינו שכבש אברהם מלכות בני חת (ונפק\"מ בנוגע למסים, דינא דמלכותא, דיני המלך דפורץ גדר וכו' בארץ מלכותו וכו'). ועפ\"ז יל\"ע במש\"כ בפנים (ובהערות). ואכ\"מ. וראה בארוכה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410146\" data-slug=\"likkutei-sichot\" data-id=\"1301410146\">לקו\"ש ח\"ל ע' 82</a> ואילך. *) כמפורש בהמשך הלשון שם „לקח מכל שבט כו'\"."],["67","67","דה\"א כא, כב-כד."],["68","68","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101062\" data-slug=\"likkutei-sichot\" data-id=\"1300101062\">לקו\"ש ח\"י ע' 62</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151105\" data-slug=\"likkutei-sichot\" data-id=\"1300151105\">וראה ע\"ד</a> ההלכה לקו\"ש חט\"ו ע' 105 שוה\"ג להערה 45. וש\"נ."],["69","69","משנה ברכות רפ\"ב. — בנוגע לענין הכי מפורסם: קבלת עול מ\"ש וכו', מצות ק\"ש וכו'."]]],[1300291103,"<h3>ראה ג</h3>\nא. אויפן פסוק1 „לא תאכל כל תועבה\" איז רש\"י מפרש: כל תועבה — כל שתעבתי לך כגון צרם אזן בכור כדי לשוחטו במדינה הרי דבר שתעבתי לך כל מום לא יהי' בו2 ובא ולמד כאן שלא ישחט ויאכל על אותו המום (און דערנאָך ברענגט רש\"י אַ צווייטע דוגמא פון „בשל בשר בחלב\", כדלקמן ס\"ד).\nדאָס הייסט, אַז דער טייטש פון „לא תאכל כל תועבה\" איז — אַז אויב ס'איז געטאָן געוואָרן אין אַ זאַך אַ פעולה וואָס „תעבתי לך\", וואָס תורה האָט גע'אסר'ט טאָן — איז „לא תאכל\", ווערט די זאַך אסור באכילה3.\nאון דער טעם פאַרוואָס רש\"י לערנט ניט אַז דער פסוק „לא תאכל כל תועבה\" איז אַ הקדמה כללית צו דער פרשה פון מאכלות אסורות4 און „כל תועבה\" באַציט זיך צו די מאכלות אסורות, אַז זיי זיינען „נתעבים לנפש הטהורה\"5 — איז6 ווייל, ווי גערעדט כמה פעמים7, אַז וואו נאָר מעגלעך, דאַרף מען איינלערנען אַז די תורה איז אויסן צו זאָגן אַ נייעם ציווי ודין (און ניט זאָגן, אַז דער ציווי קומט בלויז מוסיף זיין נאָך אַ לאו ואזהרה אין אַ ציווי מפורש<sup data-n=\"8\">8</sup>,\nאון דערפאַר לערנט רש\"י אַז „לא תאכל כל תועבה\" איז מחדש אַ נייעם סוג איסור אכילה (וואָס מען ווייס ניט פון פריערדיקע פסוקים) — „כל שתעבתי לך\" איז אסור באכילה, און ווי רש\"י איז מדייק בהמשך פירושו — „ובא ולמד כאן שלא ישחט ויאכל\".\nב. מען דאַרף אָבער פאַרשטיין די דוגמא וואָס רש\"י גיט פון „צרם אזן בכור כו'\":\nוויבאַלד דער „דבר שתעבתי לך\" בנדו\"ד איז די תועבה פון „כל מום לא יהי' בו\", וואָס רעדט ניט בלויז וועגן אַ בכור, נאָר וועגן יעדן „זבח שלמים\" — פאַרוואָס ברענגט רש\"י די דוגמא דוקא פון „צרם אזן בכור\" (ובפרט אַז דאָס איז ניט אַ דבר רגיל והווה<sup data-n=\"9\">9</sup>? — רש\"י האָט",[["1","1","פרשתנו יד, ג."],["2","2","אמור כב, כא. — ולהעיר שלכאורה בפשש\"מ אין כוונת הכתוב לאסור הטלת מום בקדשים כ\"א רק לאסור הקרבת קרבן עם מום, „כי יקריב גו' כל מום לא יהי' בו\" [משא\"כ ע\"ד ההלכה שלמדים מ„כל מום לא יהי' בו\" — „אל תתן בו מום\" (תו\"כ עה\"פ. בכורות לג, סע\"ב ואילך. ובכ\"מ)]. ואולי יש לומר ע\"פ פרש\"י אמור שם, כב: שלשה פעמים להזהיר על הקדשן כו' — שמזה מובן, דכשם שאסור להקדיש בע\"מ, כך אסור להטיל מום בקדשים."],["3","3","אלא שאינו כלל בכל האיסורים — ראה בארוכה חולין קיד, ב ואילך ובמפרשים שם. רא\"ם וגו\"א (ועוד מפרשי רש\"י) כאן. לקמן הערה 15."],["4","4","ראה ראב\"ע, רמב\"ן, ספורנו, אברבנאל ועוד."],["5","5","ל' הרמב\"ן. ועד\"ז בראב\"ע. וראה אברבנאל בארוכה."],["6","6","ראה גם באר יצחק על פרש\"י כאן."],["7","7","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161332\" data-slug=\"likkutei-sichot\" data-id=\"1300161332\">לקו\"ש חט\"ז ע' 332</a> הערה 36. ועוד. — וגם ע\"ד ההלכה כ\"ה, ד„כל היכא דאיכא למדרש דרשינן ולא מוקמינן בלאוי יתירי\" (פסחים כד, ריש ע\"ב)."],["8","8","ברמב\"ן כאן ש„רצה להוסיף באור במאכלים האסורים\" (שטעם איסורם הוא מפני שהם „נתעבים לנפש הטהורה . . יולידו עובי ואטימות בנפש\") — אבל פשטות לשון הכתוב היא, שבא להוסיף אזהרה ולאו (ולא רק „באור\"). וראה גם רש\"י שמיני יא, מד."],["9","9","ע\"ד „דיבר הכתוב בהווה\" (רש\"י משפטים כב, ל. פרשתנו טו, יט. ובכ\"מ)."]]],[1300291104,"געקאָנט זאָגן באופן כללי10: כגון מטיל מום בקדשים11.\nדי שאלה איז נאָך גרעסער: דער מקור פון פרש\"י איז אין ספרי על הפסוק, אָבער דאָרט ברענגען זיך צוויי דיעות: „ר' אליעזר אומר מנין לצורם אוזן של בכור ואכל ממנה שעובר בל\"ת ת\"ל לא תאכל כל תועבה, אחרים אומרים בפסולי המוקדשים הכתוב מדבר\".\nזיינען מפרשים12 מבאר, אַז לויט דעת „אחרים\" איז „צורם אוזן של בכור\" ניט אין גדר פון „לא תאכל כל תועבה\" — וויבאַלד אַז אַ בכור בעל מום איז מותר באכילה אָן קיין פדיון, איז עס דעריבער ניט קיין דבר מתועב; נאָר דוקא פסולי המוקדשים וואָס דאַרפן פריער האָבן פדיון זיי צו מתיר זיין באכילה, זיינען זיי אין גדר פון „תועבה\" און זיינען דערפאַר אסור באכילה.\nאיז ניט מובן: פאַרוואָס ברענגט רש\"י די דוגמא פון „צרם אוזן בכור\" (און איז דערמיט מכריע — בפשוטו של מקרא13 — כדעת ר\"א<sup data-n=\"14\">14</sup>, און זאָגט ניט די פשוט'ערע און כללות'דיקע דוגמא פון „פסולי המוקדשים\" (אָדער ברענגען בלויז די צווייטע דוגמא „בשל בשר בחלב\"<sup data-n=\"15\">15</sup>?\nג. אויך דאַרף מען פאַרשטיין די אריכות לשון רש\"י אין דער דוגמא, דלכאורה האָט רש\"י געקענט זאָגן בקיצור16 „כגון צרם אוזן בכור הרי דבר שתעבתי לך כל מום לא יהי' בו ובא ולמד כאן שלא יאכל\".\nפאַרוואָס איז רש\"י מוסיף:\nא) „כדי לשוחטו במדינה\"17 — למאי נפק\"מ אַז די כוונת האדם בעת צרימת אוזן הבכור איז געווען „כדי לשוחטו במדינה\"? אפילו ווען מ'האָט ניט מכוין געווען „לשוחטו במדינה\" האָט מען דאָך געטאָן אַ „דבר שתעבתי לך\" — „כל מום לא יהי' בו\"18.",[["10","10","ע\"ד לשון הרמב\"ם הל' פסולי המוקדשין פי\"ח ה\"ג-ה (וראה סהמ\"צ שלו מל\"ת קמ. חינוך מצוה תסט)."],["11","11","שמותרים במדינה (ע\"י פדיון), כפרש\"י לעיל (פרשתנו יב, טו)."],["12","12","ספרי דבי רב ותולדות אדם לספרי שם (ומתרצים עפ\"ז שיטת הרמב\"ם בהל' פסוה\"מ שם. ע\"ש). וראה תוד\"ה ומי — בכורות (לד, סע\"א ואילך). תוד\"ה רבא — תמורה ד, סע\"ב [אבל בתוד\"ה כל (חולין קטו, א — נעתק ברא\"ם כאן): דשרי רחמנא קדשים שהוממו כצבי ואיל א\"כ אינו דבר מתועב — דממ\"ש „קדשים\" (אף שמדבר בבכור) מוכח דס\"ל דלאו דוקא בכור. ואכ\"מ]."],["13","13","והרי חילוק זה (דבכור בע\"מ אין צריך פדיון) הוא גם ע\"פ פשש\"מ (כפרש\"י פרשתנו לקמן טו, כג)."],["14","14","וכן מכריע דצרם אוזן בכור אסור באכילה מה\"ת, ולא רק מצד קנס דרבנן (ראה בכורות לד, סע\"א ואילך ובתוד\"ה ומי שם. תוד\"ה רבא תמורה שם. וראה תוד\"ה כל חולין שם. מפרשי רש\"י כאן. ואכ\"מ)."],["15","15","ולהעיר מכו\"כ מהאופנים שהובאו בחולין שם (כמו: המבשל בשבת, כלאי זרעים ועוד), שלכאורה הטעמים שבגמ' שם שלא נאסרו מצד „לא תאכל כל תועבה\" אינם מתאימים בלימוד ע\"ד הפשט (וראה הנסמן בהערה 3); ואת\"ל שע\"ד הפשט יש בהם האיסור ד„לא תאכל — כל שתעבתי לך\", הי' אפשר לרש\"י להביא דוגמא יותר פשוטה. [ולפי המסקנא לקמן (סעיף ו-ז) יש לומר הטעם שרש\"י לא הביא א' מהדוגמאות הנ\"ל — כי מעדיף רש\"י הדוגמא שבחז\"ל, מכיון ש(גם) היא מתאימה בלימוד ע\"ד הפשט]."],["16","16","כבספרי. אלא שרש\"י (א) צריך להוסיף מהי ה„תועבה\" — „כל מום לא יהי' בו\" (ובפרט ע\"פ הנ\"ל הערה 2). (ב) מדגיש „ובא ולמד כאן\", כנ\"ל ס\"א."],["17","17","שהרי אין רש\"י צריך להודיע הדין שבכור בע\"מ נאכל במדינה — כי כבר מפורש הוא בפרש\"י לעיל (יב, טו) בנוגע לכל הקדשים (ולקמן טו, כב מפורש בכתוב גבי בכור). ובכל אופן — דבר זה (שמותר לאכול בכור בע\"מ במדינה) מובן בלאה\"כ מהמשך לשון רש\"י כאן „ובא ולמד כאן שלא ישחט ויאכל\"."],["18","18","ע\"ד ההלכה (משנה בכורות לה, א ובפרש\"י"]]],[1300291105,"ב) „(ובא ולמד כאן) שלא ישחט ויאכל\" — פאַרוואָס דאַרף רש\"י צוגעבן דעם וואָרט „ישחט\"19?\nג) פון דעם סיום ל' רש\"י „על אותו המום\" איז משמע, אַז רש\"י מיינט מדייק זיין, אַז דוקא „על אותו המום\" לא ישחט, אָבער „נולד בו מום אחר — ישחוט עליו\"20.\nאיז ניט מובן:\n(א) וואָס איז דער הכרח אין פשוטו של מקרא אַז אַ צווייטער מום נעמט אַראָפּ דעם איסור אכילה וואָס האָט זיך געלייגט אויפן בכור מצד „לא תאכל כל תועבה\"21? צי ווייל ס'איז נולד געוואָרן אין דער בהמה נאָך אַ מום, ווערט דערמיט בטל די „תועבה\" וואָס האָט זיך אין איר געשאַפן דורך הטלת המום באיסור?!\n(ב) אפילו אויב מ'וועט געפינען אַ הסברה בזה — איז נאָך אַלץ ניט מובן: למאי נפק\"מ בפשוטו של מקרא צי דער איסור אכילה בלייבט לעולם, אָדער בלויז ביז „נולד בו מום אחר\"? פירוש רש\"י איז דאָך ניט קיין ספר הלכות וואָס דאַרף באַוואָרענען ווי דער ענין איז להלכה.\nד. ווייטער זאָגט רש\"י אַ צווייטע דוגמא אויף „דבר שתעבתי לך\" — „בשל בשר בחלב הרי דבר שתעבתי לך והזהיר כאן על אכילתו\".\nאיז תמוה (ווי מפרשים22 פרעגן): רש\"י האָט שוין (צוויי מאָל<sup data-n=\"23\">23</sup> מפרש געווען אַז „בג' מקומות נכתב בתורה24 (דער ציווי פון „לא תבשל גדי בחלב אמו\") א' לאיסור אכילה וא' לאיסור הנאה וא' לאיסור בישול\" — פאַרוואָס דאַרף מען האָבן אַ באַזונדער לאו אויף איסור אכילתו, בשעת עס איז סייווי אסור מצד דעם לאו פון „לא תאכל כל תועבה\"?\nדער מקור פון דעם פירוש רש\"י („בשל בשר בחלב כו'\") איז אין גמרא25 — „מנין לבשר בחלב שאסור באכילה",[["","","שם) „לדעתו (שנתכוין להתירו) אסור שלא לדעתו מותר\". אבל זהו משום שלפי סוגיית הגמ' האיסור הוא רק משום קנס (ולכן — שלא לדעתו אין מקום לקנס); אבל לפרש\"י בפשש\"מ שהוא דין תורה מצד שנעשה בו „דבר שתעבתי לך\" — מאי נפק\"מ כוונת האדם בזה?*"],["19","19","בפשטות — לשון זה ברש\"י הוא אגב לשונו לפנ\"ז „כדי לשוחטו במדינה\". אבל הא גופא דורש ביאור — דהו\"ל (כלישנא דקרא) „לאוכלו\"."],["20","20","דעת חכמים במשנה בכורות (לד, סע\"א) [משא\"כ לדעת ר\"א ד„לא ישחוט עולמית\"]. וראה הערה הבאה. ואכ\"מ."],["21","21","שהרי אין האיסור כאן מפני שהמטיל מום באיסור נשאר עליו איסור אכילה במדינה מחמת קדושת בכור (שאז מקום לומר שע\"י מום אחר שוב נפקע (קדושת בכור, ובמילא) האיסור) — כ\"א שאסור באכילה רק מחמת „לא תאכל כל תועבה\", ולמה יותר אח\"כ ע\"י מום אחר (ולהעיר מרש\"י חולין שם (קיד, ב) ד\"ה הרי הוא בבל תאכל: עולמית). ושאני דעת חכמים במשנה בכורות שם — כי לשיטתם ה\"ז רק קנס, כבהמשך הסוגיא שם (וכנ\"ל הערה 18. אבל ראה צפע\"נ עה\"ת פרשתנו כאן). אלא שברמב\"ם הל' פסוה\"מ שם מוכח, דגם האיסור מה\"ת (מצד „לא תאכל כל תועבה\") הוא רק עד שיולד בו מום אחר. ובכמה מפרשים, שלדעת ר\"א מה ש„לא ישחוט עולמית\" הוא רק דרבנן, ומה\"ת אסור רק עד שיולד בו מום אחר (תוס' בכורות שם. ספרי דבי רב לספרי כאן. דברי דוד להט\"ז על פרש\"י כאן (בסופו). ועוד). ואכ\"מ."],["22","22","רע\"ב, ס' זכרון, לבוש האורה, דברי דוד, צידה לדרך ועוד."],["23","23","משפטים כג, יט. תשא לד, כו."],["24","24","משפטים ותשא שם. פרשתנו יד, כא (אלא שברש\"י שם פי' באו\"א. וכבר האריכו במפרשי רש\"י. ואכ\"מ)."],["25","25","חולין שם. *) אבל ראה סהמ\"צ להרמב\"ם וחינוך שבהערה 10 ואכ\"מ"]]],[1300291106,"שנאמר לא תאכל כל תועבה\" — אָבער דאָרט זיינען דאָס צוויי דיעות (איין מ\"ד לערנט עס אָפּ פון „לא תאכל כל תועבה\", און אַ צווייטער מ\"ד26 פון דעם וואָס „לא תבשל גו'\" שטייט ג' פעמים) — ווי אַזוי אָבער נעמט אָן רש\"י ביידע לימודים ודיעות?\nמפרשים27 פאַרענטפערן, אַז דער לאו פון „לא תאכל כל תועבה\" איז ניט מחייב קיין מלקות, ווייל עס איז אַ לאו שבכללות שאין לוקין עליו; דעריבער דאַרף מען האָבן דעם לאו מיוחד פון „לא תבשל\" אויף אכילת בשר בחלב.\nאמנם, דער תירוץ איז מתאים28 בלימוד ע\"ד ההלכה, ס'איז אָבער שווער אַזוי צו פאַרענטפערן כוונת רש\"י בפירושו על התורה29 — מען געפינט ניט אַז רש\"י זאָל ברענגען בפירושו על התורה דעם כלל אַז אין לוקין על לאו שבכללות.\nה. לכאורה וואָלט מען געקענט פאַרענטפערן אַז דאָס איז ע\"ד ווי רש\"י זאָגט בכמה מקומות30 אַז די תורה איז מוסיף אַ לאו כדי „לעבור עליו בשני לאווין\" (וכיו\"ב) — ועד\"ז בנדו\"ד, אַז ביי אכילת בשר בחלב איז מען עובר אויף שני לאווין.\n— עפ\"ז וואָלט מען אויך געקענט מסביר זיין דעם שינוי בלשון רש\"י: אין דער ערשטער דוגמא זאָגט רש\"י „ובא ולמד כאן שלא ישחט ויאכל\", משא\"כ ביי „בשל בשר בחלב\" איז ער משנה און זאָגט „והזהיר כאן על אכילתו\" (ניט — „ולמד כאן שאסור באכילה\" וכיו\"ב),\nווייל ביי „צרם אזן בכור\" ווערט דער איסור אכילה אָפּגעלערנט מכאן („בא ולמד כאן שלא ישחט ויאכל\"); משא\"כ בבשר בחלב וואָס איסור אכילתו ווייס מען שוין פון פריער (פון דעם וואָס עס שטייט ג' פעמים „לא תבשל\"), און דאָ איז דאָס בלויז וואָס עס קומט צו אַן אזהרה — „והזהיר כאן על אכילתו\".\nאָבער דאָס איז ניט קיין תירוץ מספיק, ווייל31:\nא) סוף־סוף איז דאָ רש\"י פאָרט מדגיש „והזהיר כאן על אכילתו\", וואָס פון דעם איז משמע אַז די אזהרה איז „כאן\" — ניט אַז דאָ איז נתוסף געוואָרן נאָך אַן אזהרה.\nב) ועוד ועיקר: די כוונה פון רש\"י בפירושו אויף „לא תאכל כל תועבה\" איז (כנ\"ל סעיף א) צו אַרויסברענגען אַז דער פסוק קומט לערנען אַ חידוש, אַ נייעם דין ואיסור וואָס שטייט ניט במקום אחר — איז ווי פּאַסט צו ברענגען דערויף אַ דוגמא פון אַן איסור אין וועלכן דער פסוק דאָ טוט ניט אויף קיין חידוש דין, נאָר ער איז בלויז מוסיף אַ צווייטן לאו, „לעבור עליו בשני לאווין\"?!",[["26","26","שם קטו, ב. — וראה בהסוגיא שם עוד דיעות ולימודים."],["27","27","רע\"ב ולבוש שם. וכ\"ה ברא\"ם משפטים שם."],["28","28","אבל ראה צידה לדרך כאן מה שהקשה על תי' זה — ממ\"ש החינוך (שם) שלא תאכל כל תועבה אינו לאו שבכללות ולוקין עליו. ע\"ש (וראה גם רמב\"ם הל' פסוהמ\"ק שם). אלא שבמנ\"ח שם — ע\"פ דעת החינוך — שרק על פסולי המוקדשין לוקין, אבל „שאר איסורין (שהם) יוצאין ממנו\" אין לוקין עליהם. ע\"ש. וראה כס\"מ הל' טומאת מת פ\"א ה\"ב. שער המלך הל' יסוה\"ת פ\"ה ה\"ח."],["29","29","נוסף על העיקר, שמפשטות לשון רש\"י „והזהיר כאן על אכילתו\" משמע שעיקר האזהרה היא כאן (ולא בהכתוב דלא תבשל גו')."],["30","30","ראה לדוגמא — פרש\"י: תשא לד, כג („הרבה מצות כו'\"). צו ו, ו. שמיני יא, מד. אמור כג, לא. ועוד."],["31","31","וגם: אם מוקמינן בלאווי יתירי, מנ\"ל ש„לא תבשל\" ג\"פ קאי על איסור אכילת (והנאת) בשר בחלב, ולא (כפשוטו של מקרא) לאסור הבישול בלאווין הרבה?"]]],[1300291107,"ו. וי\"ל דעם ביאור בכל זה:\nרש\"י קומט באַוואָרענען אַ תמי' אין די ווערטער „לא תאכל כל תועבה\" כשלעצמן: וויבאַלד דאָ רעדט זיך וועגן זאַכן וועלכע דער פסוק אַליין איז זיי מתאר אַלס „תועבה\" (ניט אויסטייטשנדיק וועלכע זיי זיינען) — והיינו, אַז ס'איז אַ דבר ידוע (ממקום אחר) אַז זיי זיינען אַן ענין של תועבה32 — איז ניט גלאַטיק וואָס טוט אויף דער פסוק מיט דער אזהרה „לא תאכל כל תועבה\": וויבאַלד אַז זיי זיינען „תועבה\" איז מובן אַז זיי דאַרפן זיין „נתעב\" — מ'טאָר זיי ניט עסן?\nדאַרף מען זאָגן, אַז דער פסוק מיינט אַ סוג מיוחד אין „תועבה\", וואָס לולא דעם ציווי „לא תאכל גו'\" וואָלט מען ניט געוואוסט אַז ער איז אסור באכילה, און דוקא פון דער אזהרה „לא תאכל כל תועבה\" — יעדן אופן פון „תועבה\" — לערנט מען אָפּ אַז אויך אַזאַ „תועבה\" איז אסור באכילה.\nאון דאָס איז וואָס רש\"י איז מחדש גלייך בתחילת פירושו „כל תועבה — כל שתעבתי לך\", וואָס די הדגשה בזה איז דער וואָרט „(תעבתי) לך\": דער תיעוב איז ניט אין דער זאַך — נאָר ביחס צום גברא, „תעבתי לך\".\nוהיינו: דאָ מיינט ניט דער פסוק סתם מאכלות אסורות וועלכע זיינען דברים מתועבים מצד עצמם (און דאָס וואָס זיי זיינען אסור בלויז פאַר אידן און ניט פאַר בני נח, איז ווייל אויך אַ דבר מתועב33 האָט די תורה ניט גע'אסר'ט צו אַ בן נח<sup data-n=\"32\">32</sup>;\nנאָר דאָ טוט אויף דער פסוק אַ נייעם גדר — אַז עס זיינען פאַראַן זאַכן וואָס „תעבתי לך\": דער „תיעוב\" איז בלויז „לך\" — ביחס צו דעם „גברא\", אָבער ניט אַז די זאַך עצמו איז אַ דבר מתועב.\nאויך די זאַכן — כאָטש זיי זיינען ניט קיין דברים מתועבים — איז „לא תאכל\".\n[און דאָס איז דער המשך הכתובים: נאָך דעם ווי תורה זאָגט אָן דעם איסור פון „לא תתגודדו גו'\" מצד דעם וואָס „עם קדוש אתה לה' אלקיך ובך בחר ה' להיות לו לעם סגולה מכל העמים אשר על פני האדמה\"34, איז די תורה ממשיך „לא תאכל כל תועבה\" — „כל שתעבתי לך\", אַז די תועבה איז נאָר מצד מעלת ישראל, אַלס „עם קדוש . . לה' אלקיך גו'\"].\nז. אויף דעם ברענגט רש\"י די ערשטע דוגמא — „כגון צרם אוזן בכור\" — און זאָגט ניט סתם „מטיל מום בקדשים\" —\nווייל דוקא ביי בכור איז מודגש ווי מצד דעם „דבר\" גופא איז ניטאָ קיין תיעוב35 (און דער תיעוב איז בלויז מצד הגברא):\nביי אַלע קדשים, וואָס אַ מום פסל'ט די בהמה למזבח, בלייבט אָבער די בהמה קדשים ביז מ'איז זי פודה. די מציאות פון פסולי המוקדשים (קודם הפדיון) איז אַ דבר האסור („מתועב\") מצד דער חפצא (דוקא דורך פדיון ווערט עס מותר באכילה).\nמשא\"כ אַ בכור בעל מום, וויבאַלד ער איז מותר באכילה (אָן פדי'), קומט אויס,",[["32","32","ראה גם ספורנו עה\"פ."],["33","33","להעיר משבת (פו, ב. וש\"נ) דאכלין שקצים ורמשים חביל גופייהו. וראה שם קמה, ב."],["34","34","פרשתנו יד, א-ב."],["35","35","וראה גם לעיל סעיף ב מ\"ש המפרשים בטעם פלוגתת ר\"א ואחרים."]]],[1300291108,"אַז אין זיין מציאות איז ניטאָ קיין דבר מתועב. דער חסרון („תיעוב\") דאָ איז בלויז מצד דעם גברא, וועלכער האָט (דורך הטלת המום) מפקיע געווען פון דעם בכור די קדושה צו זיין ראוי למזבח36 (אָבער אויך דערנאָך איז דער בכור בעל מום ניט קיין דבר מתועב).\nאון בלויז מצד דעם, וואָס הטלת מום בבכור איז „דבר שתעבתי לך\" — ווערט עס אסור באכילה36*.\nאון דערמיט וועט מען אויך פאַרשטיין פאַרוואָס רש\"י:\nא) נוצט דוקא די דוגמא פון „צרם אוזן בכור\" — און ניט אַן אַנדער מום — ווייל דערמיט איז רש\"י מדגיש אַז דאָ האָט זיך ניט געשאַפן (דורך הטלת המום) קיין דבר מתועב אין דעם בכור, אפילו ניט במובן גשמי כפשוטו. וואָרום צרימת האוזן איז ניט קיין מום וואָס איז פוגע באיזה אופן שהוא אין דער בהמה ופעולותי', ואדרבה: דער ענין פון צרימת האוזן איז אַ דבר הנהוג ורגיל אפילו בבני אדם37.\nב) רש\"י איז מוסיף „כדי לשוחטו במדינה\" — דערמיט איז רש\"י שולל נאָכמער, אַז אפילו דער צער וואָס די בהמה האָט פון צרימת האוזן קען ניט גערעכנט ווערן אַלס אַ דבר בלתי רצוי, וויבאַלד ער טוט עס „כדי לשוחטו\": אויב אַז צוליב אכילת אדם רעכנט מען זיך ניט מיטן צער הבהמה שבשחיטתה, איז עאכו\"כ אַז ס'האָט ניט קיין אָרט צו רעכענען זיך מיטן צער הכי מועט פון צרימת האוזן, אויב אַז דורכדעם וועט די בהמה קענען גענוצט ווערן לאכילת אדם.\nח. עפ\"ז וועט אויך רעכט ווערן סיום לשון רש\"י „ובא ולמד כאן שלא ישחט ויאכל על אותו המום\":\nוויבאַלד אַז אין דער בהמה איז ניטאָ קיין „תיעוב\" — ס'איז נאָר וואָס „תעבתי לך\", תורה האָט גע'אסר'ט דעם גברא צו טאָן דאָס און דערפאַר איז „לא תאכל\" — איז דער איסור „לא תאכל\" (ע\"ד הפשט) נאָר אויף דעם גברא וואָס האָט עובר געווען אויף דעם „תעבתי לך\". משא\"כ באַ אַנדערע, וואָס ביי זיי איז ניט געווען די פעולה האסורה — און די זאַך אַליין איז דאָך ניט קיין דבר מתועב — איז ניטאָ קיין איסור אכילה.\nאון דאָס איז רש\"י מדייק:\nא) „ובא ולמד כאן שלא ישחט ויאכל\" — ניט אַז דער בכור איז געוואָרן אסור באכילה, נאָר עס איז בלויז אַן איסור אויף דעם אדם וואָס „צרם אזן בכור כדי לשוחטו\", אַז „(הוא) לא ישחט (ווי ער האָט געוואָלט) ויאכל\".\nב) „על אותו המום\" — וואָרום דער בכור איז ניט געוואָרן אסור באכילה און ס'איז ניט קיין דבר מתועב, עס איז נאָר וואָס אויף דעם אדם שצרם אוזן הבכור איז דאָ אַן איסור לשוחטו, מצד זיין פעולה האסורה — כדי עס זאָל נתקיים ווערן מחשבתו „צרם אוזן כו' כדי לשחטו\" (וואָס נאָר מצד דעם איז עס „תעבתי לך\") — איז במילא פאַרשטאַנדיק, אַז אויב נולד בו מום אחר, און פון דער בהמה איז סיי ווי נפקע געוואָרן קדושת הבכור (למזבח), איז ניטאָ קיין אָרט פאַרן איסור מצד „כל שתעבתי לך\", וויבאַלד אַז אפילו לולא",[["36","36","ע\"ד מ\"ש בגו\"א כאן. 36*) ולהעיר מבית אפרים יו\"ד (סי' עה בסופו), ששיטת התוס' (הנ\"ל הערה 12) שצורם אוזן בכור אינו בבל תאכל כל תועבה, הוא לפי שי\"ל ד„כל שתעבתי לך\" הוא רק כאשר „המעשה עצמו הוא מתועב מצד המעשה ולא מצד העושה\". ע\"ש."],["37","37","כמפורש גם בפשש\"מ (תשא לב, ב-ג). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111100\" data-slug=\"likkutei-sichot\" data-id=\"1300111100\">לקו\"ש חי\"א ע' 92</a>."]]],[1300291109,"פעולתו האסורה איז די בהמה ראוי' לאכילה.\nט. ע\"פ כל זה איז פאַרענטפערט בפשטות די צווייטע דוגמא פון רש\"י — „בשל בשר בחלב כו'\":\nרש\"י איז מדייק בלשונו „בשל בשר בחלב כו'\" — ניט ווי לשון הגמרא „מנין לבשר בחלב שאסור באכילה\" — ווייל לויט שיטת רש\"י (בפירושו על התורה, פשוטו של מקרא) איז דער גאַנצער איסור פון „לא תאכל כל תועבה\" נאָר אַן ענין בשייכות צו דעם גברא וועלכער האָט עובר געווען און געטאָן אַ פעולה האסורה (אפילו ווען אין דער זאַך איז ניטאָ קיין ענין של תיעוב).\nועד\"ז בעניננו: דער איסור פון אכילת בשר בחלב וואָס ווערט אָפּגעלערנט פון „לא תאכל כל תועבה\" איז ניט פאַרבונדן מיטן גוף המאכל, נאָר מיט דעם גברא וואָס האָט עובר געווען און מבשל געווען דעם בשר בחלב, אַז צוליב זיין פעולה האסורה אין דעם מאכל איז פאַר אים נאסר געוואָרן דער מאכל מיט אַן איסור נוסף באכילתו („לא תאכל כל תועבה\"<sup data-n=\"38\">38</sup>.\nמשא\"כ אַנדערע אידן, וואָס האָבן ניט עובר געווען אויף דעם איסור פון „בשל בשר בחלב\", זיינען ניט אסור אין דעם מצד „לא תאכל כל תועבה\", נאָר בלויז מצד דעם וואָס ג' פעמים נכתב בתורה „לא תבשל גו'\".\nאון דאָס איז רש\"י מדייק „בשל בשר בחלב . . והזהיר כאן על אכילתו\" — פון דעם פסוק לערנט מען אָפּ אַן אזהרה מיוחדת („והזהיר כאן\") צו דעם וואָס „בשל בשר בחלב\", וויבאַלד אַז ער האָט געטאָן אַ „דבר שתעבתי לך\".\nוואָס דאָס ברענגט אַרויס (כנ\"ל) נאָכמער די מעלה פון אידן, ווי זיי זיינען „עם קדוש . . לה'\" און אין זיי „בחר ה' להיות לו לעם סגולה מכל העמים אשר על פני האדמה\".\n(משיחת ש\"פ ראה תשד\"מ)",[["38","38","ע\"פ המבואר בפנים יומתק סדר הדוגמאות בפרש\"י (ובכלל — למה נקט רש\"י שתי דוגמאות, ובפרט שהם מב' מקומות, ספרי וגמ') — כי בתחילה מפרש עיקר חידוש הקרא, כשכל האיסור הוא רק מצד הגברא (כצרם אזן בכור), ואח\"כ מוסיף, שמזה למדים ג\"כ, דגם כשהדבר נאסר מצד החפצא (כבשר בחלב), באם יש גם איסור גברא (איסור בישול) נתוסף עי\"ז עוד איסור על גברא זה."]]],[1300291110,"<h3>שופטים</h3>\nא. אויפן פסוק „שופטים ושוטרים (תתן לך)“ שטייט אין מדרש רבה:1 „א“ר לוי, למה“ד, למלך שהיו לו בנים הרבה והי' אוהב את הקטן יותר מכולן והי' לו פרדס אחד והי' אוהבו יותר מכל מה שהי' לו, אמר המלך נותן אני את הפרדס הזה שאני אוהבו מכל מה שיש לי לבני הקטן שאני אוהבו מכל בני, כך אמר הקב“ה, מכל האומות שבראתי איני אוהב אלא לישראל שנאמר2 כי נער ישראל ואוהבהו, מכל מה שבראתי איני אוהב אלא את הדין שנאמר3 כי אני ה' אוהב משפט, אמר הקב“ה, נותן אני מה שאהבתי לעם שאני אוהב, הוי שופטים ושוטרים“.\nאיז ניט מובן:\nא) דער צוועק פון אַ משל איז דאָך צו מוסיף זיין ביאור אין נמשל — וואָס גיט צו בנדו“ד דער משל („למלך שהיו לו בנים הרבה כו' והי' לו פרדס אחד כו'“) אויפן נמשל?\nובכלל — דאָס וואָס מען גיט אַ דבר חביב ביותר צו דעם וואָס איז אהוב ביותר — איז אַן ענין פשוט וואָס פאָדערט ניט קיין משל!\nב) לרוב הפשיטות — איז ניט מובן דער „דומה למלך“ — באַ יעדער מענשן איז דאָך דאָס אַזוי?\nג) ווי איז מתאים צו זאָגן אַז „מכל מה שבראתי איני אוהב אלא את הדין“? „דין“ איז טאַקע אַן ענין הכרחי צוליב קיום העולם4, און דעריבער איז דער אויבערשטער ניט מוותר אויף אַ הנהגה וואָס איז בסתירה צו „דין“5; אָבער ווי פּאַסט צו זאָגן6 „מכל מה שבראתי איני אוהב אלא את הדין“7?\nד) פון דעם וואָס דער מדרש גיט אַ משל פון „הי' אוהב את הקטן יותר מכולן“ איז מובן, אַז די חביבות פון אידן („עם שאני אוהב“), צוליב וועלכער דער אויבערשטער גיט זיי דעם ענין פון „משפט“, איז בדוגמא צו דער חביבות פון אַ בן קטן דוקא. ומהאי טעמא ברענגט ער (אין נמשל) דוקא דעם פסוק „כי נער ישראל ואוהבהו“ (און ניט פריערדיקע פסוקים ובחומש: „מאהבת ה' אתכם“8, „כי אהבך ה“א“9, וכיו“ב) — ווייל דאָ (אין דעם ענין פון נתינת משפט ודין) איז נוגע דוקא די חביבות מצד דעם וואָס אידן זיינען „נער (ישראל)“, בן קטן דוקא.",[["1","1","פ“ה, ז."],["2","2","הושע יא, א."],["3","3","ישעי' סא, ח."],["4","4","אבות ספ“א (הובא ביל“ש ריש פרשתנו): על ג' דברים העולם קיים כו'. וראה הנסמן בהערה 7."],["5","5","ראה בארוכה טור ריש חו“מ. וש“נ."],["6","6","ועוד: איך מתאים הביטוי „אהבה“ בנוגע לדין ומשפט (ע“ד השאלה בד“ה שופטים ושוטרים תרל“ג (קה“ת, תשט“ז) בנוגע ללשון „שמחה“ שנאמר בשייכות למשפט, ד„מהו השמחה כו'“)."],["7","7","ראה טור שם בתחלתו (מפי רבינו יונה). וראה פרישה שם בארוכה ד„אין שייך לומר שבשביל דין אמת ושלום נברא העולם שהרי אינם אלא ביטול ושמירה מקלקול כו' אבל* אין להם** ית' בעצם אותם ג' שום כבוד או נחת רוח“. ע“ש."],["8","8","ואתחנן ז, ח."],["9","9","תצא כג, ו. *) כ“ה בדפוס ראשון (פפא“מ תע“ב). ולפנינו אבל אם (לכאו' ט“ס) אין. **) כ“ה גם בדפוס ראשון. וצע“ק."]]],[1300291111,"ולכאורה, איפכא מסתברא: דער ענין פון „משפט“ — שופטים ושוטרים תתן לך — איז פאַרבונדן מיט גדלות בכלל, ובפרט גדלות אין שכל, ובלשון הרמב“ם10 „אין מעמידין בסנהדרין . . אלא אנשים חכמים ונבונים11 מופלגין בחכמת התורה בעלי דעה11 מרובה . . שנאמר12 והתיצבו שם עמך בדומין לך (למשה) בחכמה כו'“.\nב. ויש לומר הביאור בכל זה:\nבפשטות קומט אויס, אַז די שייכות דוקא פון „משפט“ (דין) צו אידן, איז ניט אין אַזאַ גרויסער מאָס ווי די שייכות פון אַנדערע עניני תומ“צ צו אידן. ווייל אע“פ וואָס „מגיד13 דבריו ליעקב. חוקיו ומשפטיו — אלו הדינין14 — לישראל (דוקא)“, דאָך, זיינען אויך „או“ה15 נצטוו על הדינין שהיא אחת משבע מצות שנצטוו בני נח“, און דאָס וואָס דער פסוק זאָגט16 „ומשפטים בל ידעום“, באַציט זיך דאָס נאָר14 אויף „דקדוקי הדין“.\nאון דאָס קומט ר' לוי זאָגן, אַז דער ענין איז דוקא פאַרקערט: „משפט“ האָט גאָר אַ ספּעציעלע חביבות ביים אויבערשטן, נאָך מער ווי „כל מה שבראתי“, און דערפאַר איז עס שייך דוקא צו דעם „עם שאני אוהב“. אשר ע“כ קומט אויס, אַז די שייכות פון „משפט“ צו אידן איז מער ווי אַנדערע עניני תומ“צ.\nעס איז דאָך אָבער ניט מובן טעם הדבר — פאַרוואָס אַזאַ חביבות מיוחדת צו „משפט“ ביז אַז דערפאַר האָט „משפט“ מער שייכות צו אידן ווי אַנדערע עניני תומ“צ? — ס'איז דאָך לכאורה פאַרקערט, כנ“ל.\nאויף דעם איז ר' לוי מקדים דעם משל פון „מלך שהיו לו בנים הרבה כו' והי' לו פרדס אחד כו'“, וואָס דער משל פון „פרדס“ איז בדיוק ובהדגשה: דער חילוק צווישן פרדס און שדה איז, וואָס אין אַ פרדס וואַקסן פירות, פרי העץ, „שאינם מוכרחים לצורך קיום החיות“17, און „אינן אלא להתענג בהן“18 — און בשדה וואַקסט (בעיקר) תבואה, וואָס איז אַ מזון הכרחי „לצורך קיום חיותן“17.\nדערמיט מאַכט ר' לוי קלאָר, אַז דאָ רעדט זיך ניט וועגן „משפט“ סתם. משפט בכלל איז אַן ענין הכרחי פאַר קיום העולם (כנ“ל), נאָר המדובר איז וועגן אַ סוג מיוחד אין משפט, וועלכער איז בדוגמא צו פרדס, וועלכער ברענגט „תענוג“19 (און דערפאַר איז דער פסוק מדגיש „אני ה' אוהב משפט“ — ווייל אַ זאַך וואָס שאַפט תענוג איז פאַרבונדן מיט דעם רגש האהבה והחביבות).\nאון דער סוג מיוחד פון משפט איז: א) געגעבן געוואָרן צו אידן דוקא, און ב) דאָס איז פאַרבונדן דערמיט וואָס די חביבות פון אידן ביים אויבערשטן איז בדוגמא צו דער אהבה צו אַ בן קטן דוקא — „נער ישראל ואוהבהו“, כדלקמן.",[["10","10","הל' סנהדרין רפ“ב."],["11","11","חב“ד — ועד“ז בכ“מ ברמב“ם (ראה הנסמן בלקו“ש חכ“ג ע' 86 הערה 49)."],["12","12","בהעלותך יא, טז."],["13","13","תהלים קמז, יט."],["14","14","תנחומא פרשתנו א."],["15","15","ל' התנחומא שם. וראה סנהדרין נו, סע“א ואילך. ולהעיר מהשקו“ט אם ב“נ מצווים לדון בפרטי הדינים כמשפטי התורה (ראה אנציקלופדי' תלמודית ערך ב“נ (ע' שנה). וש“נ)."],["16","16","תהלים שם, כ."],["17","17","ב“י לטאו“ח סר“ז. וראה שו“ע אדה“ז שם."],["18","18","טור שם. וראה ב“י ושו“ע אדה“ז שם."],["19","19","ראה גם נתיבות עולם (להמהר“ל) נתיב הדין בתחלתו: ולכך נקרא המשפט פרדס שהוא טיול ושמחה (אבל שם, שזהו „בעבור שהוא דבר מחוייב ומוכרח“. ע“ש. ולהעיר אשר במלך מוכרח גם ענין התענוג — ע“ד מלך ביפיו גו')."]]],[1300291112,"ג. די הסברה בזה:\nאין כללות ענין המשפט זיינען פאַראַן צוויי פרטים, ובלשון הכתוב — שופטים ושוטרים: „שופטים — דיינין הפוסקים את הדין, ושוטרים — הרודין את העם אחר מצותם . . עד שיקבל עליו את דין השופט“20.\nלכאורה דאַרף אויסקומען, אַז שופטים זיינען בלויז אַן „אמצעי“ וואָס דערמעגלעכט אַז די משפטי התורה זאָלן ווערן קלאָר און באַוואוסט און קענען דורכגעפירט ווערן אין לעבן: אַזוי ווי עס קען ווערן אַ ספק וואָס איז דער משפט התורה, דאַרף מען האָבן „שופטים“ — דיינים וועלכע זיינען מברר דעם פסק דין פון תורה; און אויך „שוטרים“, וואָס ענינם איז דורכצופירן דעם פסק דין ומשפט בפועל „עד שיקבל עליו את דין השופט“.\nוואָס לויט דעם קומט אויס, אַז שוטרים זיינען (אין אַ פרט<sup data-n=\"21\">21</sup> מער עיקר ווי שופטים, ווייל זיי טוען אויף (דעם עיקר ותכלית —) „שיקבל עליו את הדין“.\nאָבער ווי דער ענין פון „שופטים“ איז מבואר בתורה, זיינען זיי ניט נאָר כדי מגלה ומודיע זיין לכל העם אַ קלאָרע הוראה, די דיני ומשפטי התורה, נאָר זיי האָבן (אויך) אַ תוכן און אַ תפקיד פאַר זיך.\nאון ווי דער רמב“ם22 איז מתאר דעם מהות פון ב“ד הגדול שבירושלים — וואָס איז געווען דער עיקר ויסוד פון אַלע שופטים, ש„בכל שעריך“23 — אַז „הם עיקר תורה שבעל פה והם עמודי ההוראה ומהם חק ומשפט יוצא לכל ישראל“.\nדער רמב“ם זאָגט דאָ דריי פרטים (ושלבים)24 בנוגע דעם תפקיד פון ב“ד הגדול: א) „הם עיקר תורה שבעל פה“ — דאָס איז ניט דער ענין פון „עמודי ההוראה“, נאָר דער עיקר פון תורה שבעל פה (ד.ה. ניט נאָר תורה אַלס הוראה, נאָר אויך — לימוד והבנת התורה)25. ב) „והם עמודי ההוראה“ — דער ענין פון בירור הלכה למעשה שבתורה, הוראה לפועל. ג) „ומהם חק ומשפט יוצא לכל ישראל“ — דער תפקיד אַז די הוראות הב“ד זאָלן אַרויסקומען (און אָנקומען) לכל ישראל26.",[["20","20","ל' רש“י ריש פרשתנו. וראה תנחומא פרשתנו ב. רמב“ם ריש הל' סנהדרין. וראה לקו“ש חל“ד ע' 98 ואילך."],["21","21","אף ששופטים חשובים יותר משוטרים, כי השוטר הוא רק שליח השופט (ראה רא“ם וגו“א ריש פרשתנו) — מ“מ בנוגע להעיקר והתכלית (קיום הדין בפועל), הוא יותר בשוטרים מבשופטים (ראה תנחומא שם)."],["22","22","ריש הל' ממרים."],["23","23","ראה פרשתנו יז, ח (ובפרש“י ד“ה דברי ריבות). ולהעיר גם מספרי עה“פ בכל שעריך — להקיש כו'. רמב“ם הל' סנהדרין פ“א ה“ג: קובעין בתחלה כו'. שם ה“ח. ועוד."],["24","24","ע“פ מ“ש הרמב“ם בהלכה שלאח“ז, דמה שלמדו „מפי השמועה“ הוא „תורה שבעל פה“; „מפי דעתם באחת מן המדות כו'“ נק' „משפט“; ו„על פי התורה אשר יורוך“ קאי על „התקנות והגזירות והמנהגות שיורו כו'“ — יש לומר לכאורה, שזהי ג“כ כוונת הרמב“ם כאן בג' לשונות אלו: „עיקר תורה שבע“פ“ — מה שלמדו מפי השמועה (קבלה איש מפי איש); „עמודי ההוראה“ — תקנות גזירות ומנהגות; „חוק ומשפט יוצא כו'“ — מה שלמדו באחת מן המדות כו'. אבל משינוי לשון הרמב“ם — „עיקר תורה שבעל פה . . עמודי ההוראה . . חוק ומשפט יוצא לכל ישראל“ (שבודאי אינם סתם מליצות) משמע שכוונתו (עכ“פ — גם) להמבואר בפנים."],["25","25","ראה הקדמת הרמב“ם לס' היד בתחלתה: כל המצות . . בפירושן ניתנו . . והמצוה זו פירושה . . ומצוה זו היא הנקראת תורה שבעל פה. וראה צפע“נ שם."],["26","26","להעיר מהחילוק בין לאסוקי שמעתתא"]]],[1300291113,"ד. און דאָס איז דער חילוק צווישן דעם ענין פון „שופטים“ ווי דאָס איז ביי אידן, און — ווי דאָס איז באַ בני נח „להושיב דיינין ושופטים בכל פלך ופלך“27 — אַ חילוק עיקרי אין עצם מהותם:\nביי ב“נ, איז דער תפקיד פון די שופטים ודיינים בלויז כדי „לדון בשש מצות אלו ולהזהיר את העם“27: די דינים זיינען צו זיי געגעבן געוואָרן פאַרטיקערהייט, בשלימותם28; נאָר וויבאַלד ניט יעדער איינער קען אַליין (בשכלו) מכווין זיין צום דין לאמיתו, האָט די צייט דערצו א.ז.וו. מוז מען האָבן דיינים ושופטים וועלכע לערנען די דינים און זיינען מודיע דעם דין המתאים צו דער פּאַסירונג (און אויך — זיך משתדל זיין, אַז די דינים זאָלן ווערן דורכגעפירט בפועל — „להזהיר את העם“).\nמשא“כ ביי בני ישראל איז דער ענין פון שופטים צום אַלעם ערשטן — „עיקר תורה שבעל פה“.\nצו זיי איז איבערגעגעבן געוואָרן תורה שבכתב אַז זיי זאָלען זי לערנען און מפרש ומבאר זיין — תורה שבעל פה: זיי האָבן בכח ניט בלויז צו קלאָר מאַכן ומפרט זיין אַ דין בתורה, נאָר ס'איז בכחם (כמובן, לויט כללי התורה) צו מחדש זיין אין תורה29; און אין דעם אַלעם איז „לא תסור מן הדבר אשר יגידו לך ימין ושמאל“30.\nאון דאָס מיינט דער מדרש „מכל מה שבראתי איני אוהב אלא את הדין“ און אַז דער אויבערשטער האָט אָפּגעגעבן משפט ודין צו אידן: דאָ רעדט זיך ניט וועגן דעם תפקיד פון דורכפירן דין ומשפט אין אַלגעמיין (וואָס איז פאַראַן אויך ביי בני נח), נאָר וועגן דעם חידוש ענין פון „משפט“ — דער שכל וחכמה31 פון תורה שבע“פ, וואָס דער ענין אין משפט איז ניט צוליב לדעת את המעשה אשר יעשו, צוליב וועלט — ס'איז העכער (ובמילא מער אהוב למעלה) „מכל מה שבראתי“32, און דאָס איז אָפּגעגעבן געוואָרן צו אידן, כנ“ל.\nה. עפ“ז וועט מען אויך פאַרשטיין דעם טעם וואָס דאָס איז פאַרבונדן מיט",[["","","אליבא דהלכתא, ופס“ד בנוגע לפועל — ראה ב“ב (קל, ב) אין למדין הלכה לא מפי למוד כו' עד שיאמרו לו הלכה למעשה (ראה רשב“ם שם. לקו“ש חי“ד ע' 50). רמב“ם הל' ממרים פ“ג ה“ו. וראה בארוכה המשך תרס“ו (ע' שצ ואילך. ע' תו ואילך)."],["27","27","לשון הרמב“ם הל' מלכים ספ“ט — מסנהדרין שם, ב."],["28","28","להעיר מרמב“ם הל' מלכים (פ“י ה“ט): אין מניחין אותן לחדש דת כו' יעמוד בתורתו לא יוסיף ולא יגרע."],["29","29","ראה בארוכה המשך תרס“ו שם (ע' שפג ואילך. ע' תד ואילך)."],["30","30","פרשתנו יז, יא. וראה ספרי ופרש“י שם: אפילו אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין. וראה לקו“ש ח“ה ע' 127 (ובהנסמן בהערה 26 שם). ולהעיר גם מנתיבות עולם (להמהר“ל) נתיב התורה פי“א: החכמים הם עצם התורה. ע“ש. ואכ“מ."],["31","31","ראה פרדס (הובא באוה“ת ריש פרשתנו. סד“ה שופטים ושוטרים תער“ב (בהמשך תער“ב ח“א)) דהספירות כולם נקראו שופטים מצד הבינה."],["32","32","ע“פ המבואר בפנים יומתק השינוי בלשון המדרש בין המשל להנמשל — בהמשל אומר „שהיו לו בנים הרבה והי' אוהב את הקטן יותר מכולן והי' לו פרדס כו' אוהבו יותר מכל מה שהי' לו“, ואילו בנמשל אומר „איני אוהב אלא לישראל . . איני אוהב אלא את הדין“, כי בהנמשל, ענין ה„פרדס“ שבמשפט ה“ה שלא בערך* לשאר עניני הבריאה (ולא רק שהוא יותר אהוב מהם). וכן (בנמשל) זה שישראל הם „נער . . ואוהבהו“ (כדלקמן סעיף ה) אינו בערך לשאר כל האומות. *) להעיר ממעשה מרכבה ומעשה בראשית ש„קוראין אותו פרדס“ ודוקא בו (ולא בשדה) שייך טיול (רמב“ם הל' יסודי התורה פ“ד הי“ג), שבתורה ה“ה סודות התורה כו'."]]],[1300291114,"דער חביבות פון אידן אַלס „נער ישראל“ דוקא33:\nאין דעם ענין פון בירור ההלכות שבתורה איז נוגע בעיקר34 דער ענין פון גדלות בשכל וחכמה, כנ“ל, אָבער דאָס וואָס דער אויבערשטער „גיט אָפּ“ תורה, כביכול, צו די (שופטים פון) אידן, באופן אַז זיי זיינען „עיקר תורה שבעל פה“ — דאָס איז ניט מצד זייער מעלה בשכל וחכמה, נאָר דערפאַר וואָס ישראל וקוב“ה כולא חד35, אידן זיינען, כביכול, איין זאַך מיטן אויבערשטן, מיט נותן התורה.\nאון אויף דעם איז אַ משל די חביבות פון אַ בן קטן דוקא. די אהבת האב צו אַ בן קטן איז ניט פאַרבונדן מיט מעלות הבן (ובפרט — גלויות) (וואָרום ער איז דאָך נאָך אַ קטן), נאָר דערפאַר וואָס זיי (האב והבן) זיינען אַן עצם אחד36.\nועד“ז בנמשל בנוגע צו אידן: עס איז פאַראַן די חביבות צו אידן מצד דעם וואָס זיי זיינען אַן „עם חכם ונבון“37; אָבער די אהבה עצמית פון דעם אויבערשטן צו אידן איז מצד זייער עצם (ניט פאַרדעקט מיט זיינע מעלות וכיו“ב) — זיי זיינען „נער ישראל“.\nובעבודה — דאָס שטייט בגילוי ביי אידן בשעת זיי האַלטן זיך קליין38, בביטול — „ממעטין עצמכם“39 — וואָס מצד דעם ווערן אידן „בעה“ב“ כביכול אויף תורה.\nאון דערפאַר איז די שייכות פון משפט צו אידן טיפער און שטאַרקער ווי אַנדערע עניני תומ“צ, ווייל אין התהוות, חידוש המשפט דריקט זיך אויס די „מעלה עצמית“ פון אידן, וואָס זיי זיינען איין מהות כביכול מיטן אויבערשטן, אלקי ומלך40 המשפט.\nדערמיט איז אויך מובן וואָס מען ברענגט אַ משל פון אַ מלך דוקא — ווייל אין נמשל, באַקומען די אידן (ניט סתם אַ זאַך וואָס איז חביב, נאָר) אַ זאַך וואָס איז ביכולת נאָר פון אַ מלך צו געבן — די „בעלות“ אויף משפט, וואָס קומט (כנ“ל) פון אלקי ומלך המשפט.\nו. דער ענין הנ“ל בנוגע צו „משפט“ — זייענדיק אַן ענין כללי פון כל (ובכל) התומ“צ — איז פאַראַן מענינו ביי דעם קיום פון יעדער מצוה, על ידי כל אחד ואחת. והביאור:\nדער חילוק צווישן „שופטים“ און „שוטרים“ איז בדומה צום חילוק צווישן „נעשה“ און „נשמע“: „שופטים“ איז ענינם — „נשמע“ — דער פאַרשטאַנד41 פון און מאַכן הערן תורה",[["33","33","בהבא לקמן — להעיר (באו“א קצת) מאוה“ת פרשתנו ע' תתיט ואילך. סד“ה שופטים תער“ב הנ“ל."],["34","34","אף שצ“ל גם ענין הביטול, ואדרבה — הטעם שקבעו הלכה כב“ה ולא כב“ש (אף שב“ש „מחדדי טפי“ — יבמות יד, א), הוא „מפני שנוחין כו' ולא עוד אלא שמקדימין דברי ב“ש לדבריהם“ (עירובין יג, ב) — ראה בארוכה סה“מ תרכ“ז (ע' רעז ואילך. ע' רצ ואילך). המשך תרס“ו ע' תכב ואילך. לקו“ש חכ“א ע' 115. ועוד."],["35","35","להעיר גם מלקו“ש חי“ט ע' 386-7. וראה שם הערה 54."],["36","36","ראה ד“ה כי נער ישראל תרס“ו (ע' תקנג. ובהוצאת תנש“א — ע' תקעז). וראה לקו“ש חכ“א ע' 20 ואילך (וש“נ). וראה שם הערה 6."],["37","37","ואתחנן ד, ו."],["38","38","ראה גם לקו“ש שם ע' 21."],["39","39","חולין פט, א. וראה גם פי' מהרז“ו למד“ר שם."],["40","40","ומלך מחדש משפטים (רמב“ם הל' מלכים ספ“ג. שם פ“ד) ועיין מהר“ץ חיות בס' תורת נביאים פ“ז (דין מלך ישראל). ואכ“מ."],["41","41","מל' דבר גו' כי שומע (ש“א ג, ט) וכיו“ב."]]],[1300291115,"ומצוות; און „שוטרים“ טוען אויף דעם „נעשה“ — די עשי' בפועל, כולל אויך מעשה מלשון כפי'42 (בדוגמת השוטרים), וואָס בכללות איז דאָס דער ענין פון קבלת עול.\nקען מען מיינען אַז „נשמע“ איז ניט קיין ענין ותכלית פאַר זיך, עס איז נאָר מעין הכשר מצוה והכנה, וואָס פירט צו עשיית מצות — האָט מען אויף דעם די הוראה פון דעם מדרש הנ“ל, אַז דער אויבערשטער הייסט עס זאָל זיין „נשמע“ (שופטים) אַלס אַן עבודה לעצמה.\nוואָס דאָס איז אויך איינער פון די ביאורים אין דעם וואָס דער סדר איז „נעשה ונשמע“ (נעשה קודם לנשמע) — דאָס איז ניט נאָר צוליב'ן „נעשה“, אַז די תנועה פון קבלת עול זאָל זיין בתקפה ובשלימותה, אָן אַן אַריינמישונג פון טעמים שכליים מצד „נשמע“, נאָר דאָס איז אויך צוליב'ן „נשמע“:\nווען דער „נשמע“ קומט פאַר „נעשה“, קען זיין אַז דער „נשמע“ איז בלויז אַ הכנה והכשרה צום „נעשה“ — „לימוד מביא לידי מעשה“;\nבשעת אָבער דער „נשמע“ קומט נאָכן „נעשה“, נאָך דעם וואָס די עשי' איז שוין „אָפּגעטאָן“ געוואָרן — איז מובן אַז דער „נשמע“ איז (ניט צוליב'ן „נעשה“, נאָר) אַן עבודה (ושלימות) ותכלית פאַר זיך.\nוהטעם בזה — ווייל די שלימות החביבות והתענוג דלמעלה איז ווען ביי אידן איז פאַראַן אויך די הבנה והשגה אין עניני תומ“צ. וואָרום נתאוה הקב“ה להיות לו דירה בתחתונים, אַז אַלע „תחתונים“ זאָלן ווערן אַ „דירה“ וכלי צו ג-טלעכקייט. בשעת ביי אַ אידן טוט זיך אויף בלויז דער „נעשה“ — עשי', קבלת עול — איז אע“פ אַז אין דעם דריקט זיך אויס זיין ביטול צום רצון העליון, איז דאָס אָבער ניט אַן ענין וואָס דרינגט דורך זיין מציאות בכל פרטי', אויך די כחות פנימיים:\nכדי עס זאָל זיך דורכפירן די כוונה פון „דירה בתחתונים“43 איז ניט גענוג וואָס אַ איד איז זיך מבטל צום רצון העליון, נאָר ער כולו ובכל פרטיו מוז ווערן אַ „כלי“ („דירה“) צו קדושה, וואָס דאָס איז דוקא ווען עס איז (אויך) דאָ (כוחותיו הפנימיים) „נשמע“, הבנה והשגה44.\nז. ע“ד ווי ס'איז פאַראַן אַ מעלה אין לימוד (והבנת<sup data-n=\"45\">45</sup> התורה („נשמע“) לגבי קיום המצות — עד“ז זיינען דאָ די צוויי ענינים אין קיום כל מצוה גופא:\nכידוע46, זיינען אין מצוות פאַראַן צוויי סוגי כוונות: א) די כוונה כללית וואָס איז שווה בכל המצוות (חלק דנוסח הברכה השווה בכל המצוות) — „אשר",[["42","42","ב“י לטויו“ד סרמ“ח. וראה לקו“ת בחוקותי מח, א. ולהעיר מאגה“ק סי“ב (קיח, א-ב) בההפרש בין „מעשה“ ו„עבודה“. וצע“ק."],["43","43","ועאכו“כ מש“כ בזח“ב (מב, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">תניא ספמ</a>“ד) „בגין דישתמודעון לי'“, ובע“ח (ש' הכללים בתחלתו) „ויכירו גדולתו“."],["44","44","ראה אוה“ת פרשתנו שם: דירה בתחתונים . . י' עקב . . שנמשך האור והשפע ע“י צמצום התורה ומצות וזהו תכלית רצונו ית'. ובהמשך תער“ב שם (ע' קג): וענין מ“ש שאוהב את המשפט י“ל שזהו מה שיש מעלה בפנימי על המקיף . . שהמשפט הוא בע“ס. וראה גם לקו“ש שם ע' 22 ואילך."],["45","45","להעיר שבתושבע“פ צ“ל הלימוד דוקא בהבנה (שו“ע אדה“ז חאו“ח ס“נ ס“ב (ממג“א סוס“נ). הל' ת“ת ספ“ב)."],["46","46","ראה לקו“ת שלח מ, א. עטרת ראש נח, סע“ב ואילך. ובכ“מ."]]],[1300291116,"קדשנו במצותיו וציונו“, קיום רצון העליון, קבלת עול מצות: ב) די כוונה פרטית וואָס איז פאַרבונדן מיטן תוכן פרטי וסגולה מיוחדת וואָס איז דאָ אין דער מצוה — „להניח תפלין“ [וכמו: רמ“ח מ“ע כנגד רמ“ח איברים47 ושס“ה מל“ת כנגד שס“ה גידים — און יעדע מצוה טוט אויף אַ זיכוך אין איר אבר און טייל פון מענטשן48], וואָס דאָס איז אַן ענין של טעם ודעת.\nדער חילוק צווישן די צוויי כוונות איז פאַרבונדן מיט די צוויי ענינים אין מצוות49: א) דער רצון העליון ב“ה שבמצות — וואָס אין רצון איז ניטאָ קיין התחלקות, און מצד דעם זיינען אַלע מצוות גלייך. ב) עונג העליון ב“ה (די פנימיות פון דעם רצון העליון שבמצוות) — וואָס דער „עונג העליון“ איז אַנדערש בכל מצוה.\n[ע“ד50 ווי דער חילוק צווישן רצון ועונג שבנפש האדם, אַז אין רצון איז ניטאָ קיין התחלקות, דער (תוקף ה)רצון איז גלייך אין אַלע רצונות בשוה; משא“כ אין תענוג איז דאָ התחלקות, אין יעדן כח איז פאַראַן אַן אַנדער מין תענוג].\nאון דערפאַר איז פאַראַן אַן עילוי אין דער כוונה פרטית פון מצות לגבי דער כוונה כללית50 — ווייל אין דעם איז פאַראַן דער עונג העליון ב“ה (ע“ד הנ“ל, אַז דער „נתאוה הקב“ה“ איז דוקא צו האָבן אַ דירה בתחתונים, וואָס ווערט אויפגעטאָן דורך דער המשכה (אויך) בפנימיות<sup data-n=\"51\">51</sup>.\nח. אע“פ אַז ביי יעדער מצוה איז פאַראַן דער עילוי פון „משפט“ (מצד הכוונה ותוכן פרטי שבמצוה זו) — קומט עס אָבער ניט צו דעם עילוי וואָס איז דאָ אין „משפט“ כפשוטו.\nוואָרום52 דער עונג אלקי וואָס איז מלובש אין מצות (אין יעדער מצוה אַן אַנדער סוג עונג) — איז נאָר אַ הארה פון דעם עונג העליון ב“ה, וואָס איז מיוחד במהותו ועצמותו ית'; און דער אויבערשטער אַליין איז דאָך פשוט בתכלית הפשיטות, און ס'איז ניט שייך ביי אים קיין התחלקות כו', נאָר ער איז דער „מקור התענוגים“, וואָס פון דאָרט ווערט נמשך אַ „הארה במצות לכל בחי' כמדריגתה“.\nאון דאָס איז דער אויפטו פון „משפט“ — „שופטים ושוטרים תתן לך“ — וואָס דערמיט ווערט געמיינט (ניט דער ענין פרטי פון משפט, נאָר) ענין הכללי בשייכות צו גאַנץ תומ“צ (כנ“ל ס“ד בארוכה). און דערפאַר זאָגט מען דערויף „אני ה' אוהב משפט“ — ווייל אין דעם שטייט בגלוי (ניט נאָר אַ הארה פון דעם עונג העליון, ווי אין יעדער מצוה פרטית, נאָר) דער מקור התענוגים, דער „נתאוה“ פון עצמותו ית'.\nאון דאָס איז אויך דער טעם וואָס דער ענין פון משפט ווערט געגעבן צו אידן מצד דעם וואָס „נער ישראל ואוהבהו“ — דוקא צוליב זייער (מעלה פון) קטנות",[["47","47","שכל אבר ואבר אומר לו עשה בי מצוה (הובא בסוף הקדמת סהמ“צ להרמב“ם, והוא בתנחומא תצא ב, בשינוי ל' קצת)."],["48","48","ראה בארוכה לקו“ש חי“ז ע' 412 ואילך. וש“נ."],["49","49","עיין לקו“ת במדבר יח, א-ב. אוה“ת ר“ה (כרך ה) ע' ב'ק' ואילך. וראה לקמן ע' 179 ואילך."],["50","50","ראה ד“ה אדון עולם תשמ“ג (סה“מ — מלוקט ח“א ע' תלב ואילך) התיווך להמבואר ברוב הדרושים (ראה הנסמן בהערה 46. ועוד) — שהכוונה כללית היא למעלה מהכוונה פרטית."],["51","51","ראה לקו“ש שם ע' 413 ואילך."],["52","52","ראה בארוכה בכ“ז — אוה“ת ר“ה שם."]]],[1300291117,"וביטול — ווייל דער פאַרבונד מיט מקור התענוגים איז53 ניט דורך אַן עבודה פון טעם והרגש העונג, וואו ס'איז נרגש מציאות האדם, נאָר אדרבה: דוקא דורך פשיטות פאַרבינדט מען זיך מיט דער פשיטות שלמעלה54.\nט. פ' שופטים לייענט מען אַלע מאָל בתחילת חודש אלול\n— ברוב השנים איז שבת פ' ראה נאָך אין חודש מנ“א — ש“מ אלול; און אַפילו ווען עס פאַלט אויס בר“ח אלול, איז עס דער ערשטער טאָג ר“ח (ל' מנ“א), אָבער א' אלול איז אַלעמאָל בפ' שופטים —\nאיז מובן, אַז דער ענין הנ“ל בנוגע צו שופטים האָט אַ שייכות מיוחדת צו חודש אלול, וואָס פון די מנהגי ישראל בחודש זה (וועלכע הויבט זיך אָן פון א' אלול<sup data-n=\"55\">55</sup> איז תקיעת שופר דאלול56:\nבנוגע דעם ענין פון שופר געפינט מען צוויי קצוות57: „שופר“ איז מלשון „שפרו מעשיכם“58, וואָס איז דער ענין פון תענוג; ולאידך, דער קול השופר איז מטיל אימה וחרדה59 (היפך העונג).\nאיז דער צ“צ דערויף מבאר60, אַז „שופר“ איז די בחינה פון „מקור התענוגים“ וואָס איז אינגאַנצן העכער פון גילוי התענוג, און דערפאַר איז ער מטיל אימה וחרדה, ווייל דער גילוי פון מקור התענוגים, איז פאַרבונדן מיט ביטול ופשיטות כנ“ל.\n[וכידוע61 דער משל פון בעש“ט אויף קול שופר, אַז דאָס איז בדוגמת דעם קול פשוט62 פון בנו יחידו של המלך, וואָס „אביו יכירו בטביעת עין דקלא“].\nאָבער מאידך, איז „שופר“ מלשון תענוג, היות אַז דאָס איז דער מקור",[["53","53","ראה לקו“ת שם (יח, ג) „והיינו ע“י אני אותיות אין“ (וראה בהנסמן שם). וראה אוה“ת שם פ“ד — הובא לקמן בפנים."],["54","54","ע“ד מאמר הבעש“ט (כתר שם טוב בהוספות סקנ“ד (ואילך). וש“נ) דפשיטות העצמות מתגלה בהפשיטות דאיש פשוט."],["55","55","ראה הדיעות בזה בנ“כ הטושו“ע או“ח סתקפ“א. ואנו אין לנו אלא הוראת נשיאנו כ“ק מו“ח אדמו“ר (היום יום אדר“ח אלול) שביום השני דר“ח אלול מתחילין לתקוע, וביום הראשון תוקעין (רק*) להתלמד."],["56","56","וכ“ה בנוגע ההוספה בתהלים (ג“פ ליום). משא“כ אמירת לדוד ה' אורי גו' — שמתחיל בא' דר“ח אלול. אבל להעיר, שב' ענינים אלו נמשכים גם בחודש תשרי, משא“כ שופר דאלול (ואף שישנו בר“ה — ה“ה סוג אחר לגמרי בתקיעות*. ואכ“מ)."],["57","57","ראה בכ“ז — אוה“ת שם פ“ב ופ“ד. ולהעיר מאוה“ת (יהל אור) תהלים ע' רצב."],["58","58","ל' המדרש — ויק“ר פכ“ט, ו. מדרש תהלים פא, ד."],["59","59","כמש“נ (עמוס ג, ו) אם יתקע שופר בעיר ועם לא יחרדו — הובא בטאו“ח (ונ“כ) שם בנוגע לאלול."],["60","60","באוה“ת שם."],["61","61","הובא בהמשך וככה תרל“ז פרק ע."],["62","62","בהמשל שם אומר „קול גדול“, אבל בנמשל אומר „קול פשוט“*. וראה בארוכה סידור ד“ה להבין ענין תק“ש ע“פ כוונות הבעש“ט (רמד, ג ואילך) דענין של תק“ש הוא קול פשוט המעורר הפשיטות דלמעלה. *) אלא שבפנימיות הענינים, זה שתוקעין להתלמד באדר“ח אלול הוא התחלה של ענין השופר — ראה בארוכה לקו“ש חל“ד ע' 95. ואילך. *) אף שי“ל ששייכים זל“ז — ראה לקו“ש ח“ט ע' 129 ואילך. שם ע' 317 בהערה. *) ומסתבר שגם בהמשל הכוונה לקול פשוט, שהרי „מחמת אריכות הזמן שכח גם לשון מדינתו“, והמלך מכירו (רק) ע“י קולו."]]],[1300291118,"התענוגים פון וועלכן עס ווערן נמשך כל מיני תענוג.\nוואָס דאָס איז ע“ד וואָס דער מדרש איז מבאר בנוגע צו משפט — שופטים ושוטרים תתן לך — אַז אין דעם איז פאַראַן דער „אני ה' אוהב משפט“, און דערפאַר איז עס פאַרבונדן מיט אידן ווי זיי זיינען אין דעם אופן פון „נער ישראל ואוהבהו“, כנ“ל.\nוע“י ענין ה„משפט“ (שלימות פון דין בכלל) ווערט אויפגעטאָן (ווי דער מדרש איז מסיים), אַז „מיד אני גואל אתכם גאולה שלימה“63.\n(ממאמר ושיחת ש“פ שופטים תשכ“ז. ד“ה יו“ט של ר“ה תשמ“ב*)",[["63","63","ראה סד“ה שופטים תער“ב בביאור סיום דברי המדרש (דבזכות המשפט „אני . . משרה קדושתי ביניכם . . מיד אני גואל אתכם גאולה שלימה“) — כי ע“י המשפט ממשיכים עצמות אוא“ס. ע“ש. וראה לעיל סעיף ח. *) נדפס כולו בסה“מ מלוקט ח“א ע' תכא ואילך."]]],[1300291119,"<h3>שופטים ב</h3>\nא. נאָכדעם ווי דער רמב\"ם רעכנט אויס בפרטיות אַלע מצות (אין דער הקדמה פון ספרו יד החזקה), איז ער ממשיך: אלה הם תרי\"ג מצות שנאמרו לו למשה בסיני הן וכללותיהן ופרטותיהן כו' ויש מצות אחרות שנתחדשו אחר מ\"ת וקבעו אותם נביאים וחכמים ופשטו בכל ישראל כגון מקרא מגילה ונר חנוכה ותענית תשעה באב ועירובין וידים כו' כל אלו המצות שנתחדשו חייבים אנו לקבלם ולשמרם שנאמר1 לא תסור מן הדבר וכו'.\nוצריך ביאור: אַלץ וואָס דער רמב\"ם שרייבט איז בתכלית הדיוק, און ווען ער ברענגט בחיבורו כמה ענינים איז ער זיי מסכם2 ומפרט — ווי מ'געפינט עס לכל לראש בנוגע כללות חבורו: ער איז זיך ניט מסתפק מיט דעם וואָס ער איז מקדים3 „וראיתי לחלק חיבור זה הלכות הלכות בכל ענין וענין ואחלק ההלכות לפרקים שבאותו ענין וכל פרק ופרק אחלק אותו להלכות קטנות כדי שיהיו סדורים על פה\", נאָר ער איז זיי מונה וסופר (נאָכן אויסרעכענען די מצות) „וראיתי לחלק חיבור זה לארבעה עשר ספרים\", און איז מבאר דעם תוכן פון יעדן ספר ושמו און וויפל הלכות יעדער ספר אַנטהאַלט (ווי בספר המדע: הלכותיו חמש וזה סדורן הלכות . . תשובה)4.\nועד\"ז בנוגע למנין המצות: כשם ווי ער איז מדייק צו געבן דעם מספר כללי פון אַלע מצות של תורה (ווי בסוף ההקדמה — לפני מנין המצות) „ומנין מצות התורה הנוהגות לדורות שש מאות ושלש עשרה מצות מהם מצות עשה מאתים וארבעים ושמנה סימן להם כו' ומהם מצות ל\"ת שלש מאות וששים וחמש כו'\" און ער איז עס חוזר וכופל בכמה מקומות — אַזוי רעכנט ער אויס5 בראש כל „הלכה\" דעם מספר כללי פון די מצות און אויך דעם מספר פרטי דעשה ול\"ת וואָס די הלכה אנהאַלט אין זיך. ולדוגמא — הלכות יסודי התורה: „יש בכללן עשר מצות שש מצות עשה וארבע מצות ל\"ת (און איז ממשיך) וזהו פרטן כו'\"; און ער איז חוזר ומסכם בסיום פון יעדן פון די י\"ד ספרים — דעם מספר כללי ופרטי פון די מצות שבו (ולדוגמא בסו\"ס המדע: „נמצאו כל המצות הנכללות בספר זה חמש ושבעים שש עשרה מהם מצות עשה ותשע וחמשים מצות לא תעשה\").\nועפכ\"ז פאָדערט זיך ביאור — פאַרוואָס שרייבט דאָ ניט דער רמב\"ם (און מען געפינט אויך ניט אַז דער רמב\"ם זאָל ערגעץ אין ספרו היד אָנגעבן) דעם",[["1","1","פרשתנו יז, יא. וצע\"ק שלא הזכיר הרמב\"ם כאן גם העשה שבזה — אף שהביאו והדגישו בכ\"מ. ראה לקמן בפנים ס\"ג."],["2","2","ראה יד מלאכי כללי הרמב\"ם אות לד."],["3","3","בסוף הקדמתו לספר היד — לפני מנין המצות. ועד\"ז בהקדמתו לספר המצות."],["4","4","ועד\"ז כתב בסוף הקדמתו (אחרי שמפרט כל הי\"ד ספרים והמצות שבהם): ונמצאו כל ההלכות של ארבעה עשר ספרים אלו שמונים ושלש הלכות. אבל מ\"ש בסוף כמה ספרים — מספר כל הפרקים שבכל הלכה וסכום הכולל שבכל הספר — צ\"ע אם הוא מהרמב\"ם (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271245\" data-slug=\"likkutei-sichot\" data-id=\"1300271245\">לקו\"ש חכ\"ז ע' 231-2</a> בשוה\"ג להערה 26)."],["5","5","ולהעיר דכפי הנראה מכמה כת\"י ודפוסים וכן מצילום כי\"ק דהרמב\"ם (נדפס ברמב\"ם הוצאת שולזינגער בסופו) חזר וכתב כל ההלכות שבכל ספר — בריש כל ספר; וכל מנין המצות על סדר ההלכות — בריש כל הלכה והלכה."]]],[1300291120,"מספר פון די מצות וועלכע זיינען מדברי סופרים6?\nב. אין ספר המצות7 זאָגט דער רמב\"ם (ווען ער פרעגט אויפן דעת הבה\"ג וועלכער רעכנט געוויסע מצות דרבנן אין מנין המצות): „אם נמנה כל עשה דרבנן וכל לא תעשה דרבנן יהי' זה עולה לאלפים רבים\".\nמ'קען אָבער ניט זאָגן אַז מטעם זה זאָגט ניט דער רמב\"ם דעם מספר פון מצות דרבנן, ווייל:\nא) אדרבה, וויבאַלד דער מספר איז אַזוי גרויס, איז דאָך נאָכמער נויטיק צו זאָגן זייער מספר, וואָרום דאָס העלפט זיי אַלע צו וויסן און געדענקען8 (נאָכמער: ע\"פ דברי הרמב\"ם9 לגבי די תרי\"ג מצות, דעם טעם וואָס ער איז זיי מפרט ומונה בכל הלכה והלכה — כדי „להשמר שלא יעדר ממנו דבר שלא אדבר בו ובזכרי כל המצות במספר הייתי בטוח מזה\" — איז שייך און נויטיג אויך (און נאָכמער) לגבי מצות דרבנן).\nב) ועיקר: די שאלה פאַרוואָס ער ציילט זיי ניט איז וועגן די מצות דרבנן בכללותן, ע\"ד ווי דער רמב\"ם רעכנט זיי דאָ — „כגון מקרא מגילה ונר חנוכה ותענית תשעה באב ועירובין וידים\", און ניט בנוגע זייערע פרטים. ועוד ועיקר — די שאלה איז בנוגע אַ באַזונדער סוג אין ד\"ס גופא: די מצות וואָס זיי האָבן מחדש ומתקן געווען — ניט די גזירות וסייגים וואָס זיי האָבן צוגעגעבן און אַריינגעגעבן אין די מצות דאורייתא, אָדער מנהגות וכיו\"ב10;\nאון דער סוג פון מצות מד\"ס איז דאָך במספר מוגבל ומועט. ובכ\"מ11 ווערן גערעכנט ז' מצות דרבנן — ותו לא12.\nג. לכאורה קען מען דאָס מבאר זיין ע\"פ דברי הרמב\"ם עצמו:\nדער רמב\"ם זאָגט אַז „כל מה שצוונו חכמים לעשותו וכל מה שהזהירונו ממנו כבר צוה . . לעשותו והוא אמרו1 על פי התורה אשר יורוך וגו' והזהירנו יתברך מעבור דבר מכל מה שתקנו אותו או גזרו, ואמר1 לא תסור\"13, און ווי ער איז מאריך בזה בריש הלכות ממרים.",[["6","6","ע\"ד שמנאום בכמה ספרים — ראה לקמן הערה 12, 46."],["7","7","שורש א בסופו."],["8","8","ראה יד מלאכי שם. ובאגרת תחה\"מ להרמב\"ם קרוב לתחלתו: וכללנו במספר ואמרנו שהם עשרים וארבעה מיראתנו שמא יחסר אחד מן המעתיקים מן המספר אחד ויאמר האומר שלא זכרנו אותו."],["9","9","בהקדמתו לספר המצות."],["10","10","ראה רמב\"ם ריש הל' ממרים."],["11","11","של\"ה שטו, סע\"א בשם „קדמונים\". כתר תורה (לר\"ד ויטאל) הובא בתורת העולה להרמ\"א ח\"ג פל\"ח. וראה בפרטיות בהנסמן בסה\"מ תש\"ח ע' 165. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211410\" data-slug=\"likkutei-sichot\" data-id=\"1300211410\">לקו\"ש חכ\"א ע' 401</a> ואילך. אמנם הכלל המבואר שם (מספר „מצות השם\") דאין נכנסין במנין אלא אלו שתקנו חז\"ל לברך עליהם ושאין להם עיקר מן התורה (ושהן בקום ועשה) — לא יתכן לומר על כל אלו שהרמב\"ם מונה כאן, כי „תענית ת\"ב\" אין מברכין עליו ואינו בקום ועשה. ולהעיר דבהל' ברכות (פי\"א ה\"ג — דלקמן בפנים ס\"ג) הזכיר בהמצות שהן מד\"ס, גם הדלקת נר בשבת. ואכ\"מ."],["12","12","ובסמ\"ג (ח\"ב) בסוף רמזי מ\"ע כתב: אחרי כן בארנו חמש מצות מד\"ס והם כו'. ולהעיר ממ\"ש בסוף חלק המ\"ע „אחרי שסיימנו מ\"ע של תורה נחל לבאר מ\"ע שהם מד\"ס . . והם חמש מצות*\" — אף שלדעתו ישנם עוד, וכמו שממשיך שם „וכבר בארנו מצות נטילת ידים שהיא מד\"ס\". וידוע שבכלל — הסמ\"ג הלך בעקבות הרמב\"ם (יד מלאכי כללי הרמב\"ם כו' הסמ\"ג אות מו)."],["13","13","לשון הרמב\"ם בסהמ\"צ שורש א. וראה גם *) וראה לקמן שם שבריש כל מצוה (אחרי מצוה הא') מציין מספרה: המצוה השנית; המצוה השלישית כו'."]]],[1300291121,"דער רמב\"ן14 איז משיג אויף די דברי הרמב\"ם און פרעגט כו\"כ קשיות, וביניהן: אויב אויף יעדער מצוה שמד\"ס איז דאָ אַ לאו און עשה האָט מען געדאַרפט מחמיר זיין אין אַלע ענינים מדרבנן וויבאַלד אַז זיי זיינען חיובים מן התורה — פאַרוואָס געפינט מען כמה חילוקים בהלכה צווישן אַ מצוה דאורייתא און אַ מצוה מד\"ס?\nאיינער פון די תירוצים שבזה אין מפרשים15: בשעת מ'איז ניט מקיים אַ מצוה דרבנן אָדער מ'איז עובר אויף אַן איסור מד\"ס איז מען (לדעת הרמב\"ם) ניט עובר אויף דער מצוה פון „על פי התורה אשר יורוך\" אָדער אויפן לאו „לא תסור\", נאָר בלויז דאַן ווען מען איז ניט מקבל די מצוה אָדער דעם איסור דרבנן, ווען ער איז ניט מודה אין דברי חכמים.\nדאָס הייסט: די מצוה „על פי התורה אשר יורוך\" און דער לאו פון „לא תסור\" איז ניט דעם עצם טאָן אָדער ניט־טאָן דאָס וואָס די חכמים האָבן מתקן געווען, נאָר16 די מצוה איז „לשמוע מכל בית דין הגדול שיעמדו להם לישראל\"17 — אַ חיוב צו פאָלגן די חכמים.\nאון ווי דער רמב\"ם18 איז מסביר דעם נוסח הברכה „אשר קדשנו במצותיו וצונו\" באַ מצות דרבנן: „והיכן צונו בתורה, שכתוב בה1 אשר יאמרו לך תעשה, נמצא ענין הדברים והצען כך הוא אשר קדשנו במצותיו שציוה בהן לשמוע מאלו שצונו להדליק נר של חנוכה או לקרות את המגילה וכן שאר כל המצות שמדברי סופרים\".\nקומט אויס19, אַז די מצות דרבנן זיינען ניט איינגעטיילט אין באַזונדערע מצות, נאָר אַלע מצות זיינען (נכלל אין) איין מצוה — „לשמוע כו'\" און „לא תסור\".\nנאָכמער זאָגן מפרשים20, אַז כשם ווי איסורי דרבנן זיינען (לכמה דיעות20*) ניט איסורי חפצא, נאָר איסורי גברא21, עד\"ז איז עס אויך ביי די מצות מדרבנן, אַז זיי זיינען ניט אין דער חפצא, נאָר זיי זיינען אַ חיוב אויפן גברא.\nועפ\"ז יש לומר, אַז דערפאַר זאָגט ניט דער רמב\"ם אַ מספר מצות דרבנן, ז' מצות וכיו\"ב, כדי מדגיש זיין דאָס גופא, אַז מצות דרבנן זיינען ניט אויסגעטיילט יעדערע בפ\"ע אַלס אַ באַזונדער מצוה, ס'איז ניט חל אַ באַזונדער שם „מצוה\"22 אויף יעדער מצוה מדברי",[["","","לשונו בהקדמת היד — הובא בתחילת השיחה. סהמ\"צ ומנין המצות שבריש ס' היד — מ\"ע קעד ומל\"ת שיב."],["14","14","בהשגותיו לשרשים שם. וראה גם חינוך מצוה תצו."],["15","15","ראה בהבא לקמן אנציקלופדי' תלמודית ערך דברי סופרים ס\"ד. וש\"נ. שד\"ח כללים מערכת אל\"ף סי' שצט, מערכת למ\"ד כלל וא\"ו. וש\"נ. ובכ\"מ."],["16","16","ראה גם צפע\"נ על הרמב\"ם כאן. ובמכתבי תורה מכתב רכה בתחלתו."],["17","17","ל' הרמב\"ם במנין המצות שבריש ס' היד מ\"ע קעד. ובהמצות שבריש הל' ממרים כתב „לעשות על פי התורה שאמרו לנו ב\"ד הגדול\". ובסהמ\"צ כתב (וכ\"ה בחינוך מצוה תצה) ב' הענינים: לשמוע . . ולעשות. ואכ\"מ."],["18","18","הל' ברכות פי\"א ה\"ג. וראה שם פ\"ו ה\"ב."],["19","19","ראה צפע\"נ שבהערה 16. וביאר עפ\"ז הא ד„ירושלמי סוכה פ\"ג על הך דסוכה דף מ\"ו (ע\"א) על מצות זקנים ר\"ל דנוסח הברכה כך הוא דלא כרש\"י\" (סוכה שם ד\"ה מכאן ואילך)."],["20","20","ראה אתוון דאורייתא כלל יו\"ד. 20*) ראה השקו\"ט באתוון דאורייתא שם. בית האוצר מערכת א' כלל קכב. ובכ\"מ."],["21","21","וצע\"ג איך ליישב עפ\"ז מש\"כ ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310013\" data-slug=\"tanya\" data-id=\"3401310013\">תניא רפ\"ח</a> „ואפילו הוא איסור דרבנן\". ועד\"ז בכ\"מ. — וראה שיחות אחש\"פ (ושלאח\"ז) תשל\"ז. ועוד."],["22","22","ראה דברי המג\"א לסהמ\"צ שם בתחלתו."]]],[1300291122,"סופרים, היות אַז די אַלע מצות זיינען נכלל אין איין מצוה — פאָלגן די רבנן און „לא תסור\" מדבריהם.\nוע\"ד ווי דאָס איז, להבדיל, ביים אויספאָלגן (שזהו ציווי השו\"ע) הוראות הרופא, וואָס מ'איז זיי מחוייב מקיים זיין מצד דעם ציווי „ונשמרתם מאד לנפשותיכם\"23 — טיילט מען ניט פאַנאַנדער יעדער מעשה ופעולה וזהירות אַלס אַ באַזונדער (קיום) מצוה\nויתרה מזו — ע\"ד קיום הפרטים פון מצות כיבוד אב ואם24. וכיו\"ב.\nד. מען קען אָבער אַזוי ניט פאַרענטפערן, וואָרום\n[נוסף על זה אַז עס לייגט זיך ניט צו זאָגן אַז דער רמב\"ם זאָל משנה זיין פון דרכו וסדרו בכל הספר כולו (וואָס ער איז סופר ומונה די פרטי הדברים והענינים, און זאָגט אויך זייער סך־הכל), בלויז בכדי צו מרמז זיין ענין הנ\"ל (ובפרט אַז דאָס איז אַן ענין עקרי וואָס ער האָט עס געדאַרפט זאָגן בפירוש25 באיזה מקום בספרו) — איז]\nא) די עצם הנחה, אַז ביי די מצות ואיסורים דרבנן איז (לדעת הרמב\"ם) די מצוה ניט די מעשה נאָר די שמיעת דברי חכמים, איז צע\"ג — וכדמוכח אויך פון דעם וואָס ניט אַלע לערנען אַזוי בדעת הרמב\"ם26 —\nדאָס איז כלל ניט בדומה צו הוראות הרופא הנ\"ל, וואָס סוף־סוף זיינען זיי כשלעצמן ניט קיין דברי תורה27, משא\"כ די תקנות ומצות דרבנן זיינען (בכללות כל אחת מהן) אַ טייל פון הלכות ודברי תורה: און וויבאַלד אַז זיי זיינען אַ חלק (ועיקר<sup data-n=\"28\">28</sup> פון תורה שבע\"פ, איז מובן אַז אויך קיומן (ווי קיום מצות מקרא מגילה, עד\"מ) איז אויך ע\"פ תורה (מדאורייתא) אַ מעשה של מצוה29, ניט בלויז אַ קיום פון דעם ציווי (הכללי) לשמוע דברי חכמים.\nב) עכ\"פ קען מען ניט זאָגן אַז דאָס איז כוונת הרמב\"ם דאָ מדגיש זיין אָט דעם ענין אין מצות דרבנן, וואָרום דער רמב\"ם איז דאָך ווייטער ממשיך און באַוואָרנט ווי די מצות „אינם תוספת על מצות התורה\"\n[וז\"ל: אם הוסיפו ב\"ד כו' דרך תקנה או דרך הוראה כו' אין זו תוספת שהרי לא אמרו שהקב\"ה צוה לעשות עירוב או לקרות מגילה כו' ואילו אמרו כן היו מוסיפין על התורה אלא כך אנו אומרים שהנביאים עם ב\"ד תקנום וצוו לקרות המגילה בעונתה כדי כו'30],\nואת\"ל תירוץ הנ\"ל איז דאָך דאָס מלכתחילה קיין קשיא ניט: דער רמב\"ם",[["23","23","ואתחנן ד, טו."],["24","24","ראה קנאת סופרים לסהמ\"צ שם שורש א (ט, ב) במה שהשיב על א' מהשגות הרמב\"ן."],["25","25","אף שבכלל אין דרכו להביא חידושים בספרו (יד מלאכי כללי הרמב\"ם אות ה'), אבל נדו\"ז ה\"ז הסברה עיקרית."],["26","26","ראה אנציקלופדי' תלמודית שם."],["27","27","ומשתנים מזמן לזמן ואפילו ממקום למקום."],["28","28","ראה לשון הרמב\"ם ריש הל' ממרים."],["29","29","ראה דרשות הר\"ן דרוש ז. וכן בדרוש ה נוסחא ב (הובא גם באוה\"ת שה\"ש כרך ג ע' תסג. רד\"ה מאי מברך בסה\"מ פר\"ת: ה'ש\"ת). וכ\"ה לפי הבנת הרמב\"ן בדברי הרמב\"ם."],["30","30","ובהל' ממרים (פ\"ב ה\"ט) מתרץ בנוגע לגזירות ב\"ד — ראה ראב\"ד ונ\"כ הרמב\"ם שם, וכאן מתרץ ומבאר בנוגע לתקנות, היינו (בעיקר) מצות עשה מד\"ס. ולהעיר מסיום לשונו כאן „ועד\"ז היא כל מצוה ומצוה שהיא מדברי סופרים בין עשה בין לא תעשה\". כן להעיר דשם מדייק „שלא להוסיף על דברי תורה ולא לגרוע מהן . . בין בתורה שבכתב בין בתורה שבע\"פ\", ואילו כאן מדייק „ואינם תוספת על מצות התורה\"; „לא להוסיפה למצות התורה\". ואכ\"מ. וראה לקמן הערה 33."]]],[1300291123,"גופא איז דאָך מדגיש (דערמיט וואָס ער זאָגט ניט קיין מספר פון מצות דרבנן) אַז מצות דרבנן זיינען ניט צוטיילט אַלס באַזונדערע מצות, נאָר זיי אַלע זיינען איין כללית'דיקע מצוה דאורייתא, פאָלגן די רבנן און לא תסור מדבריהם, איז דאָך מובן בפשטות אַז עס איז ניטאָ קיין קס\"ד אַז ס'איז צוגעקומען עי\"ז אַ הוספה אין מספר המצות31, און ער דאַרף ניט פאַרענטפערן ווי „אינם תוספת על מצות התורה\" און ס'איז ניט קיין סתירה צו „לא32 תוסף עליו\"33.\nוע\"כ צ\"ל, אַז דערפון גופא וואָס דער רמב\"ם דאַרף דאָ גלייך באַוואָרענען אַז „אינם תוספת על מצות התורה\", איז מוכח אַז, אדרבה: תוכן דבריו דאָ וועגן מצות דרבנן איז אַז זיי זיינען (ניט אַ קיום פון איין מצות התורה — שמיעת דברי חכמים, נאָר פאַרקערט) נאָך מצות (בדומה צו מצות התורה), וואָס יעדער מצוה איז מען מחוייב מקיים זיין — חיוב ע\"פ תורה.\nוכדמוכח אויך פון דיוק לשונו „אלה הם תרי\"ג מצות . . ויש מצות אחרות שנתחדשו אחר מ\"ת . . ויש לכל מצוה ומצוה מאלו פירושין ודקדוקין . . כל אלו המצות שנתחדשו חייבים אנו לקבלם ולשמרם כו'\", ד. ה. זיי זיינען אַנדערע באַזונדערע מצות34 (ניט קיין פרטים הכלולים אין דער מצות התורה לא תסור) וועלכע זיינען אין דעם זעלבן סוג וגדר פון די פריערדיקע תרי\"ג מצות התורה, נאָר זיי זיינען „נתחדשו אחר מ\"ת כו'\". און דעריבער פאָדערט זיך גלייך צו באַוואָרענען, אַז אעפ\"כ „אינם תוספת על מצות התורה\".\nוהדרא קושיא לדוכתא: פאַרוואָס זאָגט ניט דער רמב\"ם דעם מספר פון די „מצות אחרות שנתחדשו\"35?\nה. ויש לומר הביאור בזה:\nאין דעם וואָס דער רמב\"ם איז מדייק וחוזר ומונה דאָ דעם מספר מצות דאורייתא\n[סיי בתחילת דבריו „אלה הם תרי\"ג מצות כו'\", און אַזוי אויך בהמשך דבריו וואו ער איז מסביר (כנ\"ל) ווי מצות דרבנן „אינם תוספת על מצות התורה ועל מה הזהירה תורה לא תוסף עליו",[["31","31","ועיין אגה\"ק סכ\"ט (קנ, סע\"א): והנה ז' מצות דרבנן אינן נחשבות מצות בפני עצמן שהרי כבר נאמר לא תוסף אלא הן יוצאות ונמשכות ממצות התורה וכלולות בהן במספר תרי\"ג."],["32","32","ראה יג, א."],["33","33","להעיר מהשגת הראב\"ד הל' ממרים שם לגבי סייגים וגזירות — וראה רדב\"ז שם. מנ\"ח מצוה תנד בתחלתה (נב, רע\"א). ועיין בהמשך הדברים במנ\"ח שם „כמה מצות שהוסיפו חז\"ל כגון נר חנוכה ונט\"י וכדומה שהם דברים חדשים ולא הוסיפו במצות התורה נראה דודאי לא שייך ב\"ת כי התורה נתנה רשות לחכמים לתקן תקנות הן בקום ועשה כו' ולא ראיתי בדברי הראשונים שיהי' זה נכלל זה ויתרצו הדברים כי הלאו הזה אינו אלא כו'\". וצע\"ג שכנראה נעלם ממנו לפי שעה — דברי הרמב\"ם כאן בסוף מנין המצות!"],["34","34","ועפ\"ז יומתק זה שהרמב\"ם כאן מקדים מקרא מגילה ונר חנוכה ל„עירובין וידים\", אף שעירובין וידים הם מתקנות שלמה וב\"ד (עירובין כא, א. רמב\"ם הל' עירובין פ\"א ה\"ב ואילך. הל' אבות הטומאות פ\"ח ה\"ח) — לפני תיקון מקרא מגילה כו' — כי במגילה וחנוכה מודגש יותר דהוי „מצות בפני עצמן\" — ראה חדא\"ג מהרש\"א מגילה יד, א ד\"ה חוץ."],["35","35","וכמ\"ש ב„מנין המצות על סדר הרמב\"ם\" בסוף ספר זמנים „נמצאו כל המצות של תורה הנכללות בספר זה חמש ושלשים י\"ט מהם . . ויש בו ג' מצות מדברי סופרים\", והיינו הל' עירובין (דכ' שם בתחלת ההלכות „מצות עשה אחת והיא מד\"ס ואינה מן המנין\") והל' מגילה וחנוכה (דכ' בריש ההלכות „יש בכללן ב' מצות עשה מדברי סופרים ואינם מן המנין\")."]]],[1300291124,"ולא תגרע ממנו שלא יהא נביא רשאי לחדש דבר ולומר שהקב\"ה צוהו במצוה זו להוסיפה למצות התורה או לחסר אחת מאלו השש מאות ושלשה עשרה מצות\"],\nאון זאָגט ניט קיין מספר אין די מצות מד\"ס — אין דעם גופא דריקט זיך אויס דער חילוק צווישן מצות של תורה און מצות דרבנן:\nדי מצות דאורייתא זיינען במנין ומספר מסויים וקבוע — מ'איז אָנגעזאָגט געוואָרן „לא תוסף עליו ולא תגרע ממנו\" ובלשון הרמב\"ם36 „דבר ברור ומפורש בתורה שהיא מצוה עומדת לעולם ולעולמי עולמים אין לה לא שינוי ולא גרעון ולא תוספת שנאמר37 את כל הדבר אשר אנכי מצוה אתכם אותו תשמרון לעשות לא תוסף עליו ולא תגרע ממנו\".\nמשא\"כ מצות דרבנן זיינען, כלשון הרמב\"ם „מצות שנתחדשו\", וואָס די רבנן בכח התורה זיינען מחדש „כדי לחזק הדת ולתקן העולם\" (ווי דער רמב\"ם זאָגט אין הלכות ממרים<sup data-n=\"38\">38</sup>.\nד. ה. זיי זיינען — דער היפך פון אַ באַשטימטער צאָל. במילא קען דער רמב\"ם ניט זאָגן קיין מספר אויף די מצות דרבנן, קביעות מספר איז שייך נאָר ביי די מצות דאורייתא, ניט ביי מצות דרבנן.\nו. נאָכמער: וויבאַלד עס ליגט אויף די חכמים אַ חיוב לעשות סייג לתורה (בלשון הרמב\"ם<sup data-n=\"39\">39</sup> „לפי מה שהשעה צריכה\" — קען דאָך זיין אַז עס זאָל קומען אַ „שעה\" ווען עס פאָדערט זיך צו מוסיף זיין נאָך גזירות תקנות ומנהגות, מצות דרבנן — און דעמאָלט ליגט אויף די חכמים אַ חיוב צו מוסיף זיין און אַ חיוב על בנ\"י לקיימן — די הוספות — מצד „לא תסור\" און „לשמוע\".\nאון אע\"פ אַז לפועל קען איצט ניט צוקומען קיין נייע מצות דרבנן, ווייל ס'איז ניטאָ קיין ב\"ד הגדול וואָס האָט דעם כח צו מוסיף זיין תקנות כו' — איז שתי תשובות בדבר:\nערשטנס, דאָס בייט ניט דעם גדר פון מצות דרבנן, וויבאַלד אַז ע\"פ הלכה איז דאָ אַן אפשריות מוסיף זיין אויף די מצות אויב ס'זאָל אויפשטיין אַ ב\"ד הגדול, ובפרט לעת\"ל, ווען „ואשיבה שופטיך כבראשונה\"40 —\nוע\"ד ומעין דעם ביאור הרמב\"ם (אין ספר המצות שלו<sup data-n=\"41\">41</sup> אין דעם טעם פאַרוואָס ער רעכנט צווישן די מצות אויך די מצוה פון השמדת ז' אומות — אע\"פ אַז דאָס איז ניט אַ מצוה וועלכע איז נוהגת לדורות (וואָס אַזעלכע מצות רעכנט ניט דער רמב\"ם במנין המצות) — וז\"ל42: „הענין שנסתיים בהשגת מטרתו בלי שיהא אותו הדבר תלוי בזמן מסויים אין אומרים בו אינו נוהג לדורות, לפי שהוא נוהג בכל דור שבו נמצאת אפשרות אותו הדבר . . כללו של דבר אתה צריך להבין ולהתבונן בהבדל בין המצוה ובין הדבר אשר נצטוה עליו כי יש שתהא נוהגת לדורות אלא שהדבר שנצטוה עליו כבר נעדר בדור מן הדורות כו'\";",[["36","36","הל' יסוה\"ת רפ\"ט (וראה שם בהמשך ההלכה). וראה הל' מעשה הקרבנות ספ\"ב. הל' מלכים פי\"א סה\"ג."],["37","37","פ' ראה שם (ושם: תשמרו)."],["38","38","פ\"א ה\"ב."],["39","39","הל' ממרים שם."],["40","40","ישעי' א, כו."],["41","41","מ\"ע קפז."],["42","42","בהעתק קאפח. ולפנינו — בשינוי לשון."]]],[1300291125,"ועד\"ז בנדו\"ד: אע\"פ אַז בפועל (איצט) איז ניטאָ די מציאות פון אַזאַ ב\"ד וואָס קען מחדש זיין אַ מצוה, איז אָבער דאָ די הלכה ומצוה שבזה, אַ ב\"ד וואָס קען מחדש ומוסיף זיין מצות דרבנן בזה\"ז.\nוהשנית קרוב לומר אַז לדעת הרמב\"ם קענען בפועל נתחדש ווערן תקנות (אין גדר פון מצות דרבנן) אויך ווען ס'איז ניטאָ קיין ב\"ד הגדול, והוא ע\"פ דברי הרמב\"ם בהקדמתו לספר היד: „כל הדברים שבגמרא הבבלי חייבין כל ישראל ללכת בהם וכופין כל עיר ועיר וכל מדינה ומדינה לנהוג בכל המנהגות שנהגו חכמי הגמרא ולגזור גזירותם וללכת בתקנותם (אע\"פ אַז דער „בית דין הגדול של שבעים ואחד בטל מכמה שנים קודם חיבור הגמרא\") הואיל וכל אותם הדברים שבגמרא הסכימו עליהם כל ישראל ואותם החכמים שהתקינו או שגזרו או שהנהיגו או שדנו דין ולמדו שהמשפט כך הוא, הם כל חכמי ישראל או רובם כו'\". ומזה, אַז אַ תקנה ומנהג וואָס „הסכימו עליהם כל ישראל\" האָבן בכל הזמנים דעם תוקף פון אַ מצוה דרבנן.\nובפרט לפי דעת הרמב\"ם, אַז עס קען זיין ווען „הסכימו כל החכמים שבארץ ישראל למנות דיינים ולסמוך אותם\"43, עס זאָל ווערן אַ ב\"ד של דיינים סמוכים44 מיטן תוקף פון ב\"ד הגדול (און דער חיוב „לשמוע מכל ב\"ד הגדול\"17 איז ניט פאַרבונדן כלל מיט דעם וואָס דער ב\"ד געפינט זיך בלשכת הגזית<sup data-n=\"45\">45</sup>.\nז. אע\"פ אַז בכמה ספרים ווערן די מצות דרבנן גערעכנט מיט אַ מספר קבוע — ז' מצות דרבנן46 — און דער מספר ז' איז בדיוק ובדוקא,\nוכידוע אַז די ז' מצות דרבנן ביחד מיט די תרי\"ג מצות דאורייתא איז דער מספר מדוייק תר\"ך, כתר תורה47 [ומהאי טעמא געפינט מען אַז די „עשרת48 הדברות (וואָס) כוללים כל התורה כולה (איז אין זיי דאָ) תר\"ך אותיות, תרי\"ג אותיות בכל אות נרשם49 מצוה אחת מתרי\"ג מצות וז' אותיות היתרות הם50 ז' מצות דרבנן כמ\"ש הקדמונים\"] —",[["43","43","רמב\"ם הל' סנה' פ\"ד הי\"א. וראה פיה\"מ סנה' פ\"א. בכורות פ\"ד מ\"ג."],["44","44","ראה קונטרס הסמיכה למהר\"י בירב (שבשו\"ת מהרלב\"ח). תו\"ש סוף כרך ט\"ז."],["45","45","כ\"מ מלשונו „מכל ב\"ד הגדול\". וכדאי' בירוש' סנה' פי\"א ה\"ג „ובאת לרבות ב\"ד שביבנה\". ועד\"ז בספרי פרשתנו יז, ט (כפי' ר\"ה שם). וראה צפע\"נ לירוש' שם. אבל ברמב\"ן בהשגות לסהמ\"צ מ\"ע קנג, שדין ב\"ד הגדול הוא בלשכת הגזית דוקא (וראה לב שמח שם). וראה בארוכה מרגניתא טבא לסהמ\"צ שרשים שם (אות ה'). מנ\"ח מצוה תצו. ועוד."],["46","46","בכמה דפוסי החינוך (אשר במנין המצות הולך בעקבות הרמב\"ם*), אחרי שמפרט (בתחלת הספר) כל התרי\"ג מצות, כותב**: ואלו ז' מצות דרבנן כו'. אלא שבכמה דפוסים (עם מנ\"ח) ליתא, וכן ליתא בדפוסים הראשונים דהחינוך (ראה בהוצאת שעוועל)."],["47","47","כ\"ה גם ב„חינוך\" שבהערה הקודמת."],["48","48","לשון השל\"ה (וראה גם ספר תורת העולה) שבהערה 11. וראה הערות הבאות."],["49","49","וראה ספר כתר תורה (שבהערה 11) — שמפרט כל התרי\"ג מצות (וז' מצות דרבנן) בכל אות מעשה\"ד."],["50","50","ראה הערה הקודמת. בבעה\"ט יתרו כ, יד (וכן בס' זהר הרקיע (להרשב\"ץ) בהקדמה קרוב לתחלתה ובעוד ספרים) נמצא ג\"כ ענין הנ\"ל — שבעשה\"ד יש תר\"ך אותיות *) ראה חינוך בסוף הקדמתו. שם (בפנים הספר) סוף מצוה תקעג. ועוד. **) הובא גם בספר „מצות השם\" בהקדמתו, וכן בסוף ז' מצות דרבנן שמונה. ושם: כפי שמצאתי בספר החינוך הנדפס אצל החומש (אלא שאינו כפי הסדר שבחינוך שם)."]]],[1300291126,"איז דאָס כלל קיין סתירה ניט להנ\"ל. ווייל אין די ספרים רעדט זיך ווי דאָס איז בפועל (כולל גם לעת\"ל?) וואָס מלמע' איז אויסגעשטעלט אַז עס וועלן בפועל ניט זיין מער ווי שבע מצות דרבנן (דער ב\"ד וועלכער קען מחדש ומוסיף זיין — וועט מצות51 ניט מחדש זיין בפועל<sup data-n=\"52\">52</sup> און צוזאַמען מיט די מצות דאורייתא זיינען זיי תר\"ך מצות — כתר.\nאָבער מצד דעם גדר פון מצות דרבנן ע\"פ הלכה — קענען צוקומען נאָך מצות53 (און (אויך) אויף זיי איז חל דער ציווי „ע\"פ התורה אשר יורוך\" און „לא תסור\").\nבסגנון אחר קצת: דאָס וואָס „כלפי שמיא גליא\" אַז בפועל וועלן זיין נאָר שבע מצות דרבנן, איז ניט משנה כלל דאָס וואָס ע\"פ הלכה קענען צוקומען נאָך מצות דרבנן. ויתרה מזה: וויבאַלד אַז „רשות לכל אדם נתונה\" — טאָן היפך התורה, קען ווערן אַז דער ב\"ד דאַרף ומחוייב מתקן זיין ולהוסיף מצות לצורך השעה און מ'איז מחוייב לקיימן במ\"ע ול\"ת.\nוי\"ל דוגמא וע\"ד ווי דער רמב\"ם איז מבאר54 לגבי דער ידיעה שלמעלה, אַז דאָס וואָס „הקב\"ה יודע כל מה שיהי'\", איז ניט מכריח די בחירת האדם, און „מעשה האדם ביד האדם כו'\"55, „רשות לכל אדם נתונה אם רצה להטות עצמו לצד טובה ולהיות צדיק הרשות בידו\"56; ועד\"ז להיפך. און ווי דער רמב\"ם איז מבאר בארוכה54.\nח. ע\"פ הנ\"ל — אַז דאָס וואָס דער רמב\"ם רעכנט ניט דעם מספר פון די מצות דרבנן איז מצד דעם וואָס ע\"פ הלכה האָבן זיי ניט קיין „מנין\" והגבלה (און דער העדר המדידה והגבלה — איז ע\"פ הלכת תורת אמת) —\nיש לומר, אַז דאָס איז מתאים דערמיט וואָס איז מבואר (אין ספרים פון גדולי ישראל) אַז דער מספר מדויק פון שבע מצות דרבנן איז משלים דעם מספר תר\"ך — כתר.\nע\"ד ווי מ'געפינט בנוגע הלכות שבתורה די צוויי ענינים: הלכות שבתורה ווערן אָנגערופן57 „תגא\", „כתרה של תורה\"; און זיי האָבן ניט קיין מספר, ווי עס שטייט „ועלמות58 אין מספר59 אל תקרי עלמות אלא עולמות אלו הלכות דלית לון חושבנא\"60.\nאון הא בהא תליא: מצד דעם וואָס הלכות שבתורה זיינען פאַרבונדן מיט „כתר\" זיינען זיי בלי מספר. בדוגמא ווי אַ כתר גשמי וואָס איז למעלה מן הראש און איז מקיף דעם ראש וואָס דאָס ווייזט אַז עס איז העכער פון דעם מענטשן —",[["","","ושהוא „כתר תורה\". אלא דשם, שז' אותי' היתירות הן כנגד ז' מצות ב\"נ (וראה זה\"ר שם, דז' מצות ב\"נ מרומזים בהאותיות ד(סוף עשה\"ד) „אשר לרעך\"). וראה בית האוצר (להר\"י ענגל) ח\"א ה, ב ואילך. ואכ\"מ."],["51","51","משא\"כ גזירות וסייגים וכו'."],["52","52","וע\"ד שכל הסנהדראות כולם — לא חידשו אלא שבע מצות!"],["53","53","ואולי גם ע\"ז קאי מש\"נ ועלמות אין מספר, ראה לקמן בפנים."],["54","54","בהל' תשובה ספ\"ה."],["55","55","ל' הרמב\"ם שם."],["56","56","ל' הרמב\"ם שם רפ\"ה."],["57","57","מגילה כח, ב. נתבאר באגה\"ק סכ\"ט (קנ, ב ואילך)."],["58","58","ל' אדה\"ז באגה\"ק שם (קנא, א)."],["59","59","שה\"ש ו, ח."],["60","60","ראה תקו\"ז בהקדמה (יד, ריש ע\"ב). תכ\"א (מג, ב). זח\"ג רטז, סע\"א. ובשהש\"ר שם, ט (ב) — הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381289\" data-slug=\"likkutei-torah\" data-id=\"4001381289\">לקו\"ת שה\"ש מ, ב</a>: ועלמות אין מספר אין קץ לתוספת."]]],[1300291127,"און צוזאַמען דערמיט איז אַ כתר אמתי דאַרף זיין „הולם\" דעם ראש61 עד\"ז איז „כתר עליון\" העכער פון מדידה והגבלה, און צוזאַמען דערמיט איז ער כתר דעשי', דיצירה וכו' — און דערפאַר זיינען הלכות, וואָס זיינען „כתרה של תורה\", אָן אַ חשבון62.\nועד\"ז (בסגנון אחר קצת) בנוגע די מצות מד\"ס63, וועלכע זיינען פאַרבונדן מיט תורה שבע\"פ „מער\" ווי סתם הלכות: הלכות זיינען מבאר ומפרש תושב\"כ64, אָבער מצות מד\"ס זיינען „מצות אחרות שנתחדשו\"65 — זייענדיק פאַרבונדן מיט דער מדריגה פון כתר, זיינען זיי ביידע בלי מנין והגבלה.\nוהגם אַז בנוגע זייער קיום בפועל אין וועלט, און מנינם מצד „וועלט\" שבתורה — איז פאַראַן אַ הגבלה במצות אלו (ז' מצות דרבנן) — ווי זיי שטייען אָבער אין הלכות התורה (ובמילא — בס' הרמב\"ם שהוא — הלכות הלכות) קומט צו אַ חידוש גדול — בלשון הרמב\"ם עצמו כנ\"ל (רס\"ב) — אַז זיי זיינען „עולה\" און „לאלפים רבים\" בפועל66, למעלה ממדידה והגבלה — בערך המספר דשבע67.\nאון דורך דעם לימוד ההלכות בכלל וואָס ווערן אָנגערופן „תגא וכתרה של תורה\", איז — „כל השונה הלכות בכל יום מובטח לו שהוא בן עוה\"ב\"68.\n(משיחות אחש\"פ והתוועדויות שלאח\"ז — תשמ\"ה)",[["61","61","שה\"ז סימנו של מלך בית דוד (ע\"ז מד, סע\"א) מלך בשלימות (ראה רמב\"ם הל' מלכים פ\"א ה\"ז ואילך)."],["62","62","באגה\"ק שם: וז\"ש אשת חיל עטרת בעלה כי התורה שבע\"פ . . מעמדת חיילות הרבה כמ\"ש ועלמות כו' (כנ\"ל). והיינו שהוא מצד מעלת הבינה (וראה גם ד\"ה מצה זו תר\"מ פל\"ז. ובכ\"מ). אבל זהו בענין הגילוי בפועל, אבל בשרשו — ה\"ז גילוי הכתר, רצון העליון, וכמו שממשיך שם: וכולן הן בחי' רצון העליון ב\"ה למע' מעלה ממעלת חכמה כו'. וראה המשך תרס\"ו ע' שצב במעלת תושבע\"פ ד„ביגיעתם ועמלם כו' (דהחכמים) ה\"ה ממשיכים אור חדש . . וממילא כל הענינים באים בבחי' התחדשות ממש . . וזהו ג\"כ מה שבתורה שבע\"פ מתחדשים ריבוי דינים מאד ותלי תלים של הלכות וכמא' ועלמות אין מספר אלו הלכות כו' שזהו ג\"כ לפי שממשיכים בחי' אור חדש מהעלם העצמית כו'\"."],["63","63","במעלת דברי סופרים (מה שחביבין מדברי תורה — שהש\"ר עה\"פ א, ב) — ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370236\" data-slug=\"torah-or\" data-id=\"3901370236\">תו\"א נב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>. המשך מצה זו הנ\"ל פמ\"א. ובכ\"מ."],["64","64","ראה אגה\"ק שם."],["65","65","ראה המשך תרס\"ו שבהערה 62."],["66","66","ומובן גם ממקומות שבהערה 63, שמצות שמד\"ס הן מבחי' אור שלמעלה מ(הגבלת ה)כלים, בדוגמת מצות ל\"ת. וראה גם דרך חיים שער התפלה פס\"ד (עא, א ואילך). סה\"מ תר\"ס ע' קנה ואילך."],["67","67","ע\"ד התואר ע\"פ הלכה ובנוגע לפועל: „מים שאין להם סוף\" (יבמות קכא, א. רמב\"ם הל' גירושין פי\"ג הט\"ז וה\"כ) — אע\"פ „שיודעין לשער כמה טפות יש בים\" (הוריות י, סע\"א)."],["68","68","מגילה שם בסוף הע' (וש\"נ) — הובא באגה\"ק שם. וראה רמב\"ם (הל' תשובה ספ\"ח): זה שקראו אותו חכמים עוה\"ב לא מפני שאינו מצוי עתה . . אין הדבר כן, אלא הרי הוא מצוי ועומד . . ולא קראוהו עולם הבא אלא מפני . . (ש)באין לו לאדם אחר חיי העולם הזה."]]],[1300291128,"<h3>שופטים ג</h3>\nא. אין הלכות סנהדרין1 פסק'נט דער רמב\"ם: סנהדרין שפתחו כולם בדיני נפשות תחלה ואמרו כולן חייב הרי זה פטור עד שיהיו שם מקצת מזכין שיהפכו בזכותו וירבו המחייבין ואחר כך יהרג.\nדער מקור דברי הרמב\"ם איז די גמרא אין סנהדרין2 וז\"ל: סנהדרי שראו כולן לחובה פוטרין אותו מ\"ט כיון דגמירי הלנת דין למעבד לי' זכותא והני תו לא חזו לי'3.\nדאָס וואָס דער רמב\"ם זאָגט „שפתחו כולם בדיני נפשות תחלה ואמרו כולן חייב\" און איז משנה פון לשון הגמרא „שראו כולן לחובה\" — איז דאָס בפש־טות בכדי לפרש יותר (כדרך בתראי בכלל)4, אַז דאָס וואָס די גמרא זאָגט בקיצור „ראו כולן לחובה\" מיינט „פתחו כולם . . תחלה ואמרו כולן חייב\", דהיינו אַז באַלד בתחילת הדין5 איז ביי די דיינים ניט געווען קיין סברא לזכות, נאָר גלייך בתחלה „אמרו כולן חייב\"6.\nס'איז אויך מובן פאַרוואָס דער רמב\"ם איז משמיט דעם טעם הדבר וואָס שטייט אין גמרא „מ\"ט כיון דגמירי כו' והני תו",[["1","1","רפ\"ט."],["2","2","יז, סע\"א (כמצויין במפרשי הרמב\"ם — רדב\"ז, כס\"מ וכו')."],["3","3","בדק\"ס שם הובאה גירסא מכ\"י שמסיים „(תו לא חזו לי') זכותא\". וכן הובא ברדב\"ז וכס\"מ שם. וראה לקמן הערה 16."],["4","4","ראה יד מלאכי כללי הרמב\"ם אות כד. ועוד."],["5","5","וי\"ל דהרמב\"ם למדו מלשון הגמרא גופא „ראו כולן לחובה\", ולא „דנו\" וכיו\"ב, שמזה משמע שלא הי' זה אחר משא ומתן, כ\"א ראו כלם לחובה, תיכף בתחילה. וראה הערה הבאה."],["6","6","ראה בספר „מלחמת מצוה\" („עשהו רבינו שלמה בן רבינו שמעון דוראן המכונה רשב\"ץ בעהמ\"ס התשב\"ץ\" — מהשער דפוס ווארשא, חש\"ד) „אלא מיד כשעמד לפני העדה למשפט פתחו כולם ואמרו חייב אתה, הוא פטור. ותראה דיוק לשונם שלא אמרו סנהדרין שדנו כולם לחובה אלא שפתחו שמורה על תחלת הדבור (פתח דבריך יאיר — ל' הכתוב תהלים קיט, קל) כלומר תחלת דברך\". ע\"ש. ומסיים שם „וכך הם דברי הרמב\"ם בהל' סנהדרין\" (והרי הל' „פתחו כולם כו'\" שמביא הוא ברמב\"ם ולא בגמ'). ולפי פירושו נמצא*, שלא הי' כאן שום משא ומתן, אלא זה הי' ראשית ותחלת אמירתם (וראה גם שו\"ת בית יצחק או\"ח סוף הספר השמטה לסי' נג). אבל במנ\"ח מצוה עז (סק\"ג) דאינו תלוי בפתיחה רק תלוי ביום הראשון אם היו כולם לחוב פטור ואם היו בתחילה כולם לחוב ואחר זה חזרו לזכות בודאי נהרג. ע\"ש. ולפי פירושו צ\"ל דזה גופא קמ\"ל הרמב\"ם שתלוי הכל בפתיחה דיום ראשון (שזה אינו מפורש בגמ'). ובאמת שכן מפורש ביד רמה לסנהדרין שם דתלוי ביום ראשון (הובא לקמן הערה 17). וכן משמע מבאר הגולה למהר\"ל בבאר השני (דלא תלוי באמירתם הראשונה אלא בדעתם והסכמתם בדין). וכן מוכח מדבש לפי להחיד\"א מערכת ח אות כא (דמביא מהפוסקים „דדוקא אם כולם מטעם אחד אבל אם מטעמים חלוקים הו\"ל רוב לחיובא\", שאי\"ז שייך לאמירת כולם חייב בפתיחת הדיון). — אלא שמלשון הרמב\"ם משמע שלא מקרי זה גמר דין**. וראה לקמן בפנים. — ועצ\"ע. — וראה לקמן הערה 28. *) ודוחק גדול לומר שכוונתו שמכיון שאמרו כן להחוטא (כלשונו שם „חייב אתה\") א\"כ הרי\"ז היפך הדין דאין פותחין בדיני נפשות לחובה אלא לזכות (סנהדרין לב, א (במשנה). רמב\"ם הל' סנהדרין פ\"י ה\"ז), וכפי שמשמע לכאו' גם מהמשך לשונו שם „אבל אם נשאו ונתנו בזכותו ופתחו לו לזכות ואמרו לו אל תירא כו'\", כי פתיחה בזכות להחוטא אינה שייכת לנדו\"ד (ראה מנ\"ח שבפנים ההערה). **) משא\"כ להפירוש בשיטה שבסוף חמרא וחיי סנהדרין כאן (בשם הרא\"ש. ובקהלת יעקב (אלגאזי) לשון חכמים סי' תלא בשם המאירי) „פי' רבינו מאיר ממהרין להרגו מיד\" — נמצא דהוי גמר דין שלהם."]]],[1300291129,"לא חזו לי'\" — ווייל ס'איז ניט דרכו של הרמב\"ם צו ברענגען בחיבורו די טעמי ההלכות7.\nמ'דאַרף אָבער פאַרשטיין דעם המשך דברי הרמב\"ם — „הרי זה פטור עד שיהיו שם מקצת מזכין שיהפכו בזכותו וירבו המחייבין ואחר כך יהרג\":\nא) וויבאַלד די הלכה איז אַ הקדמה ויסוד צו דעם תוכן כללי פון דעם פרק — די הגדרה וואָס ס'הייסט רוב לחיוב און רוב לזכות — האָט דער רמב\"ם גע־דאַרפט לכאורה אָנהויבן מיטן עיקר — דער אויספיר פון דער הלכה, אַז דער חיוב בדיני נפשות איז (דוקא) ווען „היו שם מקצת מזכין שיהפכו בזכותו וירבו המחייבין כו'\", און דערנאָך אויספירן „אבל סנהדרין שפתחו כולם בדיני נפשות תחלה ואמרו כולן חייב הרי זה פטור\".\nב) וויבאַלד דער רמב\"ם זאָגט דאָ דעם צד הפטור ווען „אמרו כולן חייב\" און דעם צד החיוב ווען „יהיו שם מקצת מזכין שיהפכו בזכותו וירבו המחייבין\" — האָט דער רמב\"ם געדאַרפט זאָגן און אויספירן (ניט „ואחר כך יהרג\", נאָר) „ואחר כך יתחייב\"8 (וכיו\"ב) — בהתאם (ניגוד) צו „הרי זה פטור\".\nב. וועט מען דאָס פאַרשטיין בהקדם הביאור אין דעם טעם הגמרא „כיון דגמירי הלנת דין למעבד לי' זכותא והני תו לא חזו לי'\", וואָס לכאורה קען מען עס לערנען אויף צוויי אופנים:\nא) דער עיקר איז הלנת דין (און דער „למעבד לי' זכותא\" איז בלויז דער טעם והסברה פאַרוואָס עס דאַרף זיין הלנת דין). ד. ה. דאָס וואָס „פוטרין אותו\" איז דערפאַר וואָס אויב „ראו כולן לחובה\" איז ניטאָ קיין מעגלעכקייט צו מקיים זיין איינעם פון די תנאים וואָס זיינען דאָ אין פאַל פון לא מצאו לו זכות9 — דעם תנאי „(בעי) הלנת דין\".\nב) דער טעם און סיבת הפטור איז דאָס וואָס „הני תו לא חזו לי'\", און „הלנת דין\" איז נאָר אַן ענין וואָס פירט צו דער סיבה.\nד. ה. דאָס וואָס „פוטרין אותו\" איז ניט ווייל אין דעם פאַל קען דער ב\"ד ניט מקיים זיין איינעם פון די תנאים, נאָר וויבאַלד אַז „ראו כולן לחובה (איז) תו לא חזו לי' (זכותא)\" (ובמילא פעלט אין דעם „ושפטו העדה והצילו העדה\"10 — עדה מצלת<sup data-n=\"11\">11</sup>, און אַזאַ ב\"ד וואָס קען ניט זען אַ זכות איז ניט אין גדר צו מחייב זיין — און דערפאַר „פוטרין אותו\".\nאין אַן אַנדער סגנון: לויטן ערשטן אופן איז דאָס אַ „חסרון\" וואָס איז נוגע דעם פסק פון די סנהדרין, עס קען ניט זיין קיין פסק ב\"ד כדבעי (ווייל עס פעלט דער קיום התנאי פון הלנת הדין)12; לויטן צווייטן אופן איז דאָס אַ חסרון אין דעם גברא הפוסק — די סנהדרין\n[ע\"ד ווי „סנהדרין שראו אחד שהרג את הנפש\" וואָס זיי קענען ניט ווערן (לדעת רע\"ק) קיין דיינים „דרחמנא אמר",[["7","7","ראה הל' ת\"ת לאדה\"ז קו\"א רפ\"ב."],["8","8","כלשונו שם פ\"ט ה\"ב. סה\"ג. ועוד."],["9","9","ראה פרש\"י סנהדרין שם (יז, א) ד\"ה כיון דגמירי."],["10","10","מסעי לה, כד־כה."],["11","11","משנה ריש סנהדרין (ב, סע\"א). ועד\"ז בכ\"מ. וראה לקמן בפנים מר\"ה כו, א."],["12","12","להעיר מקרית ספר להמבי\"ט הל' סנהדרין כאן, דמספקא לי' אם הדין דפוטרין אותו כאן הוי מדאורייתא או מדרבנן."]]],[1300291130,"ושפטו העדה והצילו העדה וכיון דחזיוהו דקטל נפשא לא מצו חזו לי' זכותא\"13, איז ניט דער פשט אַז דער פסק זייערער איז ניט ריכטיק, נאָר זיי הייסן ניט קיין סנהדרין לגבי דעם מענשן וואָס „ראו . . שהרג את הנפש\"14].\nג. פון דער גמרא איז יש מקום להוכיח הן כאופן הראשון, הן כאופן השני:\nאַ ראי' צום ערשטן אופן קען מען מדייק זיין פון דעם וואָס די גמרא ברענגט מפורש נאָר דעם דין „כיון דגמירי הלנת דין\", און ניט דעם מקור פון דעם דין אַז מ'איז מחוייב צו זוכן אַ זכות אויפן נידון15, ובפרט אַז די גמרא זאָגט ניט דעם טעם (ע\"ד ווי די גמרא הנ\"ל „סנהדרין שראו אחד שהרג\") „דרחמנא אמר ושפטו העדה והצילו העדה\" — איז משמע פון דעם, אַז דאָ איז בעיקר נוגע וואָס מ'קען ניט מקיים זיין די הלכה פון הלנת דין.\nאָבער מאידך גיסא — פון דעם וואָס די גמרא איז זיך ניט מסתפק מיטן זאָגן בלויז דעם דין כיון דגמירי הלנת דין, און איז מוסיף דעם טעם „למעבד לי' זכותא\" און פירט אויס „והני תו לא חזו לי'\"16 — איז משמע אַז דער עיקר חסרון איז אין די „והני\", דאָס וואָס „לא חזו לי' (זכותא)\"17, ווי דער צווייטער אופן.\n[זאת ועוד: דוקא לויטן צווייטן אופן איז מדוייק דער לשון הגמרא „סנהדרין שראו כולן לחובה\", והיינו, אַז דער חסרון דאָ איז וואָס זייער ראי' איז נאָר לחובה און דערפאַר קענען זיי ניט זען זכותו (ע\"ד הנ\"ל בא „סנהדרין שראו אחד שהרג את הנפש\")].\nועפ\"ז י\"ל אַז עס קען אויך זיין אַ נפק\"מ לדינא: לויט דעם ערשטן אופן, אַז ס'איז אַ חסרון אין דעם פסק פון דעם ב\"ד, דאַרף אויסקומען אַז אויב דער ב\"ד געפינט דערנאָך אַ סברא לזכות, איז מקום לומר אַז זיי קענען נאָכאַמאָל18 דן זיין דעם נידון19:",[["13","13","ר\"ה כה, סע\"ב ואילך."],["14","14","ומכ\"ש שכ\"ה לטעם הב' (והעיקרי) „עד עמדו לפני העדה למשפט (מסעי לה, יב) עד שיעמוד בב\"ד אחר\" — מכות יב, א (ראה תוד\"ה דרחמנא אמר — ר\"ה שם כו, א. וש\"נ)."],["15","15","ועד דמי שלמד זכות אינו חוזר ומלמד חובה (סנהדרין לב, א — במשנה. וע\"ש בפרש\"י (ד\"ה אינו) דהוי מטעם והצילו העדה)."],["16","16","ובפרט לגירסת ש\"ס כ\"י (הובא בדק\"ס סנהדרין שם) שחוזר ומפרט „והני כיון דלא חזו לי' זכותא (תו כו')\"."],["17","17","ואולי י\"ל דשינוי הלשונות בהפירושים דהיד רמה והמאירי לסנהדרין הוא לפי שפליגי בפי' דברי הגמ' כנ\"ל: ביד רמה: אמר רב כהנא סנהדרין שראו כולן לחובה ביום ראשון פוטרין אותו מאי טעמא משום דגמירי הלנת דין שאם לא מצאו לו זכות ביום ראשון צריכין להלין את דינו אולי ימצאו לו זכות למחרת ויראה אחד מן המחייבין דברי המזכין והני כיון דהשתא לא חזי לי' חד מינייהו זכותא תו לא חזי לי' ולא מהני למעבד לי' הלנת דין ובעינא (הוי קרי) [הלנת דין] דחזיא להדורי בתר זכותא וליכא הילכך פטרינן לי': במאירי: סנהדרין שפתחו בדיני נפשות כלן לחובה פוטרין אותו. מכיון שתקנו הלנת דין למי שלא מצאו לו זכות ביום ראשון. שמא ימצאו לו טעמי זכות. מכיון שפתחו כלם לחובה אין רואין לו עוד זכות. ואינו נהרג עד שיהפכו מקצתן בזכות וירבו המחייבים: דהיד רמה מדגיש א) הזמן בנדו\"ד „שראו כולן לחובה ביום ראשון\", ב) דצריך למעבד הלנת דין, ובמאירי ההדגשה דאין רואין לו עוד זכות (והזמן דיום ראשון כתב בהתקנה דהלנת דין (כבפרש\"י בהסוגיא ד\"ה כיון דגמירי) לא בנדו\"ד)."],["18","18","וע\"ד מ\"ש הרמב\"ם שם פ\"י ה\"ט."],["19","19","במנ\"ח שם סוסק\"ט מספקא לי' „אם ראו כולם לחוב ובאותו היום ראו קצת בשכלם זכות אי"]]],[1300291131,"משא\"כ לויטן צווייטן אופן, וויבאַלד זיי זענען ניט בגדר סנהדרין (לגבי דעם מענשן) מחמת דעם וואָס „ראו כולן לחובה\", איז מסתבר אַז זיי קענען שוין מער ניט דן זיין דעם נידון — אויך ווען זיי געפינען דערנאָך אויף אים אַ זכות.\nד. פון דברי הרמב\"ם איז משמע אַז ער לערנט ניט ווי די ביידע אופנים הנ\"ל:\nאע\"פ אַז ס'איז ניט דרכו צו ברענגען טעמי ההלכות, אָבער אויב דער רמב\"ם וואָלט געלערנט אַז דער חסרון איז ווייל עס פעלט דער קיום התנאי פון הלנת הדין (כאופן הא') איז מסתבר אַז דער רמב\"ם וואָלט דאָס דערמאָנט, היות אַז דאָס איז ניט סתם אַ טעם, נאָר (אויך) אַ תנאי20.\nאון פון המשך דברי הרמב\"ם איז מס־תבר אַז דער חסרון איז ניט (ווי דער אופן הב' הנ\"ל) אין דעם וואָס זיי האָבן ניט די יכולת צו זען אַ זכות (וויבאַלד אַז „ראו כולן לחובה\"<sup data-n=\"21\">21</sup>, נאָר אין דעם וואָס עס פעלט דער „(מקצת מזכין ש)יהפכו בזכותו\" בפועל.\nוהיינו: פון לשון הרמב\"ם „הרי זה פטור עד שיהיו כו' ואחר כך יהרג\" — איז משמע, אַז דאָס איז ניט קיין חסרון אין דעם גברא הפוסק, אין די סנהדרין, נאָר אין דעם אויספיר פונעם פסק בפועל אין דעם נידון —\nאון דערפאַר (א) זאָגט ניט דער רמב\"ם „פוטרין אותו\" (וואָס וואָלט מדגיש געווען אַז דער פטור איז פאַר־בונדן מיטן ב\"ד און זייער פסק), נאָר „הרי זה פטור\", וואָס רעדט וועגן דעם נידון, אַז ער איז פטור פון מיתה; און (ב) מהאי טעמא איז דער רמב\"ם ממשיך „עד שיהיו כו' ואחר כך יהרג\", אַז דורך „מקצת מזכין כו'\" שאַפט זיך די אפ־שריות (ניט אויפן חיוב — „ואחר כך ית־חייב\", נאָר) אויף צו דורכפירן דעם בפועל — „ואחר כך יהרג\"21*.",[["","","מותרים לומר הזכות דמלמד חובה יכול לחזור לזכות כו' והורגין אותו\", או* „כיון דתיכף ראו חובה ונפטר א\"כ ע\"י זכות זה שרוצה ללמד חובה הוא לנידון כו'\"**. אמנם עדיין י\"ל הנפק\"מ כבפנים: א) כאשר אין המדובר באותו היום, וא\"כ הוי כישיבת דין עוה\"פ (מעין סנהדרין אחר***), ב) לא רק קצתם ראו בשכלם לזכות אלא רובם, שאז ה\"ז זכות גם בפועל (משא\"כ כאשר רק קצתם אומרים שאז הזכות הוא רק באמירתם אבל הזכות הוא חובה לו, וכמ\"ש במנ\"ח שם). — וי\"ל דתלוי אם הנדון מקרי שיצא זכאי בדין, שאז אין מקום לדונו עוה\"פ או שרק לא נתחייב**** (ויתירה מזו, רק אין הורגין אותו — כדעת הרמב\"ם — כדלקמן בפנים), שאז ה\"ז זכות גם בפועל. ואכ\"מ. *) ועפ\"ז צ\"ל דמ\"ש המנ\"ח לפנ\"ז בסוס\"ג (כבהערה 6) כדבר הפשוט „אם פתחו כולם לחוב ואחר זה חזרו קצת וזיכו בודאי נהרג\", המדובר בהמשך אותו הדיון, ובסוסק\"ט מדבר לאחרי שעמדו מדיון הא' וישבו עוה\"פ באותו היום. **) וראה אוה\"ח משפטים כג, ב. ***) ולהעיר מרמב\"ם שם פי\"ג ה\"ז־ח. אבל כמובן אינו שייך לנדו\"ד דשם מדובר „שנגמר דינו\". ****) ראה ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג עשה צו."],["20","20","ראה אנציקלופדי' תלמודית ערך הלנת הדין בסופו, דיש מסתפקין אם הלנת דין מעכבת. ולהעיר מקרית ספר הנ\"ל הערה 12. ע\"ש."],["21","21","ולהעיר שהרמב\"ם לא פסק כר\"ע כ\"א כר\"ט שעד הרואה נעשה דיין — ראה כס\"מ ולח\"מ לרמב\"ם הל' עדות ספ\"ה. אלא די\"ל דזהו רק מפני שיכול להתקיים „והצילו העדה\" על ידי השאר שלא ראו איך שהרג את הנפש, משא\"כ בנדו\"ד שכולם אינן יכולין לראות זכות. וראה טורי אבן לר\"ה שם ד\"ה ל\"ק ר\"ע. שו\"ת בית יצחק חו\"מ ס\"ב אות ט'. ביאור הרי\"פ פערלא שם. ואכ\"מ. 21*) ומתורצת גם שאלה הא' הנ\"ל סעיף א'."]]],[1300291132,"ה. ולבאר זה יש להקדים:\nעס זיינען דאָ מפרשים22 וואָס זיינען מסביר דעם טעם פון דעם דין „סנהד־רין שפתחו כו'\", אַז וויבאַלד „פתחו כולם . . ואמרו כולן חייב\" איז דאָס אַ באַווייז אויף אַ חסרון אין די סנהדרין, אַז זייער צוגאַנג צו דעם דין איז ניט גע־ווען ריכטיק (ווייל „גילו דעתם . . כולם חפצים להמיתו\"23; אָדער ווייל24 אויף יעדן נידון קען מען געפינען איזה צד של זכות — און היות זיי אַלע האָבן דאָס ניט געפונען, איז אַ ראי' אַז זיי זיינען ניט בקי בדינים, אָדער אַז זיי האָבן מחליט געווען במהירות און ניט מעיין געווען כראוי אין דעם דין, וכיו\"ב, בכמה הסברות אין דעם חסרון שבה־סנהדרין).\nכמובן איז אָבער אַ דוחק גדול לומר אַזוי בנוגע צו ב\"ד בכלל, ועאכו\"כ בנוגע צו סנהדרין גדולה\n[וואָס וועגן זיי רעדט דער דין, כמ־פורש ברמב\"ם לכמה גירסאות25. און אַזוי איז אויך מובן25* פון תוכן הדין (וואָרום אויב דאָ רעדט זיך וועגן סנהד־רין קטנה פון כ\"ג איז פאַרוואָס „פוטרין אותו\"? מ'האָט אים געדאַרפט דן זיין בב\"ד אחר26 ביז (אויב מ'דאַרף) איבער־געבן דעם דין ומשפט צו סנהדרין גדולה)],\nאַ דוחק גדול ווייל אפילו אין סנהדרין קטנה „אין מעמידין . . אלא אנשים חכמים ונבונים מופלגין בחכמת התורה בעלי דיעה מרובה כו'\"27. ווי איז שייך אַז ביי זיי אַלעמען זאָל זיין ניט קיין ריכטיקער צוגאַנג צו דעם דין וכו'28?!\nובפרט ווען פון דברי הרמב\"ם איז מוכח, כנ\"ל, אַז דאָס איז בכלל ניט קיין „חסרון\" אין די סנהדרין אָדער אין פסק דינם, נאָר אַלץ בשייכות צו דעם אדם הנידון.\nו. וי\"ל ההסברה בזה:\nס'איז ידוע אַז דין עונשי ב\"ד, מיתה מלקות וכו', איז עיקרם לשם כפרה. ווי מפורש בנוגע למלקות29 „ונקלה אחיך לעיניך כשלקה הרי הוא כאחיך\", עד\"ז שטייט30 באַ עונש מיתה, אַז דורכדעם קומט דער נענש לחיי עוה\"ב [אויך",[["22","22","מהר\"ץ חיות לסנהדרין שם. וראה מלחמת מצוה ובאר הגולה שנסמנו בהערה 6 (וראה הערה 28)."],["23","23","מלחמת מצוה שם."],["24","24","מהר\"ץ חיות שם."],["25","25","ראה רדב\"ז לרמב\"ם. וכן הובא במגדל עוז. לח\"מ. וכ\"ה גי' הכ\"י בגמרא — ראה דק\"ס סנהדרין שם. 25*) כמ\"ש באור שמח שם."],["26","26","להעיר, שב„מלחמת מצוה\" (הנ\"ל הערה 6) כ' „ואפילו בב\"ד אחר לא יוכל ללמד זכות על עצמו לפיכך נפטר מכל וכל\". וב„באר הגולה\" שם מסיים „אין על ב\"ד של מטה לדון אותו וידון אותו שופט כל הארץ\". ואכ\"מ."],["27","27","רמב\"ם הל' סנהדרין רפ\"ב."],["28","28","בנוגע למ\"ש ב„מלחמת מצוה\" („וכיון שסנהדרין אלו טעו בכך ופתחו כו' כולם חפצים להמיתו\", כנ\"ל בפנים) — הרי כל הספר הוא „נגד אנשי זדון אנשי רשע אשר הרהיבו להשיב על דברי רז\"ל כו', והראה לעיני העמים את צדק דיניהם . . ומלתעות אפיקורסים . . שיבר\" (לשון השער בספר מלחמת מצוה), י\"ל, בדוחק גדול, שלא כתב להם אמיתית הפירוש ע\"פ תורה כ\"א ענין שיתקבל בשכלם. וע\"ד שמצינו בש\"ס כיו\"ב כמ\"פ שדחו בקש (וראה רשב\"ם ב\"ב קטז, רע\"א). ובפרט דהתשובה היתה לא רק לאפיקורסים כ\"א גם „לעיני העמים\" (כמ\"ש בהשער), ד„אסור לגלות להם טעמי תורה\" (כלשון הרשב\"ם שם)."],["29","29","תצא כה, ג. מכות כג, סע\"א — במשנה (הובא בפרש\"י עה\"פ)."],["30","30","משנה סנהדרין מג, ב."]]],[1300291133,"להלכה פסק'נט דער רמב\"ם31 אַז „כל מחוייבי מיתות ב\"ד ומחוייבי מלקות אין מתכפר להם במיתתן או בלקייתן עד שיעשו תשובה ויתודו\"32, וואָס דערפון איז מובן אַז דער תכלית מיתת ב\"ד אָדער מלקות איז לכפרת האדם, נאָר די כפרה איז בתנאי „שיעשה תשובה ויתודה\"].\nועפ\"ז מסתבר, אַז אין אַ פאַל ווען מיתת ב\"ד וועט (קען) ניט ברענגען די כפרה איז ניטאָ קיין מקום צו דורכפירן די מיתה. וע\"ד ווי דער כסף משנה33 איז מסביר דעם פסק הרמב\"ם34 בנוגע צו עדים זוממין, אַז „נהרג זה שהעידו עליו ואחר כך הוזמו אינן נהרגין מן הדין שנאמר35 כאשר זמם לעשות ועדיין לא עשה כו' אבל אם לקה זה שהעידו עליו לוקין\" — און ער איז מבאר דעם טעם החילוק בזה\n„דלא אמרינן כאשר זמם ולא כאשר עשה אלא היכא דהרגו על פיהם משום דגדול עונשם מנשוא אין ראוי לתת להם מיתת ב\"ד שתכפר עליהם אלא ראוי לה־ניחם שיהיו נדונין אחר מיתה בעונשים נוראים דוגמא לדבר36 נותן כל זרעו למולך שהוא פטור37 מה שאין לומר כן בהלקו ע\"פ עדותם\".\nועד\"ז בנדו\"ד: וויבאַלד אַז (פתחו כולם כו' ואמרו כולן —) אַ ב\"ד כשר, וואָס „אלקים נצב בעדת א־ל\"38, ועאכו\"כ סנהדרין גדולה שבלשכת הגזית, האָבן אַלע באַלד געזאָגט חייב, און ס'איז ניטאָ אפילו קיין איינער וואָס זאָל מלמד זכות זיין — איז אַ ראי' אַז דער נידון איז „גדול עונו מנשוא\" — ער געפינט זיך במעמד ומצב ירוד ביותר, ביז אַז עונש מיתת ב\"ד איז אינו יכול לכפר עליו און דערפאַר „פוטרין אותו\".\nדאָס איז אָבער ניט אינגאַנצן מספיק לבאר לשון הרמב\"ם „הרי זה פטור עד כו' ואח\"כ יהרג\", פון וועלכער עס איז משמע אַז דער פסק הסנהדרין איז אַ פסק נאָר דער נידון ה\"ז פטור, מ'קען עס ניט אויס־פירן באַ דעם נידון (כנ\"ל סעיף ד) — אָבער לפי הנ\"ל איז הסנהדרין וואָס „פתחו כולם . . ואמרו כולן חייב\" זאָגט אַז ביי דעם מענטשן איז ניט שייך דער חיוב (עונש) אַלס כפרה, דהיינו, אַז זייער פסק „חייב\" איז ניט קיין פסק [„ובמילא\" וואָלט מער מתאים געווען צו זאָגן דעם לשון „פוטרין אותו\" (כלשון הגמרא), וואָס איז מדגיש, אַז אין דעם פאַל קען ב\"ד ניט אַרויסגעבן אַ פסק, ווייל „גדול עונו מנשוא\"].\nז. ויש לומר בזה עוד ביאור:\nיעדער איד, אין וועלכן מעמד ומצב ער זאָל ניט זיין, איז כפסק הרמב\"ם39, אפילו אַ איד, וואָס ב\"ד מוז אים כופה זיין צו געבן אַ גט לאשתו, איז „הוא רוצה להיות מישראל ורוצה הוא לעשות כל המצות ולהתרחק מן העבירות\".\nואפילו בנוגע צו עכן, וואָס איז גע־ווען בתכלית הירידה, זאָגן חז\"ל40",[["31","31","הל' תשובה בתחלתן."],["32","32","שבגמ' שם (מז, א־ב) מחלוקת אביי ורבא, ולרבא (וכן ס\"ל לר\"י ור\"א) נהרג מתוך רשעו יש לו כפרה. ופסק כאביי — ראה צפע\"נ לרמב\"ם שם. ואכ\"מ."],["33","33","הל' עדות פ\"כ ה\"ב בסופה."],["34","34","הל' עדות שם."],["35","35","פרשתנו יט, יט."],["36","36","ראה סמ\"ג ל\"ת מ."],["37","37","סנהדרין סד, ב. רמב\"ם הל' ע\"ז פ\"ו ה\"ד."],["38","38","תהלים פב, א. וראה סנהדרין שבהערה 45."],["39","39","הל' גירושין ספ\"ב."],["40","40","סנהדרין מד, רע\"א."]]],[1300291134,"„אע\"פ שחטא ישראל הוא\".\nדער חילוק איז נאָר אויף וויפל דער „רוצה הוא לעשות את כל המצות\", דער טוב פון אַ אידן איז: באמירתו בגלוי אָדער בהעלם: עס זיינען דאָ אידן וואָס ביי זיי איז דער טוב בתכלית ההתגלות, און עס זיינען דאָ אידן וואָס ביי זיי איז דאָס ניט אַזויפיל בהתגלות, ביז עס זיינען דאָ אַזעלכע וואָס זייער טוב איז בהעלם לגמרי, אָבער אַ מקצת פונעם טוב הנעלם קומט סו\"ס לידי איזה גילוי — וואָרום דער טוב ביי אַ אידן איז ניט אַ דבר נוסף41 אויף זיין מהות (ווי די ענינים (פון רע) וועלכע קומען41 מצד דעם וואָס „יצרו הוא שתקפו\"<sup data-n=\"42\">42</sup>, נאָר דאָס איז דער עצם און די אמיתיות פון זיין מציאות.\nעפ\"ז איז מובן, אַז יעדער איד, יהי' מי שיהי', אויך בשעת ער איז עובר אַן עבירה אויף וועלכן עס קומט מיתת ב\"ד, מוז זיין אַ לימוד זכות אויף אים, ווייל זיין אמת'ר רצון, זיין אמיתיות מציאותו איז דער טוב שבו43.\nבשעת אָבער אַז סנהדרין „פתחו כולם בדיני נפשות תחלה ואמרו כולן חייב\", באַווייזט דאָס אַז דער טוב שבו איז אויף אַזויפיל נתעלם געוואָרן, אַז אפילו סנהדרין גדולה וועלכע זיינען „חכמים ונבונים מופלגין כו'\" — ד. ה. זיי זיינען „נבונים\" להבין דבר מתוך דבר44 וב־הפלגה, צו פאַרשטיין און אויפנעמען דאָס וואָס איז באַהאַלטן און ניט אַנט־פלעקט — אויך זיי אַלע קענען ניט גע־פינען קיין זכות אויף אים — איז בנוגע צו אַזאַ זאָגט מען „הרי זה פטור\": וויבאַלד אַז ביי אים איז דאָך זיכער פאַראַן טוב, נאָר דער ב\"ד קען עס ניט „געפינען\" דערפאַר וואָס ער איז בתכ־לית ההעלם — קען דערפאַר ביי אים ניט אויסגעפירט ווערן דער (תכלית הפסק ובמילא ניט דער) פסק פון דעם ב\"ד.\nעס איז ניט קיין חסרון אין דעם ב\"ד אָדער אין זייער צוגאַנג צו דעם פסק — וואָרום אמרה תורה אין לו לדיין אלא מה שעיניו רואות45, און אַלץ וואָס די סנהדרין גדולה אשר יהי' בימים ההם46 דאַרף און קען זען, האָבן זיי געזען;\nאָבער וויבאַלד אַז פס\"ד תורת אמת איז אַז ער איז רוצה לקיים כל המצות, אַז אין אים איז דאָ טוב (וועלכע איז ניט אַנטפלעקט געוואָרן), קען דער פסק ב\"ד אויף אים ניט חל זיין — „עד שיהיו שם מקצת מזכין שיהפכו כו'\".\nוי\"ל עוד ענין — אַז דורך דעם גופא ווערט נתגלה אויך דער טוב וואָס איז פריער געווען בתכלית ההסתר וה־העלם, און וויבאַלד אַז עס ווערט בהת־גלות קען דער פסק ב\"ד אויף אים חל זיין — און „יהפכו בזכותו כו'\".\nבעומק יותר: ווען קען דער פסק ב\"ד „יהרג\" אויסגעפירט ווערן אויף דעם אידן — דוקא לאחרי ווי „יהיו שם מקצת מזכין שיהפכו בזכותו\", ווייל ווי גערעדט פריער (מהכסף משנה) איז דער תוכן ותכלית פון עונשי ב\"ד — כפרת האדם. און ווען קען אַן עונש ברענגען צו אַ כפרה, דוקא ווען דאָס",[["41","41","ראה סה\"מ תרנ\"ט (ע' פה)."],["42","42","ל' הרמב\"ם הל' גירושין שם."],["43","43","במכש\"כ וק\"ו מהטעם „אמור לאומן שעשאני\" (תענית כ, ריש ע\"ב) ובנדו\"ד הוא בו."],["44","44","ראה ספרי ופרש\"י דברים א, יג."],["45","45","ראה סנהדרין ו, סע\"ב. וש\"נ."],["46","46","פרשתנו יז, ט. „אינך חייב ללכת אלא אחר ב\"ד שבדורך\" (רמב\"ם הל' ממרים פ\"ב ה\"א. וראה ספרי ופרש\"י עה\"פ)."]]],[1300291135,"רירט אָן (און איז מגלה) דעם טוב שבו. און דעריבער, בשעת אַלע זעען נאָר חובה, וואָס דאָס מיינט אַז דער טוב שבו איז בתכלית ההעלם וההסתר, קען דער עונש („יהרג\") ניט אויפטאָן אַ כפרה אין דעם אידן;\nדוקא לאחרי ווי מ'איז מהפך בזכותו, וואָס דאָס גופא ברענגט אַרויס דעם טוב שבו47, דעמאָלט טוט אויף דער עונש פעו־לתו — אַז דער איד באַקומט זיין כפרה און איז זוכה לעוה\"ב.\nח. פון דעם נעמט מען אַרויס אַ הוראה אין גודל מעלתם און זכותם של ישראל:\nאפילו ווען עס רעדט זיך וועגן אַזאַ אידן וואָס געפינט זיך בשפל המצב עד כדי כך, אַז אפילו סנהדרין וואָס די תורה זאָגט אַז ענינם איז „והצילו העדה\" — צו זוכן און געפינען אַ הצלה וזכות אויף יעדער אידן, און דאָך זעען אויך זיי אויף אים נאָר חובה, זיי זעען ניט קיין זכות אויף אים — פונדעסטוועגן פסק'נט תורת אמת אַ פסק דין ברור, אַז דאָס איז אַ מציאות וואָס קען ניט זיין, אויך ביי דעם אידן איז דאָ דער רוצה לקיים כל המצות; ובמילא ברענגט דאָס גופא אַז די סנהדרין זיינען מלמד זכות אויף דעם אידן און דורך דעם47 איז מען מגלה דעם רוצה שבו, טוב שבו.\nעאכו\"כ ווען עס רעדט זיך וועגן אידן בדורנו וואָס אע\"פ אַז מ'איז אין אַ מצב פון „אני ישנה\"48, איז אָבער „לבי ער\" להקב\"ה ולתורתו ולמצותיו49, און ווען דאָס אידישע האַרץ איז, כפס\"ד תורת אמת, וואַך — ווערט עס סו\"ס דער־וועקט און קומט לידי גילוי;\nובפרט געפינענדיק זיך איצט אין זמן פון חודש אלול ווען דער מלך (מה\"מ הקב\"ה) געפינט זיך „בשדה\", „ואז50 רשאין (ויכולים<sup data-n=\"51\">51</sup> כל מי שרוצה לצאת להקביל פניו (בשדה) והוא מקבל את כולם בסבר פנים יפות ומראה פנים שוחקות לכולם\" —\nדאַרף מען אַרויסגיין און פועל זיין אויף יעדן אידן אין וועלכן מצב ער זאָל נאָר זיין, אַז עס זאָל ביי אים ווערן בגלוי דער „רצון\" צו מקבל זיין פני המלך בשדה.\nוואָס די פעולה איז דורך דעם גופא: בשעת מ'איז מהפך ומדבר בזכותו פון אַ אידן, אַז בו, אין אים איז דאָ דער חלק אלקה ממעל ממש, דער ניצוץ אלקי, ביז אַז — בלשון הרמב\"ם „הוא רוצה להיות מישראל ורוצה הוא לעשות כל המצות ולהתרחק מן העבירות\", און אַז דאָס איז אמיתית מציאותו — איז מען דורך דעם גופא נאָכמער מגלה דעם טוב שבו,\nאון מ'פועל'ט אויף אים אַז ער זאָל אַרויסגיין — „לצאת\" — ממקומו („ב־מדבר\"<sup data-n=\"52\">52</sup> בכדי לקבל פני המלך „בשדה\",",[["47","47","וכמובן מהביאור במחז\"ל (ערכין טו, ב. רמב\"ם הל' דעות פ\"ז ה\"ג) שלשון הרע „קטיל תליתאי\", גם „זה שאומר עליו\" (אף שאינו עובר עבירה) — כי ע\"י לה\"ר מגלה ומוציא הרע שלו, ומרובה מדה טובה, דכאשר מדבר בזכותו ה\"ז מגלה הטוב של השני (ועאכו\"כ כאשר נעשה על ידי הסנהדרין) — ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271177\" data-slug=\"likkutei-sichot\" data-id=\"1300271177\">לקו\"ש חכ\"ז ע' 163</a> ואילך (וראה שם גם ביאור דברי הרמב\"ם הל' דעות פ\"ה ה\"ז „מספר בשבח חבירו ולא בגנותו כלל\") ובהנסמן שם."],["48","48","שה\"ש ה, ב."],["49","49","ראה ד\"ה אני ישנה בסה\"מ אידיש. ובכ\"מ."],["50","50","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380844\" data-slug=\"likkutei-torah\" data-id=\"4001380844\">לקו\"ת ראה לב, סע\"א</a> ואילך."],["51","51","הוספת כ\"ק מו\"ח אדמו\"ר — סד\"ה לך אמר לבי ה'ש\"ת."],["52","52","ראה לקו\"ת שם לב, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041342\" data-slug=\"likkutei-sichot\" data-id=\"1300041342\">לקו\"ש ח\"ד ע' 1343</a>."]]],[1300291136,"וואָס עי\"ז ווערט נתגלה, נוסף אויף „מקצת\" פון זיין טוב („מקצת מזכין ש־יהפכו בזכותו\"), עס ווערט נתגלה זיין טוב במדה מרובה, ביז אַז דער ריבוי הטוב והזכות איז מכריע דעם צד ההפכי בא אים און מכריע דאָס וואָס ער איז „שקול\" און בריינגט עם „תשועה והצלה\"53 ואח\"כ יוצא זכאי בדין,\nיעדער איד ווערט נתעורר מיט אַ תשובה כדבעי ובשלימות, ובמילא האָט ער אַ כפרה שלימה ווי דאָס איז אַ נשמה שלימה בגוף שלם, נשמה בגוף למטה מעשרה טפחים54, און יעדער איינער און איינע ווערט נכתב ונחתם לאלתר55 בספרן של צדיקים גמורים לשנה טובה ומתוקה בטוב הנראה והנגלה בגשמיות וברוחניות גם יחד.\n(משיחת ש\"פ תשא תשמ\"ה)",[["53","53","רמב\"ם הל' תשובה פ\"ג ה\"ד."],["54","54","ע\"ד מרז\"ל באותו מקום (יומא פו, ב)."],["55","55","ר\"ה (טז, ב) וב„מדרש\" (ירושלמי ר\"ה פ\"א ה\"ג. יל\"ש ואתחנן רמז תתנה) הובא בטאו\"ח (סו\"ס תקפא) שכבר בער\"ה בטוחין שזוכין כו' ועד שמתעטפין כו'."]]],[1300291137,"<h3>תצא</h3>\nא. גלייך נאָך דעם ציווי1 אויף דעם איסור שעטנז — „לא תלבש שעטנז צמר ופשתים יחדיו\" — זאָגט אָן תורה2 „גדילים תעשה לך על ארבע כנפות כסותך גו'\", און פון דעם וואָס די צוויי פסוקים שטייען בסמיכות זל\"ז לערנט מען אָפּ3: „גדילים תעשה לך — אף מן הכלאים\"4, אַז כלאים זיינען מותר בציצית.\nעד\"ז געפינט מען דעם היתר פון כלאים ביי די בגדי כהונה — צווישן די בגדי כהונה, וואָס כהנים טראָגן בעבודתם במקדש, איז געווען דער אבנט, וואָס איז געמאַכט געוואָרן פון שעטנז5.\nדאַרף מען פאַרשטיין:\nעס זיינען פאַראַן דריי מיני כלאים — „בקרקע ובבהמה ובבגדים\"6, ווי די תורה רעכנט זיי דאָ אויס בהמשך אחד7: „לא תזרע כרמך כלאים גו' לא תחרוש בשור ובחמור יחדיו לא תלבש שעטנז גו'\"8 [ועד\"ז אין פ' קדושים9: בהמתך לא תרביע כלאים שדך לא תזרע כלאים ובגד כלאים שעטנז לא יעלה עליך].\nאיז מאי טעמא10, וואָס כלאי בגדים האָט תורה מתיר געמאַכט ביי עבודה במקדש11 (און ביי מצות ציצית), משא\"כ ביי די אַנדערע צוויי מיני כלאים, בבהמה ובקרקע, געפינט מען ניט אַז דאָס זאָל זיין מותר ביי אַ מצוה אָדער ביי קדשים12 (במקדש) וכיו\"ב?\nב. אויסער די ג' מיני כלאים הנ\"ל, איז פאַראַן נאָך אַן איסור וואָס איז דומה בתוכנו צו דעם איסור פון כלאים — בשר וחלב, און ווי ס'איז מבואר אין ספרים13, אַז דער טעם האיסור פון בשר בחלב איז „כסוד הכלאים\" — אַ תערו־בה פון צוויי מינים, וואָס יעדער פאַר זיך איז מותר14, נאָר בהתערבותם יחד",[["1","1","פרשתנו כב, יא."],["2","2","שם, יב."],["3","3","יבמות ד, רע\"א. פרש\"י עה\"פ. רמב\"ם הל' כלאים פ\"י ה\"ד (ובספרי עה\"פ — „שניהם נאמרו בדיבור אחד\". וכ\"ה במכילתא ורש\"י יתרו כ, ח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161237\" data-slug=\"likkutei-sichot\" data-id=\"1300161237\">לקו\"ש חט\"ז ע' 237</a> הערה 41. ואכ\"מ)."],["4","4","ל' רש\"י עה\"פ."],["5","5","רמב\"ם שם ספ\"י. הל' כלי המקדש פ\"ח הי\"א־יב."],["6","6","ל' הבחיי פרשתנו שם, י."],["7","7","ראה בחיי שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241148\" data-slug=\"likkutei-sichot\" data-id=\"1300241148\">לקו\"ש חכ\"ד ע' 148</a>."],["8","8","פרשתנו שם, ט־יא."],["9","9","יט, יט. וצע\"ק טעם שינוי הסדר בהסדרות."],["10","10","אע\"פ שכלאים חוקה היא (קדושים יט, יט ובפרש\"י שם). וראה תו\"כ לאחרי יח, ד* (ובפרש\"י שם), ח' פרקים להרמב\"ם פ\"ו ועוד — נדו\"ד ה\"ז פרט בכלאים. — וראה לקמן סעיף ג ובהערות שם."],["11","11","וי\"ל אשר במקדש ציוותה ע\"ז (ראה לקמן בפנים) ולכן אין שייך לנדו\"ד שה\"ז כדוגמת מליקה בעוף. ועוד. — וראה לקמן הערה 18."],["12","12","ולהעיר מרמב\"ם הל' כלאים פ\"ט הי\"א (בנוגע בהמת פסולי המוקדשין)."],["13","13","רקאנטי משפטים כג, יט* — הובא בשל\"ה חלק תושב\"כ שכא, רע\"א (וראה פסחים מד, ב; נזיר לז, סע\"א: ומאי חידוש . . כלאים נמי. ולהעיר מצפע\"נ הל' מאכא\"ס פ\"ט ה\"א. קונטרס השלמה כג, ב). ד\"ה איתא במד\"ת כשבקשו כו' תרל\"ד (סה\"מ תרל\"ד ס\"ע כט ואילך). ד\"ה כשעלה משה תרס\"ז (נדפס בסוף המשך תרס\"ו — קה\"ת תנש\"א — ע' תרל). לקוטי לוי\"צ על זהר כרך ב (ע' פט). תורת לוי\"צ ע' מה."],["14","14","ראה פסחים ונזיר שם: דהאי לחודי' כו' ובהדדי אסור. *) בהברייתות שנתוספו ע\"פ הילקוט. *) וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460129\" data-slug=\"or-hatorah-hb\" data-id=\"8316460129\">אוה\"ת משפטים (כרך ח ע' ג'קכו</a>) משמע דזוהי כוונת הבחיי משפטים שם (ע\"ש). וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460300\" data-slug=\"or-hatorah-hb\" data-id=\"8316460300\">אוה\"ת תצוה ס\"ע א'תשטז</a>. וראה גם של\"ה שם. ואכ\"מ."]]],[1300291138,"ווערן זיי אַ דבר האסור15.\n— געפינט מען אין מכילתא16, אַז עס איז דאָ אַ קס\"ד אַז בשר בחלב זאָל זיין מותר במוקדשין, נאָר מען דרש'נט דעם פסוק17 „ראשית גו' תביא בית ה' אלקיך לא תבשל גדי בחלב אמו\", אַז אויך אין „בית ה' אלקיך\" איז דאָ דער איסור פון בשר בחלב.\nקומט אויס, אַז עס זיינען פאַראַן דריי חלוקות בדבר:\nביי כלאי בגדים (שעטנז) — האָט די תורה מתיר געמאַכט כלאים ביי עבודת המקדש (ויתרה מזה — געהייסן) און ביי מצות ציצית;\nביי בשר בחלב איז דאָ אַ קס\"ד אַז דאָס זאָל זיין מותר במוקדשין18, נאָר מען לערנט אָפּ פון אַ פסוק אַז עס איז אסור;\nאון ביי כלאי בהמה וכלאי קרקע איז מלכתחילה ניטאָ קיין קס\"ד אַז זיי זאָלן זיין מותר במוקדשין19 — מען דאַרף אפילו ניט קיין לימוד אויף דעם.\nפאָדערט זיך הסברה: וויבאַלד אַז די אַלע אויבנדערמאָנטע איסורים האָבן דעם זעלבן תוכן — תערובות פון שני מינים (וואָס יעדערער פאַר זיך איז היתר) — וואָס איז דער טעם אויף די חילוקים הנ\"ל צווישן זיי בנוגע צו עבודה במקדש וכיו\"ב?\nג. וועט מען עס פאַרשטיין ע\"פ דברי הרמב\"ן20 — אַז דוקא בנוגע צו לבישת שעטנז ווערט דערמאָנט אין חז\"ל21 אַז „יצה\"ר ואומות העולם משי־בים עליהם\", אָבער ניט בנוגע צו כלאי בהמה,\nאון ער איז מבאר, אַז דאָס איז דער־פאַר וואָס ביי כלאי בגדים (שעטנז) איז דער טעם אויפן איסור „נעלם\", משא\"כ ביי כלאי בהמה (ועד\"ז כלאי קרקע) פאַרשטייט מען דעם טעם האיסור:\nדער אויבערשטער האָט באַשאַפן די נבראים אין אַן אופן אַז ער האָט אין די צמחים ובעלי נפש אַריינגעגעבן דעם „כח התולדה שיתקיימו המינים . . וצוה . . שיוציאו למיניהם\". און דעריבער, ווען איינער איז „מערב כלאים\" — ער איז מרכיב שני מיני בהמה, אָדער שני מיני זרעים (וואָס דורך דעם „ישתנו בטבעם גם בצורתם בהיותם יונקים זה מזה, ויהי' כל גרעין ממנו כאילו הורכב משני מינין\") — איז ער „משנה ומכחיש . . ומערבב במעשה בראשית\"21*.",[["15","15","ראה עוד ביאור באיסור בשר בחלב (מפני יניקת הקליפה מהקדושה) — ע\"פ זח\"ב קכד, סע\"ב ואילך — בד\"ה והי' כי תבא (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450566\" data-slug=\"or-hatorah-hb\" data-id=\"8316450566\">אוה\"ת תבא ע' תתרלו</a>. תתרמב ואילך. סה\"מ תרכ\"ז ע' רסב ואילך. סה\"מ תרכ\"ז (קה\"ת תשמ\"א) ע' תעח). המשך חייב אדם לברך תרל\"ח (ע' לא־לב). — והוא ע\"ד הביאור באיסור כלאים שהובא לקמן הערה 39."],["16","16","ס\"פ משפטים."],["17","17","משפטים כג, יט."],["18","18","בתוד\"ה כל הבשר (חולין קג, ב) דהחידוש בזה שבב\"ח נוהג במוקדשין הוא ד„חייל איסור בשר בחלב אאיסור מוקדשין\" (ועפ\"ז אינו שייך לגדר קדשים בפרט, כ\"א לכללות הענין דאין איסור חל על איסור). אבל במכילתא שבפנים מפורש שהקס\"ד היא משום „שכן אסר מליקה בחולין תאמר במוקדשין\"."],["19","19","ואין מביאים קרבנות מכלאים (משנה זבחים רפי\"ד. תמורה יז, א. רמב\"ם הל' איסורי מזבח פ\"ג ה\"ד. שם ה\"י. הל' תמורה פ\"א הי\"ז). ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["20","20","קדושים שם (ועד\"ז בבחיי עה\"פ). וראה השקו\"ט בדברי הרמב\"ן — ברא\"ם, גו\"א, נמוקי שמואל ועוד שם. ואכ\"מ."],["21","21","תו\"כ (ורש\"י) אחרי שבהערה 10. יומא סז, ב (אבל להעיר שבר\"ח שם מביא גם „הרבעת כלאים\"). במדב\"ר פי\"ט, ה. 21*) ראה רמב\"ן שם „וכך אמר כו' חקים שחקקתי בהם את עולמי\" (והוא מירושלמי כלאים פ\"א ה\"ז. ויק\"ר פל\"ה, ד. וראה קידושין לט, א. סנהדרין ס, א (ובתוס' שם))."]]],[1300291139,"[און דאָס וואָס תורה זאָגט אָן ניט נאָר „בהמתך לא תרביע כלאים\", נאָר אויך „לא תחרוש בשור ובחמור יחדיו\" — איז „מפני שדרך כל עובד אדמתו להביא צמדו ברפת אחת ויבואו לידי הרכ־בה\"22].\nקומט אויס אַז עס איז דאָ אַ חילוק עיקרי צווישן כלאי בהמה וכלאי קרקע און כלאי בגדים:\nביי כלאי בהמה וכלאי קרקע איז דער עירוב אויך אין דעם „כח התולדה\" פון די שני מינים, והיינו אַז דער עירוב פועל'ט אין אַן עיקר, אין זייער עצם מציאות, ובמילא איז דאָס בניגוד צו סדרי מעשה בראשית אַז זיי זאָלן זיין „למינהו\" דוקא22*;\nמשא\"כ ביי כלאי בגדים22* איז עס ניט קיין תערובות אין דעם עצם המציאות פון די צמר ופשתים, נאָר בלויז אַן עירוב חיצוני23 — ס'איז נאָר וואָס מ'איז זיי מחבר צוזאַמען אין דעם זעלבן (מקום —) בגד24, אָבער אויך נאָכדעם בלייבן זיי צמר ופשתים (כמו שהיו) — ועד אַז מען קען זיי מפריד זיין איינער פון צווייטן.\nד. לויט דעם איז מובן, אַז דער גדר התערובות ביי בשר בחלב איז ווי אַן אופן הממוצע צווישן די צוויי אופני תערובות הנ\"ל:\nדי תערובות בשר בחלב איז ניט אַזאַ (ווי כלאי בהמה וכו')25 וואָס רירט אָן דעם „כח התולדה\", הגידול והצמיחה לדורות; די תערובות בב\"ח טוט זיך אויף ניט מער ווי אין זייער גשמיות'דיקער מציאות26.\nאָבער לאידך איז עס אויך ניט בדומה צו שעטנז — ווייל ביי שעטנז איז עס ניט קיין עירוב גמור פון די צוויי מינים צמר ופשתים, כנ\"ל, משא\"כ ביי בשר בחלב איז דאָך דער איסור (מה\"ת) דוקא ווען מ'איז זיי מבשל יחד און איינער איז נותן טעם אין דעם צווייטן27; און נאָכ־מער: אפילו ווען „תרו לי' כולי יומא בחלבא\"28 (מען ווייקט בשר בחלב כל היום) — וואָס „יהיב בי' טעמא\"29 היות אַז כבוש כמבושל30 — איז ניטאָ קיין איסור מן התורה, נאָר דוקא דרך בישול אסרה תורה31. ווייל דער איסור בשר בחלב איז שייך נאָר דאַן ווען מען מאַכט פון די צוויי מינים איין (נייע) מציאות32 (וואָס דאָס קומט דוקא דורך בישול).\n[וי\"ל אַז דאָס איז די הסברה33 בדעת",[["22","22","וכ\"כ גם בפרשתנו כב, ח (בסופו). וכ\"ה במו\"נ ח\"ג פמ\"ט. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241149\" data-slug=\"likkutei-sichot\" data-id=\"1300241149\">לקו\"ש חל\"ד ע' 125-26</a>. וראה בארוכה לקו\"ש חכ\"ד (ע' 149 ואילך) שקו\"ט בגדר האיסור דלא תחרוש גו'. 22*) ראה ירושלמי שם „למה מפני שכתוב בהן למיניהן כו'\"."],["23","23","להעיר מרמב\"ן קדושים שם (ד\"ה ובגד כלאים קרוב לסופו): וטעם כלאי הבגדים להרחיק התערובות במינין כו'. וראה נמוקי שמואל שם."],["24","24","וגם לדעת רש\"י (נדה סא, ב — וראה גם פירושו לקדושים יט, יט הנ\"ל) שמה\"ת אסור רק „שוע טווי ונוז\" יחד (וראה תוד\"ה שוע שם. רמב\"ם הל' כלאים פ\"י ה\"ב ובנ\"כ) — ה\"ז רק עירוב חיצוני לגבי כלאי בהמה וקרקע. וראה בארוכה לקו\"ש חל\"ד שם."],["25","25","ולהעיר שבר\"ח יומא שם מביא (בין החוקים) גם „בשר בחלב\". וכ\"ה ברמב\"ם סוף הל' מעילה. וראה הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161242\" data-slug=\"likkutei-sichot\" data-id=\"1300161242\">לקו\"ש חט\"ז ע' 242</a> הערה 11."],["26","26","ולהעיר שרק כלאי בגדים (שעטנז) הוא תערובת שני סוגים — צומח וחי. נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161127\" data-slug=\"likkutei-sichot\" data-id=\"1300161127\">לקו\"ש</a> חל\"ד שם (ע' 127)."],["27","27","ראה רש\"י ד\"ה א\"ל רבא — חולין קח, א."],["28","28","פסחים מד, ב. נזיר לז, סע\"א."],["29","29","רש\"י פסחים שם."],["30","30","ראה תוד\"ה דחדוש — חולין שם."],["31","31","חולין שם."],["32","32","ראה בארוכה צפע\"נ הל' מאכא\"ס וקונטרס השלמה (שצויין בהערה 13), ושם — דבב\"ח הוא „הרכבה מזגיית\", ע\"ש."],["33","33","צפע\"נ שם."]]],[1300291140,"ר' לוי34 אַז דער שיעור כזית פון איסור בשר בחלב, איז אויך ווען ס'איז דאָ בלויז אַ „חצי זית בשר וחצי זית חלב\" (אַ כזית מבין שניהם) — ווייל דער שם איסור לייגט זיך (ניט אויף דעם בשר באַזונדער און דעם חלב באַזונדער, נאָר) אויף ביידע צוזאַמען — ווי זיי זיינען איין מציאות פון בשר בחלב35].\nה. ס'איז ידוע וואָס שטייט אין בחיי36, אַז דער ענין פון איסור כלאים איז (ניט נאָר אַן עירבוב בגשמיות, נאָר אויך) וואָס מ'איז „מערבב הכחות העליונים . . הכלאים . . חיבור שני קצוות שהם שני הפכים . . אין חבורן עולה יפה\"\n[ועד\"ז ביי בשר בחלב איז ער מבאר37, אַז בשר און חלב זיינען אַ „דוגמא ורמז\" צו „דברים מיוחדים\" למעלה, וואָס די תערובות פון בשר בחלב למטה פועל'ט דעם ערבוב פון „דברים ההם (וואָס) כל אחד ואחד (דאַרף זיין) מיוחד בפני עצמו\"].\nאון ווי ס'איז מבואר38, אַז צמר ופשתים (ועד\"ז שור וחמור; בשר און חלב) זיינען מרמז אויף חסד און גבורה וועלכע זיינען מדות הפכיות, און דער־פאַר איז „אין חבורן עולה יפה\"39.\nוע\"פ הנ\"ל (סעיף ג) אין דעם חילוק צווישן כלאי בהמה (וקרקע) און כלאי בגדים — איז מובן, אַז אויך בנוגע דעם „ערבוב\" פון די „כחות העליונים\" (פון חסד וגבורה) וואָס „אין חבורן עולה יפה\", איז דאָ אַ חילוק עיקרי צווישן די צוויי סוגים הנ\"ל (ועד\"ז — בנוגע בשר בחלב).\nו. וועט מען עס פאַרשטיין בהקדם אַ תמי' לכאורה40 אויפן ביאור האמור (אַז „כלאים . . הוא חבור שני קצוות שהם שני הפכים\"):\nמען געפינט אַז אַ חיבור פון שני הפכים איז אדרבא אַ מעלה הכי נפלאה — ענין השלום, וואָס „כל התורה ניתנה לעשות שלום בעולם\"41; און איינער פון די עיקרי העבודה איז צו פועל זיין התכללות המדות\n[וכידוע דער ביאור42 במחז\"ל43",[["34","34","חולין קח, ב. וכ\"ה ההלכה — רמב\"ם הל' מאכא\"ס פ\"ט ה\"א (ובמ\"מ ולח\"מ שם)."],["35","35","וי\"ל שכ\"ה גם לדעת רב (דפליג אלוי), ומה שס\"ל שאינו לוקה — כי לפני הבישול עדיין לא נעשו מציאות אחת חדשה, ועל כל חצי זית לעצמו — א\"א לחול שם האיסור (עיין רש\"י שם ד\"ה לעולם. ולהעיר משו\"ע אדה\"ז או\"ח סתנ\"א סי\"ג בהגה\"ה)."],["36","36","קדושים שם (וראה רמב\"ן שם „ומחברינו מוסיף כו'\", וברמב\"ן שופטים יח, ט) — הובא ונתבאר באוה\"ת פרשתנו (ע' תתקס ואילך). אוה\"ת נ\"ך ע' קלב ואילך. וראה הערה 39."],["37","37","משפטים שם „על דרך הקבלה\" (וראה הנסמן לעיל בשוה\"ג להערה 13)."],["38","38","ראה במקומות שנסמנו בהערה 13."],["39","39","ל' הבחיי קדושים שם. — אבל בבחיי הכוונה (וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560229\" data-slug=\"or-hatorah-hb\" data-id=\"8316560229\">אוה\"ת</a> פרשתנו ונ\"ך שם) — ע\"פ זח\"ג פו, ב ואילך (הובא באוה\"ת פרשתנו ריש ע' תתקס) — ד„כלאים זה מצד הרוח הטובה וזה מצד הרוח הרעה ואנחנו נצטוינו להמשך אחר הרוח הקודש ולהתרחק מן רע . . על כן נאסר לנו הכלאים כי הוא חבור שני קצוות כו'\", היינו שהוא חיבור של רוח הקדושה עם רוח הטומאה (וע\"ד המבואר בהערה 15). וכ\"ה בד\"ה לא תחרוש תרכ\"ז (לענין לא תחרוש גו'). ועוד. ועיין אוה\"ת בראשית (כרך ג) תקפא, א. סד\"ה לא תלבש תרע\"ח: משא\"כ במקומות שנסמנו בהערה 13 מבואר שהאיסור הוא מצד התערובות דחו\"ג. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171228\" data-slug=\"likkutei-sichot\" data-id=\"1300171228\">לקו\"ש חי\"ז ע' 228</a> ואילך (ובהערה 28 שם). חל\"ז ע' 156 ואילך."],["40","40","כמו שהקשה באוה\"ת נ\"ך שם. ד\"ה לא תלבש תרע\"ח ע' תח. וראה מאמרים שנסמנו בהערה 13."],["41","41","רמב\"ם סוף הל' חנוכה."],["42","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380671\" data-slug=\"likkutei-torah\" data-id=\"4001380671\">מטות פז, ב</a> ואילך. ובכ\"מ."],["43","43","תענית כ, סע\"א."]]]]});
